/* UI Field Guide: every term, one S(id, title, icon, blurb, items) call per category. Needs helpers.js. */
/* ---------- content ---------- */
const D=[];
const S=(id,t,ic,blurb,items)=>D.push({id,t,ic,blurb,items});

S('input','Input Controls','pen','Where people type, pick and adjust values.',[
["Text Field","Text Input, Input Box","A single-line box for short text such as a name or an email address.",`<div class="col"><span class="lab">Name</span>${IN('Alex R.')}</div>`],
["Text Area","Multiline Input","A multi-line box for longer text like comments or descriptions, often resizable from its corner.",`<div class="box col" style="width:170px;padding:10px;position:relative">${L(120,'m')}${L(140,'m')}${L(80,'m')}<span style="position:absolute;right:5px;bottom:5px;width:10px;height:10px;background:linear-gradient(135deg,transparent 45%,var(--ink) 45% 58%,transparent 58% 70%,var(--ink) 70% 83%,transparent 83%)"></span></div>`],
["Password Field","Masked Input","A text field that hides each character, usually with an eye icon to show or hide the password.",IN('••••••••','','',I('eye'))],
["Search Field","Search Bar","An input made for searching, with a magnifier icon and a clear (×) button.",IN('sliders','pill',I('search','s'),I('x','s'))],
["Number Input","Numeric Stepper, Spinner","A field that accepts only numbers, with small up and down arrows to nudge the value.",`<span class="inp" style="min-width:92px">12<span class="col" style="gap:0;margin-left:auto">${I('chu','s')}${I('chd','s')}</span></span>`],
["Slider","Range Control","A thumb dragged along a track to choose one value within a range. Drag it.",`<input class="rg" type="range" value="60" aria-label="Slider demo">`],
["Dual Range Slider","Range Slider, Min–Max Slider","A slider with two thumbs for picking a range, like a price from ₱500 to ₱2,000.",`<div class="col" style="width:170px;gap:10px"><span class="dual"><i></i><b style="left:25%"></b><b style="left:75%"></b></span><span class="row sb mono sm"><span>₱500</span><span>₱2,000</span></span></div>`],
["Stepper","Quantity Stepper","Minus and plus buttons that change a value in fixed steps, like an item quantity in a cart. Try it.",`<span class="stepper"><button type="button" data-step="-1" aria-label="Decrease">${I('minus')}</button><b class="val">1</b><button type="button" data-step="1" aria-label="Increase">${I('plus')}</button></span>`],
["Date Picker","Calendar Picker","A field that opens a calendar so people can pick one date instead of typing it.",CAL(d=>d===10?'on':'')],
["Time Picker","Clock Picker","A control for choosing hours and minutes, shown as columns, scroll wheels or a clock face.",`<span class="row mono" style="font-size:22px;font-weight:700"><span class="tbox">09</span>:<span class="tbox">30</span><span class="chip on" style="margin-left:4px">AM</span></span>`],
["Date Range Picker","Range Calendar","Picks a start date and an end date together, shading every day in between.",CAL(d=>d===4||d===9?'on':(d>4&&d<9?'in':''))],
["Color Picker","Swatch Picker","Lets people choose a color from swatches, a hue spectrum, or by typing a hex code.",`<div class="col" style="width:172px;gap:9px"><span class="hue"></span><span class="row" style="gap:5px"><i class="sw" style="background:#e85d4a"></i><i class="sw" style="background:#f2c14e"></i><i class="sw" style="background:#3c8d5a"></i><i class="sw" style="background:#2f5fd0;box-shadow:0 0 0 3px var(--bg),0 0 0 5px var(--ink)"></i><span class="mono sm" style="margin-left:auto">#2F5FD0</span></span></div>`],
["File Upload","Dropzone, File Picker","A button or drag-and-drop area for attaching files from the device.",`<div class="drop">${I('upload')}<span>Drop files or <u>browse</u></span></div>`],
["OTP Input","PIN Input, Code Input","A row of single-character boxes for one-time verification codes; focus jumps to the next box as you type.",`<span class="row">${['4','7','',''].map((c,i)=>`<span class="otp ${i===2?'cur2':''}">${c}</span>`).join('')}</span>`],
["Rich Text Editor","WYSIWYG Editor","A text area with a toolbar for bold, italics, lists and links. WYSIWYG means what you see is what you get.",`<div class="box" style="width:176px;overflow:hidden"><div class="row tb"><b>B</b><i>I</i><u>U</u>${I('list','s')}${I('link','s')}</div><div class="col" style="padding:9px">${L(130)}${L(100,'m')}${L(116,'m')}</div></div>`],
["Autocomplete","Typeahead, Combobox","An input that suggests matching options while you type, so people can pick instead of finishing the word.",`<div class="col" style="gap:0;width:160px">${IN('pal|','','','').replace('class="inp ','class="inp " style="border-radius:10px 10px 0 0" data-x="')}<div class="lbx" style="border-top-width:0;border-radius:0 0 10px 10px"><span class="on">Paladin</span><span>Palette</span><span>Palawan</span></div></div>`],
["Tag Input","Chips Input, Token Field","An input where each entry turns into a removable tag, used for skills, emails or keywords.",`<span class="inp" style="min-width:176px;gap:4px"><span class="chip sm">ui ×</span><span class="chip sm">ux ×</span><span class="chip sm">motion ×</span><span class="caret"></span></span>`],
["Rating Control","Star Rating","Clickable stars or icons for giving a score. Tap a star.",`<span class="row stars">${[1,2,3,4,5].map(n=>`<button type="button" data-star="${n}" class="${n<=3?'on':''}" aria-label="${n} stars">${I('star')}</button>`).join('')}</span>`],
["Signature Pad","Drawing Field","An area where people draw their signature with a finger, stylus or mouse.",`<div class="box" style="width:176px;height:84px;position:relative">${SV(176,84,'<path d="M18 54c10-30 20-30 18 0s14-26 22-10 10 10 20-6 12 18 24 4 14-8 32-6"/><path d="M14 68h148" stroke-width="1.5" stroke-dasharray="4 4"/><path d="M14 60l6 6M20 60l-6 6" stroke-width="2"/>')}</div>`],
["Masked Input","Formatted Input","A field that formats text automatically as you type, like phone numbers or card expiry dates.",`<div class="col"><span class="lab">Mobile number</span>${IN('+63 917 ___ ____')}</div>`]
]);

S('select','Selection Controls','check','Ways to choose one or several options from a set.',[
["Checkbox","Tick Box","Selects zero, one or many options. The dash is the indeterminate state, used when only some sub-items are checked. Tap them.",`<div class="col">${chkRow('Unchecked','')}${chkRow('Checked','on')}${chkRow('Indeterminate','ind')}</div>`],
["Radio Button","Option Button","Round buttons in a group where only one can be selected at a time. Try it.",`<div class="col" data-group>${['Paladin','Mage','Rogue'].map((t,i)=>`<label class="row b sm"><button type="button" class="rad ${i===0?'on':''}" data-rg aria-label="${t}"></button>${t}</label>`).join('')}</div>`],
["Toggle Switch","Switch","An on/off control that takes effect immediately, like a light switch. Flip them.",`<div class="col" style="gap:10px"><span class="row b sm"><button type="button" class="tg on" data-tg aria-label="Notifications"></button>Notifications</span><span class="row b sm"><button type="button" class="tg" data-tg aria-label="Auto-save"></button>Auto-save</span></div>`],
["Dropdown","Select, Picker, Select Menu","A collapsed field that opens a list so people can pick exactly one option.",`<div class="col"><span class="lab">Class</span><span class="inp sb" style="min-width:150px">Paladin${I('chd','s')}</span></div>`],
["Multi-select Dropdown","Multi-select","A dropdown that allows several choices, usually shown as chips inside the field.",`<span class="inp sb" style="min-width:176px"><span class="row" style="gap:4px"><span class="chip sm on">Sword</span><span class="chip sm on">Key</span></span>${I('chd','s')}</span>`],
["Segmented Control","Button Group, Toggle Group","Connected buttons where exactly one segment is active, used to switch views. Try it.",`<span class="seg" data-group>${['Day','Week','Month'].map((t,i)=>`<button type="button" data-rg class="${i===1?'on':''}">${t}</button>`).join('')}</span>`],
["List Box","Selection List","A visible, scrollable list of options with the chosen ones highlighted.",`<div class="lbx" style="min-width:140px"><span>Shield</span><span class="on">Sword</span><span>Potion</span><span>Key</span></div>`],
["Chips","Filter Chips, Choice Chips","Small rounded pills that switch filters or choices on and off. Tap them.",`<span class="row" style="flex-wrap:wrap;width:176px;gap:6px">${['All','Swords','Shields','Potions'].map((t,i)=>`<button type="button" class="chip ${i===1?'on':''}" data-tg>${t}</button>`).join('')}</span>`],
["Transfer List","Dual List Box","Two lists with arrow buttons that move items between “available” and “selected.”",`<span class="row"><span class="lbx" style="min-width:58px"><span>Mace</span><span class="on">Bow</span><span>Axe</span></span><span class="col" style="gap:4px">${CB('chr','sm')}${CB('chl','sm')}</span><span class="lbx" style="min-width:58px"><span>Sword</span><span>Key</span></span></span>`],
["Picker Wheel","Scroll Picker, Spinner Wheel","The rolling wheel common on iOS, where you scroll to bring a value into the center band.",`<div class="wheel"><span>2024</span><span>2025</span><span class="on">2026</span><span>2027</span><span>2028</span></div>`],
["Tree Select","Cascading Select","A dropdown whose options are nested categories you expand to reach the item you want.",`<div class="lbx" style="min-width:150px"><span>▾ Weapons</span><span class="on" style="padding-left:26px">Sword</span><span style="padding-left:26px">Bow</span><span>▸ Items</span></div>`]
]);

S('buttons','Buttons & Actions','sword','Things people press to make something happen.',[
["Primary Button","Main Action","The most emphasized action on a screen. Use only one per view so the next step is obvious.",`<span class="btn fill big">${SP}<span>Increase level</span>${SP}</span>`],
["Secondary Button","Alternative Action","A quieter option next to the primary action, such as Cancel or Back.",`<span class="row">${B('Cancel','soft')}${B('Save','fill')}</span>`],
["Outlined Button","Stroke Button, Ghost Button","A button with a border and no fill, for medium emphasis.",B('Save draft')],
["Text Button","Tertiary Button, Link Button","A button with no border or fill, for the lowest-emphasis actions.",B('Skip for now','text')],
["Icon Button","Icon-only Button","A button that shows only an icon. It needs an accessible label because there is no visible text.",`<span class="row">${CB('heart')}${CB('trash')}${CB('bell')}</span>`],
["Floating Action Button","FAB","A circular button floating above content for the screen’s single most important action.",`<div class="frame">${FL}<span class="fab">${I('plus')}</span></div>`],
["Split Button","Button with Menu","A main action joined to an arrow that opens related actions.",`<span class="split"><span>Export</span><span>${I('chd','s')}</span></span>`],
["Toggle Button","Stateful Button","A button that stays pressed until pressed again, like Bold in a text editor. Try it.",`<span class="row">${['B','I','U'].map((t,i)=>`<button type="button" data-tg class="tbtn ${i===0?'on':''}" style="${['font-weight:900','font-style:italic','text-decoration:underline'][i]}" aria-label="${['Bold','Italic','Underline'][i]}">${t}</button>`).join('')}</span>`],
["Destructive Button","Danger Button","Used for delete or other actions that can’t be undone; usually red so it stands apart.",`<span class="btn danger">${I('trash','s')}Delete</span>`],
["Call to Action","CTA","Any button or link meant to drive the key conversion, such as Buy now or Sign up.",`<div class="col" style="align-items:center"><span class="ln" style="width:120px;height:10px"></span>${L(90,'m t')}<span class="btn fill" style="margin-top:4px">Start free trial</span></div>`],
["Hyperlink","Link","Clickable text that takes people to another page or another place on the page.",`<span class="b" style="font-size:13px;max-width:170px;text-align:center;line-height:1.5">Read the <a class="lk" href="#s-process">style guide</a> before you start.</span>`],
["Speed Dial","Expanding FAB","A floating button that fans out into several smaller related actions.",`<div class="col" style="align-items:center;gap:3px">${CB('img','sm')}${CB('cal','sm')}${CB('pen','sm')}<span class="fab st0" style="width:38px;height:38px">${I('x')}</span></div>`],
["Kebab Menu","Vertical Ellipsis ⋮","A vertical three-dot icon that opens more options.",CB('kebab')],
["Meatball Menu","Horizontal Ellipsis ⋯","A horizontal three-dot icon that opens more options.",CB('meat')],
["Overflow Menu","More Actions Menu","Any menu holding actions that didn’t fit on screen, usually behind a kebab or meatball icon.",`<div class="col" style="align-items:flex-end;gap:4px">${CB('meat','sm')}<div class="lbx"><span>Rename</span><span class="on">Duplicate</span><span>Move to…</span></div></div>`]
]);

S('nav','Navigation','home','How people move around and know where they are.',[
["Navigation Bar","Navbar, Top Bar, Header","The bar across the top of a site with the logo, main links and account controls.",`<div class="box row sb" style="width:180px;padding:7px 10px"><span class="logo-dot"></span><span class="row" style="gap:6px">${L(20,'t')}${L(20,'t m')}${L(20,'t m')}</span><span class="av sm">AR</span></div>`],
["App Bar","Toolbar, Title Bar","A top bar inside an app showing the screen title, a back arrow and a few actions.",`<div class="box row sb" style="width:180px;padding:7px 9px">${I('back','s')}<b class="b">Inventory</b><span class="row" style="gap:6px">${I('search','s')}${I('kebab','s')}</span></div>`],
["Bottom Navigation","Tab Bar","A row of three to five icons at the bottom of a mobile app for its main sections.",`<div class="phone wide">${FL}<div class="bn">${['home','search','heart','user'].map((n,i)=>`<span class="${i===0?'on':''}">${I(n,'s')}</span>`).join('')}</div></div>`],
["Sidebar","Side Navigation, Side Nav","A vertical menu along the left or right edge listing the sections of a site or app.",`<div class="frame" style="display:flex"><div class="side col">${L(30)}${L(40,'m t')}${L(36,'m t')}${L(40,'m t')}</div><div class="col" style="padding:10px;flex:1">${L(80)}${L(90,'m t')}${L(70,'m t')}</div></div>`],
["Navigation Drawer","Slide-out Menu","A sidebar that slides in over the content, usually opened from a hamburger icon.",`<div class="frame">${FL}<span class="scrim"></span><div class="drawer col">${L(40)}${L(52,'m t')}${L(46,'m t')}${L(54,'m t')}</div></div>`],
["Hamburger Menu","☰ Menu Icon","The three-line icon that opens hidden navigation.",CB('menu')],
["Tabs","Tab Strip","Labels that switch between related views in the same space. Try it.",`<span class="tabs" data-group>${['Stats','Gear','Quests'].map((t,i)=>`<button type="button" data-rg class="${i===0?'on':''}">${t}</button>`).join('')}</span>`],
["Breadcrumbs","Breadcrumb Trail","A trail showing where you are in a hierarchy, with each step clickable.",`<span class="row b sm" style="gap:5px"><u>Home</u>${I('chr','xs')}<u>Shop</u>${I('chr','xs')}<b>Shoes</b></span>`],
["Pagination","Pager","Numbered controls that split long content into pages.",`<span class="row pg">${CB('chl','sm')}<span>1</span><span class="on">2</span><span>3</span><span>…</span><span>9</span>${CB('chr','sm')}</span>`],
["Infinite Scroll","Endless Feed","New content loads by itself as people reach the bottom of the list.",`<div class="col" style="width:150px;gap:5px"><div class="box" style="height:20px"></div><div class="box" style="height:20px"></div><div class="box" style="height:20px;opacity:.35"></div><span class="spin sm" style="align-self:center"></span></div>`],
["Load More Button","Show More","A button that fetches the next batch of content only when asked.",`<div class="col" style="width:150px;gap:5px;align-items:center"><div class="box" style="height:20px;width:100%"></div><div class="box" style="height:20px;width:100%"></div>${B('Load more','sm')}</div>`],
["Mega Menu","Large Dropdown","A wide dropdown panel showing many grouped links at once, common on shopping sites.",`<div class="col" style="gap:0"><span class="row b sm" style="gap:12px"><b style="border-bottom:3px solid">Shop</b><span>Sale</span><span>Help</span></span><div class="box mega">${[0,1,2].map(()=>`<span class="col">${L(36)}${L(44,'m t')}${L(30,'m t')}${L(40,'m t')}</span>`).join('')}</div></div>`],
["Dropdown Menu","Menu","A list of actions or links that appears below a trigger button.",`<div class="col" style="gap:4px;align-items:flex-start">${B('Sort by ▾','sm')}<div class="lbx"><span class="on">Newest</span><span>Price, low first</span><span>Price, high first</span></div></div>`],
["Context Menu","Right-click Menu","A menu of actions for the thing under the pointer, opened by right-click or long-press.",`<div style="position:relative;width:176px;height:100px">${CUR(28,10)}<div class="lbx" style="position:absolute;left:44px;top:30px"><span>Copy</span><span class="on">Paste</span><span>Inspect</span></div></div>`],
["Stepper / Wizard","Progress Steps","Numbered steps showing where people are in a multi-step process like checkout.",`<span class="row wz" style="gap:0"><span class="done">${I('check','xs')}</span><i></i><span class="on">2</span><i class="m"></i><span>3</span></span>`],
["Anchor Links","Jump Links, Table of Contents","Links that scroll to sections of the same page, often highlighting the one you’re reading.",`<div class="col toc">${['Overview','Stats','Gear','Quests'].map((t,i)=>`<span class="${i===1?'on':''}">${t}</span>`).join('')}</div>`],
["Back Button","Up Button","Returns to the previous screen.",`<span class="row b">${CB('back')}Back</span>`],
["Skip Link","Skip to Content","A link that appears when you press Tab so keyboard users can jump past the navigation.",`<div class="frame"><span class="skip">Skip to main content</span><div style="padding-top:28px">${FL}</div></div>`],
["Command Palette","Quick Actions, ⌘K Menu","A searchable list of every action, opened with a shortcut like Ctrl+K or ⌘K.",`<div class="box" style="width:180px;overflow:hidden"><div class="row" style="padding:6px 8px;border-bottom:2px solid">${I('search','s')}<span class="mono sm ph" style="flex:1">new…</span><span class="kbd sm">⌘K</span></div><div class="lbx" style="border:0;border-radius:0"><span class="on">New quest</span><span>New item</span><span>New guild</span></div></div>`],
["Navigation Rail","Nav Rail","A slim vertical strip of icons for navigation on tablets and desktops.",`<div class="frame" style="display:flex"><div class="rail">${['home','search','heart','user'].map((n,i)=>`<span class="${i===0?'on':''}">${I(n,'s')}</span>`).join('')}</div><div class="col" style="padding:10px">${L(90)}${L(110,'m t')}${L(70,'m t')}</div></div>`]
]);

S('layout','Containers & Layout','grid','Boxes that hold content and arrange it on the page.',[
["Card","Tile","A bordered box that groups one thing’s image, title, text and actions.",`<div class="box mcard"><div class="mimg">${I('img')}</div><div class="col" style="padding:8px">${L(70)}${L(90,'m t')}<span class="btn fill sm" style="align-self:flex-start;margin-top:3px">Equip</span></div></div>`],
["Panel","Pane","A region of the interface holding related content or controls, often with its own header.",`<div class="box" style="width:164px;overflow:hidden"><div class="row sb" style="padding:5px 8px;border-bottom:2px solid;background:var(--soft)"><b class="b sm">Layers</b>${I('chd','xs')}</div><div class="col" style="padding:9px">${L(110,'m t')}${L(90,'m t')}${L(120,'m t')}</div></div>`],
["Accordion","Collapsible, Expander","Stacked sections that expand and collapse to show or hide their content. Tap a row.",`<div class="acc box">${['What is exp?','How do I level up?'].map((t,i)=>`<div class="acci ${i===0?'on':''}"><button type="button" data-tgp>${t}${I('chd','xs')}</button><div class="accb col">${L(120,'m t')}${L(84,'m t')}</div></div>`).join('')}</div>`],
["Divider","Separator, Rule","A line that separates groups of content, sometimes with a word like “or” in the middle.",`<div class="col" style="width:164px;gap:10px">${L(120,'m')}<span class="row b sm" style="gap:8px"><i class="hr"></i>or<i class="hr"></i></span>${L(100,'m')}</div>`],
["List","List View","Items stacked vertically, each often with an icon or avatar, text and an action.",`<div class="col" style="width:176px;gap:8px">${[0,1,2].map(()=>`<span class="row"><span class="av sm"></span><span class="col" style="gap:3px;flex:1">${L(60,'t')}${L(80,'m t')}</span>${I('chr','xs')}</span>`).join('')}</div>`],
["List Item","Row, Cell","One entry in a list. iOS calls it a cell.",`<span class="row box" style="width:180px;padding:8px;background:var(--soft)"><span class="av sm">AR</span><span class="col" style="gap:3px;flex:1">${L(60,'t')}${L(80,'m t')}</span><span class="tg on"></span></span>`],
["Grid","Grid Layout","Content arranged in rows and columns, like a photo gallery or a product list.",`<div class="ggrid">${'<span></span>'.repeat(6)}</div>`],
["Hero Section","Hero Banner","The large, attention-grabbing area at the top of a landing page.",`<div class="frame col" style="align-items:center;justify-content:center;gap:6px">${SP}<span class="ln" style="width:110px;height:10px"></span>${L(80,'m t')}<span class="btn fill sm">Play now</span></div>`],
["Banner","Announcement Bar","A horizontal strip for announcements or promotions, usually at the top of a page.",`<div class="frame"><div class="ban">${SP} New: dark mode is here ${SP}</div>${FL}</div>`],
["Header & Footer","Page Header, Page Footer","The top and bottom regions of a page, holding branding, navigation and small print.",`<div class="frame col" style="justify-content:space-between;gap:0"><div class="hf row sb"><span class="logo-dot"></span>${L(40,'t')}</div><div class="col" style="padding:0 10px">${L(100,'m t')}${L(80,'m t')}</div><div class="hf row" style="border-top:2px solid;border-bottom:0">${L(30,'t m')}${L(30,'t m')}${L(30,'t m')}</div></div>`],
["Section","Content Block","A themed block of a page with its own heading, stacked one after another.",`<div class="frame col" style="gap:0">${[0,1,2].map(i=>`<div class="col" style="padding:7px 10px;gap:4px;${i?'border-top:2px dashed':''}">${L(50)}${L(120,'m t')}</div>`).join('')}</div>`],
["Container","Wrapper, Max-width","An invisible box that limits how wide content gets and centers it on the page.",`<div class="frame" style="display:grid;place-items:center;border-style:dashed"><div class="box col" style="width:96px;height:70px;padding:8px">${L(50)}${L(70,'m t')}${L(60,'m t')}</div><span class="mono xs" style="position:absolute;left:8px;top:44px">auto</span><span class="mono xs" style="position:absolute;right:8px;top:44px">auto</span></div>`],
["Split View","Split Pane","Two panels side by side, often with a handle you drag to resize them.",`<div class="frame" style="display:flex"><div class="col" style="flex:1;padding:9px">${L(50)}${L(60,'m t')}${L(40,'m t')}</div><div class="handle"></div><div class="col" style="flex:1;padding:9px">${L(50)}${L(60,'m t')}${L(46,'m t')}</div></div>`],
["Master–Detail","List–Detail View","A list on one side; the selected item’s full details show on the other.",`<div class="frame" style="display:flex"><div class="col" style="width:62px;border-right:2px solid;gap:0">${[0,1,2,3].map(i=>`<span style="padding:6px;${i===1?'background:var(--ink)':''}">${L(40,i===1?'inv t':'m t')}</span>`).join('')}</div><div class="col" style="padding:8px;flex:1">${L(60)}<div class="box" style="height:32px;background:var(--soft)"></div>${L(70,'m t')}</div></div>`],
["Carousel","Slider, Slideshow","A rotating set of slides moved with arrows, swipes or dots. Tap the dots.",`<div class="col" style="align-items:center;gap:8px"><div class="row">${CB('chl','sm')}<div class="box" style="width:100px;height:56px;display:grid;place-items:center;background:var(--soft)">${I('img')}</div>${CB('chr','sm')}</div><span class="row dots" data-group>${[0,1,2,3].map(i=>`<button type="button" data-rg class="${i===0?'on':''}" aria-label="Slide ${i+1}"></button>`).join('')}</span></div>`],
["Masonry Layout","Pinterest Grid","Columns where items keep their natural heights and stack tightly with no row gaps.",`<div class="mas">${[34,20,26,22,30,18,24,28].map(h=>`<span style="height:${h}px"></span>`).join('')}</div>`],
["Scroll View","Scroll Area, Scroll Container","A region that scrolls on its own, separately from the rest of the page.",`<div class="box" style="width:156px;height:88px;position:relative;overflow:hidden"><div class="col" style="padding:9px;gap:8px">${L(100,'m t')}${L(110,'m t')}${L(80,'m t')}${L(100,'m t')}${L(70,'m t')}${L(90,'m t')}</div><span class="sbar"></span></div>`],
["Sticky Element","Sticky Header, Pinned Element","An element that stays fixed in place while the rest of the page scrolls under it.",`<div class="frame"><div class="hf row sb" style="background:var(--ink);border-color:var(--ink);position:relative;z-index:1;box-shadow:0 4px 0 var(--soft)"><span class="ln inv" style="width:40px"></span><span class="mono xs" style="color:var(--paper)">pinned</span></div><div class="col" style="padding:8px 10px;gap:8px;opacity:.6">${L(110,'m t')}${L(90,'m t')}${L(120,'m t')}${L(70,'m t')}</div></div>`],
["Bento Grid","Bento Layout","Tiles of different sizes that fit together into one tidy block, like a bento box.",`<div class="bento"><span style="grid-row:span 2" class="d"></span><span></span><span></span><span style="grid-column:span 2"></span><span style="grid-column:span 3"></span></div>`]
]);

S('overlay','Overlays & Pop-ups','layers','Layers that appear above the page for a moment.',[
["Modal","Dialog, Modal Window","A window over the page that blocks everything behind it until it’s closed.",`<div class="frame">${FL}<span class="scrim"></span><div class="dlg col"><span class="row sb">${L(50)}${I('x','xs')}</span>${L(80,'m t')}${L(60,'m t')}<span class="row" style="justify-content:flex-end;gap:4px"><span class="btn xs soft">No</span><span class="btn xs fill">Yes</span></span></div></div>`],
["Alert Dialog","Confirmation Dialog","A modal that asks people to confirm an important or risky action before it happens.",`<div class="frame">${FL}<span class="scrim"></span><div class="dlg col"><b class="b xs">Delete this file?</b><span class="mono xs">This can’t be undone.</span><span class="row" style="justify-content:flex-end;gap:4px"><span class="btn xs">Cancel</span><span class="btn xs danger">Delete</span></span></div></div>`],
["Lightbox","Media Viewer","A modal that shows an image or video large, with the page dimmed behind it.",`<div class="frame">${FL}<span class="scrim" style="background:rgba(0,0,0,.78)"></span><div class="lbimg">${I('img','lg')}</div><span style="position:absolute;right:6px;top:6px;color:#fff">${I('x','s')}</span><span style="position:absolute;left:8px;top:44px;color:#fff">${I('chl','s')}</span><span style="position:absolute;right:8px;top:44px;color:#fff">${I('chr','s')}</span></div>`],
["Popover","Popup Panel","A small floating box attached to an element, holding extra info or controls.",`<div class="col" style="align-items:center;gap:10px"><div class="pop col">${L(80)}${L(100,'m t')}<span class="btn xs fill" style="align-self:flex-end">Got it</span></div>${B('Info','sm')}</div>`],
["Tooltip","Hint","A short label that appears on hover or focus to explain an element.",`<div class="col" style="align-items:center;gap:9px"><span class="tip">Save changes</span>${CB('check')}</div>`],
["Bottom Sheet","Action Sheet","A panel that slides up from the bottom of a mobile screen with options or details.",`<div class="phone"><div class="col" style="padding:8px;gap:5px">${L(30)}${L(44,'m t')}${L(38,'m t')}</div><span class="scrim"></span><div class="sheet"><i class="handlebar"></i>${L(30,'t')}${L(42,'m t')}${L(36,'m t')}</div></div>`],
["Side Sheet","Drawer, Off-canvas Panel","A panel that slides in from the side, often for filters, details or settings.",`<div class="frame">${FL}<span class="scrim"></span><div class="col" style="position:absolute;right:0;top:0;bottom:0;width:80px;background:var(--paper);border-left:var(--bw,2px) solid var(--ink);padding:9px"><span class="row sb">${L(34)}${I('x','xs')}</span>${L(50,'m t')}${L(44,'m t')}<span class="btn xs fill" style="margin-top:auto">Apply</span></div></div>`],
["Overlay","Scrim, Backdrop","The dimmed layer behind a modal or drawer that pushes the page into the background.",`<div class="frame">${FL}<span class="scrim" style="display:grid;place-items:center"><span class="mono sm" style="color:#fff">scrim</span></span></div>`],
["Toast","Toast Message","A brief message that pops up at the edge of the screen and disappears by itself.",`<div class="frame">${FL}<span class="toast">${I('check','xs')} Saved</span></div>`],
["Snackbar","Snackbar with Action","A toast that includes one quick action, usually Undo.",`<div class="frame">${FL}<span class="snack"><span>Message deleted</span><b>UNDO</b></span></div>`],
["Coachmark","Onboarding Tooltip, Product Tour","Highlighted hints that point at features to guide new users.",`<div class="frame">${FL}<span class="ring" style="right:12px;top:8px">${I('bell','xs')}</span><div class="pop up" style="position:absolute;right:8px;top:52px;padding:6px 8px"><span class="b xs">Your alerts live here</span></div></div>`],
["Spotlight","Highlight Overlay","A dark overlay with a cut-out around one element, drawing all attention to it.",`<div class="frame">${FL}<span class="btn xs fill" style="position:absolute;right:24px;bottom:24px">Start</span><span class="scrim" style="background:radial-gradient(circle at 138px 70px,transparent 24px,rgba(0,0,0,.72) 25px)"></span></div>`],
["Cookie Banner","Consent Banner","A notice that asks permission to use cookies or tracking.",`<div class="frame">${FL}<div class="cookie"><span class="b xs">We use cookies.</span><span class="row" style="gap:3px"><span class="btn xs">Decline</span><span class="btn xs fill">Accept</span></span></div></div>`]
]);

S('feedback','Feedback & Status','potion','How the interface tells people what is happening.',[
["Alert","Callout, Inline Message","A colored box in the page for information, success, warning or error messages.",`<div class="callout row">${I('info')}<span class="col" style="gap:5px">${L(80)}${L(110,'m t')}${L(70,'m t')}</span></div>`],
["Notification","Notice, Push Notification","A message that tells people something happened, even outside the app.",`<div class="box row" style="width:180px;padding:8px;align-items:flex-start">${CB('bell','sm fill')}<span class="col" style="gap:4px;flex:1"><b class="b xs">Quest complete</b>${L(90,'m t')}</span><span class="mono xs ph">2m</span></div>`],
["Badge","Counter, Dot Badge","A small number or dot on an icon, such as three unread messages.",`<span class="row" style="gap:22px"><span class="bdg">${CB('bell')}<i>3</i></span><span class="bdg">${CB('chat')}<i class="dot"></i></span></span>`],
["Tag","Label, Pill","A small rounded label for a category or status, such as New or Sale.",`<span class="row" style="gap:6px"><span class="chip on">New</span><span class="chip">Sale</span><span class="chip soft">lv. 4</span></span>`],
["Status Indicator","Status Dot, Presence","A colored dot that shows state at a glance, like online, away or offline.",`<div class="col">${['Online','Away','Offline'].map((t,i)=>`<span class="row b sm"><span class="sd s${i}"></span>${t}</span>`).join('')}</div>`],
["Progress Bar","Linear Progress","A bar that fills to show how much of a task is done.",`<div class="col" style="width:180px;gap:5px"><span class="pbar"><i style="width:42%"></i></span><span class="row sb mono xs"><span>5000 exp</span><span>12000 exp</span></span></div>`],
["Circular Progress","Progress Ring","A ring that fills to show completion; without a percentage it signals ongoing loading.",`<svg viewBox="0 0 60 60" width="72" height="72" aria-hidden="true"><circle cx="30" cy="30" r="24" fill="none" stroke="var(--soft)" stroke-width="7"/><circle cx="30" cy="30" r="24" fill="none" stroke="currentColor" stroke-width="7" stroke-linecap="round" stroke-dasharray="102 151" transform="rotate(-90 30 30)"/><text x="30" y="34" text-anchor="middle" font-size="12" font-family="Courier Prime,monospace" font-weight="700" fill="currentColor">68%</text></svg>`],
["Spinner","Loader, Activity Indicator, Throbber","An animated icon that says “working on it” when the wait time is unknown.",`<span class="spin"></span>`],
["Skeleton Screen","Skeleton Loader, Shimmer","Grey placeholder shapes that hint at the layout while real content loads.",`<div class="row" style="width:176px;align-items:flex-start"><span class="sk" style="width:36px;height:36px;border-radius:50%;flex:none"></span><span class="col" style="flex:1;gap:7px"><span class="sk" style="width:80%"></span><span class="sk" style="height:8px"></span><span class="sk" style="height:8px;width:60%"></span></span></div>`],
["Empty State","Zero State","What shows when there’s no data yet, with a clear next step.",`<div class="col" style="align-items:center;gap:5px">${I('folder','lg')}<b class="b xs">No quests yet</b><span class="btn xs fill">Start a quest</span></div>`],
["Error State","Failure State","What shows when something fails: what went wrong and how to fix it.",`<div class="col" style="align-items:center;gap:5px">${I('warn','lg')}<b class="b xs">Couldn’t load your gear</b><span class="btn xs">Try again</span></div>`],
["Success State","Confirmation","Confirms an action worked, so people know they can move on.",`<div class="col" style="align-items:center;gap:6px"><span class="cb fill" style="width:46px;height:46px">${I('check')}</span><b class="b xs">Level saved</b></div>`],
["Validation Message","Error Text, Helper Text","Small text under an input that explains a rule or what to fix.",`<div class="col" style="gap:4px"><span class="lab">Email</span>${IN('alex@','err')}<span class="errt">${I('warn','xs')} Enter a full email, like name@site.com</span></div>`],
["Inline Validation","Live Validation","Checking input as people type, instead of waiting for them to submit.",`<div class="col" style="gap:4px"><span class="lab">Username</span>${IN('paladin_04','','',`<span class="okc">${I('check','s')}</span>`)}<span class="b xs" style="color:var(--ok)">Username available</span></div>`],
["Pull to Refresh","Swipe to Refresh","Dragging a list down from the top to reload it on mobile.",`<div class="phone" style="width:96px"><div style="display:grid;place-items:center;height:26px">${I('refresh','s')}</div><div class="col" style="padding:6px;gap:5px"><div class="box" style="height:16px"></div><div class="box" style="height:16px"></div><div class="box" style="height:16px"></div></div><span class="touch" style="position:absolute;left:36px;top:46px;width:18px;height:18px"></span></div>`],
["Haptic Feedback","Vibration Feedback","A small vibration that confirms a touch action on phones and controllers.",SV(130,96,'<rect x="47" y="10" width="36" height="76" rx="8" fill="var(--paper)"/><circle cx="65" cy="48" r="6" fill="currentColor" stroke="none"/><path d="M36 30l-6 6 6 6-6 6 6 6M94 30l6 6-6 6 6 6-6 6"/>','0 0 130 96')]
]);

S('data','Data Display','table','Ways to show information people read and compare.',[
["Table","Data Table, Data Grid","Rows and columns of data, often sortable and filterable.",`<table class="tbl"><tr><th>Name</th><th>Lv.</th><th>Exp</th></tr><tr><td>Paladin</td><td>4</td><td>7421</td></tr><tr><td>Mage</td><td>2</td><td>1980</td></tr><tr><td>Rogue</td><td>3</td><td>4102</td></tr></table>`],
["Column Header","Table Header","The label at the top of a table column, often clickable to sort.",`<span class="row th1"><span>Name</span><span class="row" style="gap:3px">Exp ${I('chd','xs')}</span></span>`],
["Sort Indicator","Sort Arrow","An arrow showing whether a column is sorted ascending or descending.",`<span class="row" style="gap:18px"><span class="col" style="align-items:center;gap:3px">${I('chu')}<span class="mono xs">A → Z</span></span><span class="col" style="align-items:center;gap:3px">${I('chd')}<span class="mono xs">Z → A</span></span></span>`],
["Filter Bar","Filters","A row of controls that narrows down the data shown.",`<div class="box row" style="padding:7px 9px;gap:5px">${I('filter','s')}<span class="chip sm on">lv. 4+</span><span class="chip sm">Swords ×</span><span class="b xs" style="text-decoration:underline">Clear</span></div>`],
["Tree View","Hierarchy View","Nested data you expand and collapse, like folders in a file explorer.",`<div class="col mono sm tree" style="gap:4px"><span>${I('chd','xs')}${I('folder','xs')} assets</span><span style="padding-left:18px">${I('chd','xs')}${I('folder','xs')} icons</span><span style="padding-left:36px">${I('img','xs')} sword.svg</span><span style="padding-left:36px">${I('img','xs')} key.svg</span><span>${I('chr','xs')}${I('folder','xs')} fonts</span></div>`],
["Timeline","Activity Log","Events listed in time order along a line.",`<div class="tl">${['Joined the guild','Reached lv. 2','Found the key'].map((t,i)=>`<span class="row"><i class="${i===2?'on':''}"></i><b class="b xs">${t}</b></span>`).join('')}</div>`],
["Avatar","Profile Picture","A person’s photo or initials in a small circle (or rounded square).",`<span class="row"><span class="av">AR</span><span class="av" style="background:var(--soft);color:var(--ink)">${I('user','s')}</span><span class="av" style="border-radius:10px">JM</span></span>`],
["Avatar Group","Avatar Stack","Overlapping avatars that show several people, with a count for the rest.",`<span class="avg">${['AR','JM','KC'].map(t=>`<span class="av">${t}</span>`).join('')}<span class="av" style="background:var(--paper);color:var(--ink);border-color:var(--ink)">+3</span></span>`],
["Stat Card","KPI Card, Metric Tile","A card that highlights one key number and its change.",`<div class="box col" style="padding:10px 16px;gap:2px"><span class="b xs ph">Total exp</span><b class="fr" style="font-size:28px">7,421</b><span class="mono xs">▲ 12% this week</span></div>`],
["Charts & Graphs","Data Visualization","Visual pictures of data: bar, line, pie, donut, area, scatter, heatmap and more.",SV(176,96,'<path d="M14 82h150M14 10v72" stroke-width="2"/><rect x="26" y="48" width="18" height="34" fill="currentColor" stroke="none" rx="3"/><rect x="54" y="30" width="18" height="52" fill="var(--soft)" rx="3"/><rect x="82" y="56" width="18" height="26" fill="currentColor" stroke="none" rx="3"/><rect x="110" y="20" width="18" height="62" fill="var(--soft)" rx="3"/><rect x="138" y="38" width="18" height="44" fill="currentColor" stroke="none" rx="3"/><path d="M35 40L63 22l28 26 28-34 28 18" stroke-dasharray="1 0"/>')],
["Sparkline","Mini Chart","A tiny chart with no axes, shown inline to hint at a trend.",`<span class="row b sm">Exp ${SV(84,26,'<path d="M2 22L12 17 22 19 32 11 42 13 52 7 62 10 74 3"/><circle cx="74" cy="3" r="2.5" fill="currentColor"/>')}</span>`],
["Calendar View","Schedule View","Events laid out on a month, week or day grid.",`<div class="wk">${'MTWTF'.split('').map(d=>`<span class="h">${d}</span>`).join('')}<span></span><span class="ev" style="grid-column:span 2">Raid</span><span></span><span></span><span></span><span></span><span></span><span class="ev">Shop</span><span></span></div>`],
["Kanban Board","Task Board","Columns of draggable cards that move through workflow stages.",`<div class="row kb" style="align-items:flex-start;gap:5px">${[[2,'To do'],[1,'Doing'],[3,'Done']].map(([n,t])=>`<div class="col"><b class="b xs">${t}</b>${'<span></span>'.repeat(n)}</div>`).join('')}</div>`],
["Description List","Key–Value List","Labels paired with their values, like a profile summary.",`<dl class="dl"><dt>Name</dt><dd>Alex</dd><dt>Class</dt><dd>Paladin</dd><dt>Level</dt><dd>4</dd></dl>`],
["Code Block","Code Snippet","Formatted code in a monospace font, often with syntax highlighting and a copy button.",`<pre class="code"><span class="cm">// level up</span>
hero.exp += 500;
if (hero.exp &gt; max) up();</pre>`],
["Blockquote","Pull Quote","Quoted text set apart from the body, usually with a bar or large type.",`<blockquote class="bq">Make the next step obvious.<cite>— field note</cite></blockquote>`],
["Feed","Activity Feed, Stream","A scrolling list of posts or updates, newest first.",`<div class="col" style="width:176px;gap:7px">${[0,1].map(i=>`<div class="box row" style="padding:7px;align-items:flex-start"><span class="av sm"></span><span class="col" style="flex:1;gap:4px">${L(50,'t')}${L(110,'m t')}${L(80,'m t')}</span>${I('heart','xs')}</div>`).join('')}</div>`]
]);

S('media','Media','img','Pictures, video, sound and symbols.',[
["Image","Thumbnail","A picture in the interface; a thumbnail is a small preview that opens a bigger version.",`<span class="row" style="align-items:flex-end"><span class="box" style="width:96px;height:70px;display:grid;place-items:center;background:var(--soft)">${I('img','lg')}</span><span class="box" style="width:40px;height:30px;display:grid;place-items:center;background:var(--soft)">${I('img','s')}</span></span>`],
["Image Gallery","Photo Grid","A collection of images shown as a grid or carousel.",`<div style="display:grid;grid-template-columns:70px 40px 40px;grid-template-rows:38px 38px;gap:5px">${[0,1,2,3,4].map(i=>`<span class="box" style="background:var(--soft);display:grid;place-items:center;${i===0?'grid-row:span 2':''}">${I('img','s')}</span>`).join('')}</div>`],
["Video Player","Media Player","Video with controls for play, pause, seeking, volume and fullscreen.",`<div class="vp"><span class="cb sm">${I('play','xs')}</span><div class="vpc row">${I('play','xs')}<span class="scr"><i style="width:40%"></i><b style="left:40%"></b></span><span class="mono xs">1:24</span>${I('vol','xs')}</div></div>`],
["Scrubber","Seek Bar, Timeline Scrubber","The slider for jumping to any point in video or audio, often with a time preview.",`<div class="col" style="width:176px;gap:6px;padding-top:16px"><span class="scr lt"><i style="width:62%"></i><b style="left:62%"></b><em style="left:62%">2:31</em></span><span class="row sb mono xs"><span>0:00</span><span>4:05</span></span></div>`],
["Audio Player","Sound Player","Playback controls for sound, often with a waveform.",`<div class="box row" style="padding:8px 10px;gap:8px"><span class="cb fill sm">${I('play','xs')}</span><span class="wave">${[6,12,18,10,22,14,8,16,20,10,6,14,18,8].map((h,i)=>`<i style="height:${h}px;${i>5?'opacity:.3':''}"></i>`).join('')}</span><span class="mono xs">0:42</span></div>`],
["Icon","Glyph","A small symbol that stands for an action or object. Pair it with a label when meaning isn’t obvious.",`<span class="row" style="gap:12px">${['sword','potion','key','heart','star'].map(n=>I(n)).join('')}</span>`],
["Illustration","Spot Illustration","Drawn artwork that explains, decorates or sets a mood, often in empty states and onboarding.",SV(140,100,`<path d="M70 12l30 10v24c0 20-14 32-30 40-16-8-30-20-30-40V22z" fill="var(--paper)" stroke-width="3"/><path d="M70 12v74" stroke-width="3"/><path d="M48 32v14c0 12 8 22 22 30" stroke-width="2" stroke-dasharray="1 5"/><path transform="translate(104 8) scale(1)" d="${SPP}" fill="currentColor" stroke="none"/><path transform="translate(20 60) scale(.7)" d="${SPP}" fill="currentColor" stroke="none"/>`)],
["Logo","Brand Mark, Wordmark","The brand’s symbol (mark) and/or its name set in a fixed style (wordmark).",`<span class="row"><span class="logo">${SP}</span><b class="fr" style="font-size:22px">fieldguide</b></span>`],
["Placeholder Image","Image Placeholder","A temporary stand-in box, often with an X and its size, until the real image exists.",`<div class="ph-img"><span class="mono xs">320 × 180</span></div>`],
["Map Embed","Map View","An interactive map inside the page, with pins and zoom controls.",`<div style="position:relative;width:176px;height:96px;border:var(--bw,2px) solid var(--ink);border-radius:12px;overflow:hidden;background:var(--soft)">${SV(176,96,'<path d="M0 64C40 54 60 74 100 44S150 24 176 34" stroke="var(--paper)" stroke-width="9"/><path d="M60 0L82 96" stroke="var(--paper)" stroke-width="7"/>')}<span style="position:absolute;left:84px;top:22px;color:var(--ink)">${I('pin','lg')}</span><span class="col" style="position:absolute;right:6px;top:6px;gap:0"><span class="box" style="border-radius:6px 6px 0 0;padding:2px">${I('plus','xs')}</span><span class="box" style="border-radius:0 0 6px 6px;border-top:0;padding:2px">${I('minus','xs')}</span></span></div>`]
]);

S('forms','Forms','list','How inputs come together to collect information.',[
["Form","Input Form","A group of inputs that collects information and sends it with one button.",`<div class="col" style="width:164px;gap:5px"><span class="lab">Name</span><span class="inp sm2"></span><span class="lab">Email</span><span class="inp sm2"></span><span class="btn fill sm" style="margin-top:3px">Create account</span></div>`],
["Label","Field Label","The text that names an input. Keep it visible, not only inside the field.",`<div class="col" style="gap:7px"><span class="lab hl" style="align-self:flex-start">Character name</span>${IN('Paladin')}</div>`],
["Placeholder Text","Hint Text","Grey example text inside an empty field. It vanishes when you type, so it can’t replace a label.",`<div class="col"><span class="lab">Hero name</span>${IN('<span class="ph hl">e.g. Alex the Brave</span>')}</div>`],
["Floating Label","Animated Label","A label that sits inside the field, then moves up onto the border once you type.",`<div class="col" style="gap:16px"><span class="inp" style="min-width:160px"><span class="ph">Email</span></span><span class="inp" style="min-width:160px;position:relative">alex@site.com<span class="flt">Email</span></span></div>`],
["Helper Text","Hint, Supporting Text","Guidance under an input that explains what to enter before anything goes wrong.",`<div class="col" style="gap:4px"><span class="lab">Password</span>${IN('••••••')}<span class="mono xs ph">At least 8 characters, one number.</span></div>`],
["Required Indicator","Asterisk","A mark, usually *, showing which fields must be filled in.",`<div class="col" style="gap:4px"><span class="lab">Full name <b style="color:var(--danger)">*</b></span>${IN('')}<span class="mono xs ph">* required</span></div>`],
["Fieldset","Field Group","A box that groups related inputs under one caption, like a shipping address.",`<fieldset class="fs"><legend>Shipping address</legend><span class="inp sm2"></span><span class="row" style="gap:5px"><span class="inp sm2"></span><span class="inp sm2"></span></span></fieldset>`],
["Input Adornment","Prefix, Suffix","Icons or text inside a field that add context, such as ₱, @, .com or an eye icon.",`<div class="col">${IN('1,250','','<b>₱</b>')}${IN('mysite','','',`<span class="ph">.com</span>`)}</div>`],
["Character Counter","Character Limit","Shows how many characters you’ve used or have left.",`<div class="col" style="gap:4px;width:176px"><div class="box" style="padding:8px;height:52px"><span class="mono xs">Hero bio goes here…</span></div><span class="mono xs" style="align-self:flex-end">42 / 280</span></div>`],
["Submit & Reset","Form Actions","Buttons that send the form or clear everything in it.",`<span class="row">${B('Reset','text')}${B('Submit','fill')}</span>`],
["Multi-step Form","Form Wizard","A long form split across several screens, with progress shown along the way.",`<div class="col" style="width:176px;gap:6px"><span class="row sb b xs"><span>Step 2 of 3</span><span class="mono">66%</span></span><span class="pbar thin"><i style="width:66%"></i></span><span class="inp sm2"></span><span class="row sb">${B('Back','text sm')}${B('Next','fill sm')}</span></div>`]
]);

S('states','Interaction States','target','How one element looks in each moment of use.',[
["Default","Enabled, Rest","How an element looks when nothing is happening to it.",B('Button')],
["Hover","Mouse-over","How an element changes when the pointer is over it. Touch screens have no hover.",`<span style="position:relative;display:inline-block">${B('Button','hov')}${CUR(66,16)}</span>`],
["Focus","Focus Ring","The outline showing which element the keyboard is on. Never remove it.",B('Button','foc')],
["Active","Pressed","How an element looks while it’s being clicked or tapped.",`<span class="row" style="gap:14px"><span class="btn fill pr0">Rest</span><span class="btn fill pr1">Pressed</span></span>`],
["Selected","Checked, On","Shows an option is chosen.",`<span class="row" style="gap:12px"><span class="chip on">Chosen</span><span class="chk on">${I('check')}</span><span class="rad on"></span></span>`],
["Disabled","Inactive","Greyed out and not interactive. Explain why when it isn’t obvious.",`<span class="row" style="gap:12px">${B('Button','dis')}<span class="tg dis"></span></span>`],
["Loading","Busy","Shows an action is processing, so people don’t press again.",`<span class="btn fill"><span class="spin xs inv"></span>Saving</span>`],
["Error","Invalid","Shows something is wrong with the input and needs fixing.",`<div class="col" style="gap:4px">${IN('alex@','err','',`<span style="color:var(--danger)">${I('warn','s')}</span>`)}<span class="errt">Missing the domain</span></div>`],
["Read-only","View-only","Visible and copyable, but not editable.",IN('Paladin','ro','',I('lock','s'))],
["Visited","Visited Link","A link you’ve already opened, often shown in a different color.",`<span class="col b sm" style="gap:8px"><a class="lk" href="#s-states">Unvisited link</a><a class="lk" href="#s-states" style="color:#7a4bb3">Visited link</a></span>`],
["Dragging","Drop Target","How an item looks while being dragged, and how the place it can land is highlighted.",`<span class="row" style="gap:12px"><span class="box drg row">${I('kebab','xs')}${L(34,'t')}</span><span class="dropt">Drop here</span></span>`],
["Expanded / Collapsed","Open / Closed","Shows whether a section, menu or tree branch is open.",`<div class="box" style="width:150px;overflow:hidden"><div class="row sb b xs" style="padding:7px 9px">Collapsed ${I('chr','xs')}</div><div class="row sb b xs" style="padding:7px 9px;border-top:2px solid">Expanded ${I('chd','xs')}</div><div class="col" style="padding:0 9px 8px">${L(100,'m t')}</div></div>`]
]);

S('gestures','Gestures & Patterns','hand','Movements and recurring interaction patterns.',[
["Tap","Click","The basic press on a button or link.",`<span style="position:relative;display:inline-block">${B('Tap me','fill')}<span class="touch" style="position:absolute;right:-6px;bottom:-10px;width:18px;height:18px"></span></span>`],
["Double-tap","Double-click","Two quick taps, often used to zoom in or to like a photo.",`<span class="row"><span class="touch"></span><span class="touch" style="margin-left:-12px;opacity:.55"></span><span class="mono sm" style="margin-left:14px">×2</span></span>`],
["Long-press","Press and Hold","Holding a finger down to open extra options, like a context menu.",`<span class="col" style="align-items:center;gap:16px"><span class="touch" style="box-shadow:0 0 0 7px var(--soft),0 0 0 10px var(--ink)"></span><span class="mono xs">hold 0.5s</span></span>`],
["Swipe","Swipe Action","A quick slide of a finger, used to delete, archive or move between screens.",`<div class="swp"><span class="del">${I('trash','s')}</span><div class="box row" style="padding:9px;transform:translateX(-52px);position:relative"><span class="av sm"></span><span class="col" style="gap:3px;flex:1">${L(60,'t')}${L(80,'m t')}</span></div><span class="touch" style="position:absolute;left:60px;top:12px;width:16px;height:16px"></span></div>`],
["Drag and Drop","Drag & Drop","Moving an item by grabbing it and releasing it somewhere else.",SV(176,96,'<rect x="8" y="14" width="56" height="34" rx="8" fill="var(--paper)" transform="rotate(-8 36 31)"/><path d="M70 38C100 30 118 44 126 58" stroke-dasharray="3 5"/><path d="M118 56l9 4 1-10"/><rect x="108" y="62" width="60" height="28" rx="8" stroke-dasharray="5 4" fill="var(--soft)"/>')],
["Pinch to Zoom","Pinch, Spread","Two fingers moving apart to zoom in, or together to zoom out.",SV(150,96,'<rect x="38" y="22" width="74" height="52" rx="6" fill="var(--soft)" stroke-width="2" stroke-dasharray="4 3"/><circle cx="50" cy="64" r="9" fill="currentColor" stroke="none"/><circle cx="100" cy="32" r="9" fill="currentColor" stroke="none"/><path d="M42 72L28 86M28 76v10h10M108 24l14-14M112 10h10v10"/>')],
["Scroll","Pan","Moving through content that’s bigger than the screen, up and down or in any direction.",`<div class="phone" style="width:84px"><div class="col" style="padding:8px;gap:6px">${L(50)}${L(60,'m t')}${L(44,'m t')}${L(56,'m t')}${L(40,'m t')}${L(60,'m t')}</div><span class="sbar"></span><span class="touch" style="position:absolute;left:30px;top:40px;width:16px;height:16px"></span><span style="position:absolute;left:31px;top:60px">${I('chd','s')}</span></div>`],
["Hover-reveal","Hover Actions","Actions that appear only when the pointer is over an item. Hover the row.",`<div class="box row hrow" tabindex="0" style="width:176px;padding:8px"><span class="col" style="flex:1;gap:3px">${L(70,'t')}${L(50,'m t')}</span><span class="row acts" style="gap:4px">${CB('pen','sm')}${CB('trash','sm')}</span></div>`],
["Progressive Disclosure","Show More Options","Showing advanced options only when people ask for them. Tap the link.",`<div class="pd col" style="width:170px;gap:7px"><span class="inp sm2"></span><button type="button" data-tgp>Advanced options ${I('chd','xs')}</button><div class="pdb col" style="gap:5px"><span class="row b xs"><span class="tg on"></span>Auto-save</span><span class="row b xs"><span class="tg"></span>Beta tools</span></div></div>`],
["Lazy Loading","Load on Scroll","Loading images and content only when they scroll into view, so pages open faster.",`<div class="col" style="gap:5px">${[0,1,2].map(i=>`<span class="box" style="width:120px;height:24px;display:grid;place-items:center;${i===0?'background:var(--soft)':''}${i===2?'border-style:dashed;opacity:.5':''}">${i===0?I('img','s'):i===1?'<span class="spin xs"></span>':''}</span>`).join('')}</div>`],
["Undo / Redo","History","Reverse the last action, or bring it back.",`<span class="row" style="gap:10px">${CB('undo')}${CB('redo')}<span class="row mono xs" style="gap:3px"><span class="kbd sm">Ctrl</span>+<span class="kbd sm">Z</span></span></span>`],
["Keyboard Shortcuts","Hotkeys","Key combinations that trigger actions without the mouse.",`<span class="row b" style="gap:6px"><span class="kbd">Ctrl</span>+<span class="kbd">K</span></span>`],
["Microinteraction","Micro-animation","A small animated reaction to one action, like a heart that pops. Tap it.",`<button type="button" class="heart" data-tg aria-label="Like">${I('heart')}</button>`],
["Transition","Animation, Motion","Movement between states or screens, such as fade, slide or scale, that shows what changed.",`<span class="row"><span class="box" style="width:36px;height:36px"></span><span class="col" style="align-items:center;gap:2px"><span class="mono xs">ease-out</span>${SV(50,10,'<path d="M2 5h44M40 1l5 4-5 4"/>')}</span><span class="box" style="width:56px;height:56px;background:var(--ink)"></span></span>`],
["Parallax Scrolling","Parallax","Background layers scroll slower than the foreground, creating a sense of depth.",SV(170,96,'<rect x="1" y="1" width="168" height="94" rx="10" fill="var(--paper)" stroke-width="2"/><path d="M2 62L40 26l30 26 30-30 68 42v30H2z" fill="var(--soft)" stroke="none"/><path d="M2 76l34-22 30 18 44-26 58 26v22H2z" fill="currentColor" opacity=".45" stroke="none"/><path d="M2 94V82q60-18 166 2v10z" fill="currentColor" stroke="none"/><text x="128" y="20" font-size="9" font-family="Courier Prime,monospace" fill="currentColor" stroke="none">slow</text>')],
["Onboarding Flow","Welcome Screens","A short series of screens that introduces new users to the app.",`<span class="row" style="gap:6px">${[0,1,2].map(i=>MINI(`<span style="display:grid;place-items:center;height:28px">${i===1?SP:I(['hand','grid','check'][i],'s')}</span>${L(30,'t')}${L(24,'m t')}<span class="row" style="gap:2px;justify-content:center;margin-top:auto">${[0,1,2].map(j=>`<i style="width:${j===i?10:4}px;height:4px;border-radius:2px;background:var(--ink);display:block;${j===i?'':'opacity:.3'}"></i>`).join('')}</span>`)).join('')}</span>`]
]);

S('visual','Visual Design & Layout','palette','The rules of space, type, color and depth.',[
["Grid System","Layout Grid","Columns and rows that everything aligns to, such as a 12-column grid.",`<div class="frame cols">${'<i></i>'.repeat(6)}</div>`],
["Column, Gutter, Margin","Grid Anatomy","Columns hold content, gutters are the gaps between them, margins are the space at the outer edges.",SV(180,96,'<rect x="1" y="1" width="178" height="80" rx="8" fill="var(--paper)" stroke-width="2"/><rect x="14" y="6" width="44" height="70" fill="#c8372d" opacity=".18" stroke="none"/><rect x="68" y="6" width="44" height="70" fill="#c8372d" opacity=".18" stroke="none"/><rect x="122" y="6" width="44" height="70" fill="#c8372d" opacity=".18" stroke="none"/><text x="2" y="93" font-size="8" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">margin</text><text x="24" y="44" font-size="8" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">col</text><text x="58" y="93" font-size="8" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">gutter</text><path d="M63 82v-6M2 82l0-4M14 82v-4" stroke-width="1.5"/>')],
["Padding","Inner Spacing","Space inside an element, between its edge and its content. Margin is the space outside.",`<div class="pad"><em style="top:3px;left:50%;transform:translateX(-50%)">16</em><em style="left:4px;top:50%;transform:translateY(-50%)">16</em><div class="padi">content</div></div>`],
["Spacing Scale","8-point Grid","A fixed set of spacing values, such as 4, 8, 16, 24 and 32, used everywhere for rhythm.",`<div class="col" style="gap:4px">${[4,8,16,24,32,48].map(n=>`<span class="row mono xs" style="gap:6px"><span style="width:18px;text-align:right">${n}</span><i style="display:block;height:8px;width:${n*2.2}px;background:var(--ink);border-radius:2px"></i></span>`).join('')}</div>`],
["Whitespace","Negative Space","Empty space that lets content breathe and makes it easier to read.",`<span class="row" style="gap:10px;align-items:stretch"><span class="box col" style="width:74px;padding:3px;gap:2px">${L(64)}${L(60,'m t')}${L(64,'m t')}${L(54,'m t')}${L(62,'m t')}</span><span class="box col" style="width:74px;padding:14px;gap:8px">${L(40)}${L(46,'m t')}</span></span>`],
["Alignment","Alignment Line","Lining elements up along a shared edge or center so the layout feels orderly.",`<div class="frame" style="padding:12px 0 0 22px"><span style="position:absolute;left:22px;top:0;bottom:0;border-left:1.5px dashed var(--danger)"></span><div class="col">${L(80)}${L(120,'m t')}${L(100,'m t')}<span class="btn xs fill" style="align-self:flex-start">Action</span></div></div>`],
["Visual Hierarchy","Emphasis","Using size, weight, color and position so the most important thing is seen first.",`<div class="col" style="align-items:center;gap:2px"><b class="fr" style="font-size:30px">Paladin</b><span class="mono" style="font-size:15px">lv. 4</span><span class="mono xs ph">7421 exp</span></div>`],
["Typography","Type","How text is set: typeface, weight, size, line height (leading), letter spacing (tracking) and kerning.",`<div class="row" style="gap:12px;align-items:flex-end"><span class="fr" style="font-size:54px;line-height:.9">Aa</span><span class="col mono xs" style="gap:2px"><span>Fraunces Black</span><span>size 54</span><span>leading 0.9</span><span>tracking −1%</span></span></div>`],
["Type Scale","Type Ramp","A set of predefined text sizes, from big headings down to small captions.",`<div class="col" style="gap:3px"><span class="fr" style="font-size:26px;line-height:1">Heading 1</span><span class="fr" style="font-size:18px;line-height:1">Heading 2</span><span style="font-size:13px">Body text</span><span class="mono xs">Caption</span></div>`],
["Color Palette","Color Scheme","The set of colors a product uses: primary, secondary, accent, neutrals and semantic colors for success, error, warning and info.",`<div class="col" style="gap:7px"><span class="row" style="gap:5px"><i class="sw" style="background:var(--ink)"></i><i class="sw" style="background:var(--paper)"></i><i class="sw" style="background:var(--soft)"></i><i class="sw" style="background:var(--mute)"></i></span><span class="row" style="gap:5px"><i class="sw" style="background:#2e9d5b"></i><i class="sw" style="background:#c8372d"></i><i class="sw" style="background:#f2b33d"></i><i class="sw" style="background:#2f5fd0"></i></span><span class="mono xs">neutrals / semantic</span></div>`],
["Contrast","Contrast Ratio","The difference between text and its background. WCAG asks for at least 4.5:1 for body text.",`<span class="row" style="gap:10px"><span class="ctr" style="background:#fff;color:#000">Aa<em>21:1 ✓</em></span><span class="ctr" style="background:#d4d0c6;color:#b1ada4">Aa<em>1.4:1 ✕</em></span></span>`],
["Border Radius","Corner Radius","How rounded an element’s corners are, from square to fully round.",`<span class="row" style="gap:10px;align-items:flex-end">${[[0,'0'],[10,'10'],[99,'full']].map(([r,t])=>`<span class="col" style="align-items:center;gap:4px"><span class="box" style="width:44px;height:44px;border-radius:${r}px;background:var(--soft)"></span><span class="mono xs">${t}</span></span>`).join('')}</span>`],
["Elevation","Shadow, Drop Shadow","Depth shown with shadows, so higher elements sit above lower ones.",`<span class="row" style="gap:14px;align-items:flex-end">${[0,3,7].map((s,i)=>`<span class="col" style="align-items:center;gap:6px"><span class="box" style="width:42px;height:42px;box-shadow:${s}px ${s}px 0 var(--ink)"></span><span class="mono xs">${i}</span></span>`).join('')}</span>`],
["Opacity","Transparency","How see-through an element is, from 0% (invisible) to 100% (solid).",`<span class="row" style="gap:10px">${[100,60,25].map(o=>`<span class="col" style="align-items:center;gap:4px"><span style="width:42px;height:42px;border-radius:10px;background:var(--ink);opacity:${o/100}"></span><span class="mono xs">${o}%</span></span>`).join('')}</span>`],
["Gradient","Color Ramp","A smooth blend between two or more colors.",`<div class="col" style="gap:6px"><span style="display:block;width:170px;height:34px;border:var(--bw,2px) solid var(--ink);border-radius:10px;background:linear-gradient(90deg,var(--ink),var(--paper))"></span><span class="row sb mono xs"><span>0%</span><span>100%</span></span></div>`],
["Visual Styles","Flat, Neumorphism, Glassmorphism, Skeuomorphism, Material","Named looks: flat is plain fills, neumorphism is soft extruded shadows, glassmorphism is frosted see-through layers, skeuomorphism imitates real materials, and Material is Google’s system of layered surfaces.",`<div style="display:grid;grid-template-columns:repeat(2,58px);gap:7px"><span class="vs" style="background:var(--ink);color:var(--paper)">Flat</span><span class="vs" style="background:#e9e5dc;color:#333;box-shadow:4px 4px 8px rgba(0,0,0,.22),-4px -4px 8px #fff">Neumorph</span><span class="vs" style="background:linear-gradient(135deg,#ffb37a,#7a8cff);position:relative;overflow:hidden"><span style="position:absolute;inset:6px;border-radius:7px;background:rgba(255,255,255,.35);border:1px solid rgba(255,255,255,.7);backdrop-filter:blur(4px);display:grid;place-items:center;color:#222">Glass</span></span><span class="vs" style="background:linear-gradient(#f5e6c8,#c9a96e);border:2px solid #7a5a2a;color:#4a3412;box-shadow:inset 0 2px 0 rgba(255,255,255,.6),0 2px 3px rgba(0,0,0,.35)">Skeuo</span></div>`],
["Iconography","Icon System","The shared style rules for all icons: stroke width, corner shape, size and grid.",`<div style="display:grid;grid-template-columns:repeat(4,28px);gap:10px">${['home','search','heart','bell','user','cal','lock','pin'].map(n=>I(n)).join('')}</div>`],
["Z-index","Layering, Stacking Order","Which elements sit on top of others when they overlap.",`<div class="zz"><span style="left:0;top:0">z: 1</span><span style="left:22px;top:18px;background:var(--soft)">z: 2</span><span style="left:44px;top:36px;background:var(--ink);color:var(--paper)">z: 3</span></div>`],
["Above the Fold","First Screen","Content visible without scrolling. Put the most important things here.",`<div class="frame col" style="padding:9px;gap:6px">${L(70)}${L(110,'m t')}<span class="btn xs fill" style="align-self:flex-start">Buy</span><span style="position:absolute;left:0;right:0;top:62px;border-top:2px dashed var(--danger)"></span><span class="mono xs" style="position:absolute;right:6px;top:65px;color:var(--danger)">fold</span><div class="col" style="margin-top:18px;opacity:.35;gap:6px">${L(100,'m t')}${L(80,'m t')}</div></div>`],
["F-pattern & Z-pattern","Scanning Patterns","How eyes tend to scan: an F shape on text-heavy pages and a Z shape on simple layouts.",`<span class="row" style="gap:8px"><span class="frame" style="width:78px;height:86px;padding:8px"><span class="col" style="gap:6px">${L(58)}${L(42)}${L(16)}${L(16)}${L(16)}</span></span><span class="frame" style="width:78px;height:86px">${SV(74,82,'<circle cx="12" cy="12" r="4" fill="currentColor" stroke="none"/><circle cx="62" cy="12" r="4" fill="currentColor" stroke="none"/><circle cx="12" cy="70" r="4" fill="currentColor" stroke="none"/><circle cx="62" cy="70" r="4" fill="currentColor" stroke="none"/><path d="M12 12h50L12 70h50" stroke-dasharray="4 4"/>')}</span></span>`],
["Responsive Design","Fluid Layout","One layout that stretches and rearranges itself to fit any screen size.",SV(176,90,'<rect x="2" y="8" width="104" height="66" rx="6" fill="var(--paper)"/><path d="M40 86h28M54 74v12"/><rect x="114" y="22" width="40" height="56" rx="5" fill="var(--paper)"/><rect x="160" y="42" width="14" height="40" rx="3" fill="var(--paper)"/><path d="M12 20h50M12 30h84M12 40h70" stroke-width="2" opacity=".5"/>')],
["Breakpoints","Screen Size Thresholds","The screen widths where a layout changes, for example mobile, tablet and desktop.",`<div class="col" style="gap:6px;width:180px"><span style="display:block;height:10px;border-radius:99px;background:linear-gradient(90deg,var(--soft) 0 25%,var(--mute) 25% 53%,var(--ink) 53%)"></span><span class="row sb mono xs"><span>360</span><span>768</span><span>1024</span><span>1440</span></span><span class="row sb b xs"><span>mobile</span><span>tablet</span><span>desktop</span></span></div>`],
["Adaptive Design","Fixed Layouts","Separate, fixed layouts designed for specific screen sizes, swapped in as needed.",`<span class="row" style="gap:10px;align-items:flex-end">${MINI(`${L(24)}<span class="box" style="height:18px"></span><span class="box" style="height:18px"></span>`,44,74)}<span class="frame" style="width:110px;height:74px;display:grid;grid-template-columns:30px 1fr;gap:5px;padding:6px"><span style="background:var(--soft);border-radius:4px"></span><span class="col" style="gap:5px"><span class="box" style="height:22px"></span><span class="box" style="height:22px"></span></span></span></span>`],
["Safe Area","Safe Zone","The part of a screen not covered by notches, rounded corners or system bars.",`<div class="phone" style="width:72px;height:118px;border-radius:18px"><span style="position:absolute;left:50%;top:4px;width:26px;height:8px;margin-left:-13px;border-radius:5px;background:var(--ink)"></span><span style="position:absolute;inset:16px 6px 12px;border:1.5px dashed var(--danger);border-radius:6px"></span><span style="position:absolute;left:50%;bottom:4px;width:24px;height:3px;margin-left:-12px;border-radius:2px;background:var(--ink)"></span></div>`],
["Dark Mode & Light Mode","Theming","Alternate color schemes. Tap the smiley in the top bar to switch this page.",`<span class="row" style="gap:0;border:var(--bw,2px) solid var(--ink);border-radius:14px;overflow:hidden"><span style="width:70px;height:70px;background:#fffdf8;color:#000;display:grid;place-items:center;font:900 26px Fraunces,serif">Aa</span><span style="width:70px;height:70px;background:#121110;color:#f4f0e6;display:grid;place-items:center;font:900 26px Fraunces,serif">Aa</span></span>`]
]);

S('process','Design Process','key','The steps and artifacts from first idea to shipped product.',[
["User Research","UX Research","Learning about users through interviews, surveys and observation before deciding what to build.",`<span class="row" style="gap:10px"><span class="col" style="gap:6px"><span class="box" style="padding:6px 10px;border-radius:12px 12px 12px 3px">${L(60,'m t')}</span><span class="box" style="padding:6px 10px;border-radius:12px 12px 3px 12px;background:var(--ink);align-self:flex-end">${L(44,'inv t')}</span></span>${CB('search')}</span>`],
["User Persona","Persona","A fictional profile built from research that represents one type of target user.",`<div class="box col" style="width:150px;padding:9px;gap:5px"><span class="row"><span class="av">AR</span><span class="col" style="gap:2px"><b class="b sm">Alex, 21</b><span class="mono xs">CS student</span></span></span><span class="mono xs">Goal: learn fast</span><span class="mono xs">Pain: no time</span></div>`],
["User Journey Map","Customer Journey","Maps each step a user takes and how they feel at every stage.",SV(180,96,'<path d="M10 70h160" stroke-width="1.5" stroke-dasharray="3 4"/><path d="M14 46C40 20 56 20 70 50s34 30 50 0 30-26 48-30"/><circle cx="14" cy="46" r="5" fill="var(--paper)"/><circle cx="70" cy="50" r="5" fill="currentColor"/><circle cx="120" cy="50" r="5" fill="var(--paper)"/><circle cx="168" cy="20" r="5" fill="currentColor"/><text x="2" y="88" font-size="8" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">find</text><text x="58" y="88" font-size="8" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">try</text><text x="110" y="88" font-size="8" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">buy</text><text x="152" y="88" font-size="8" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">return</text>')],
["User Flow","Task Flow, Flowchart","A diagram of the path a user takes to finish one task, including decisions.",SV(180,90,'<rect x="2" y="32" width="40" height="24" rx="12" fill="var(--paper)"/><path d="M42 44h16M54 40l4 4-4 4"/><path d="M84 22l24 22-24 22-24-22z" fill="var(--paper)"/><path d="M108 44h16M120 40l4 4-4 4"/><rect x="126" y="32" width="50" height="24" rx="5" fill="currentColor"/><text x="8" y="47" font-size="8" fill="currentColor" stroke="none" font-family="Archivo,sans-serif" font-weight="700">Start</text><text x="74" y="47" font-size="8" fill="currentColor" stroke="none" font-family="Archivo,sans-serif" font-weight="700">Log in?</text><text x="134" y="47" font-size="8" fill="var(--paper)" stroke="none" font-family="Archivo,sans-serif" font-weight="700">Home</text>')],
["User Story","Job Story","A one-line need written from the user’s side: As a…, I want…, so that…",`<div class="box" style="width:176px;padding:10px;font:italic 800 12.5px/1.35 Fraunces,serif">As a student, I want to save my progress, so that I can finish later.</div>`],
["Information Architecture","IA","How content is grouped, labeled and organized so people can find things.",SV(180,92,'<rect x="68" y="4" width="44" height="18" rx="5" fill="currentColor"/><path d="M90 22v10M30 32h120M30 32v8M90 32v8M150 32v8"/><rect x="10" y="40" width="40" height="16" rx="5" fill="var(--paper)"/><rect x="70" y="40" width="40" height="16" rx="5" fill="var(--paper)"/><rect x="130" y="40" width="40" height="16" rx="5" fill="var(--paper)"/><path d="M20 56v10M40 56v10M80 56v10M100 56v10M150 56v10"/><rect x="12" y="66" width="16" height="12" rx="3" fill="var(--soft)" stroke-width="1.5"/><rect x="32" y="66" width="16" height="12" rx="3" fill="var(--soft)" stroke-width="1.5"/><rect x="72" y="66" width="16" height="12" rx="3" fill="var(--soft)" stroke-width="1.5"/><rect x="92" y="66" width="16" height="12" rx="3" fill="var(--soft)" stroke-width="1.5"/><rect x="142" y="66" width="16" height="12" rx="3" fill="var(--soft)" stroke-width="1.5"/>')],
["Sitemap","Site Map","A diagram of every page in a site and how they connect.",`<div class="col" style="align-items:center;gap:6px"><span class="chip on">Home</span><span class="row" style="gap:5px"><span class="chip sm">Shop</span><span class="chip sm">Guides</span><span class="chip sm">About</span><span class="chip sm">Cart</span></span><span class="row" style="gap:5px"><span class="chip sm soft">Shoes</span><span class="chip sm soft">Bags</span></span></div>`],
["Card Sorting","Card Sort","A research method where users group topic cards to show how they expect content to be organized.",`<span class="row" style="gap:16px;align-items:flex-start">${[['Shoes','Bags','Hats'],['Help','FAQ']].map((g,i)=>`<span class="col" style="gap:0">${g.map((t,j)=>`<span class="box b xs" style="padding:6px 10px;margin-top:${j?-6:0}px;transform:rotate(${(j%2?3:-4)+i}deg);background:var(--paper)">${t}</span>`).join('')}</span>`).join('')}</span>`],
["Sketch","Paper Sketch","A quick rough drawing of an idea, made fast so it’s cheap to throw away.",SV(170,96,'<path d="M10 12c40-3 110-2 150 1M159 12c2 25 1 50-1 74M158 86c-50 2-100 1-147-1M11 85C9 60 9 35 10 12" stroke-width="2"/><path d="M22 26c20-1 40 0 60 1M22 38c30 1 50 0 80-1M24 52l30 22M54 52L24 74M100 56c10-1 30 0 44 1M100 70c12 1 30 0 40-1"/>')],
["Wireframe","Lo-fi Layout","A simple grey layout skeleton with no colors or styling, focused on structure.",`<div class="frame wire" style="padding:8px;display:grid;grid-template-columns:1fr 1fr;gap:6px"><span style="grid-column:span 2;height:12px"></span><span class="ph-img" style="width:auto;height:44px;border-width:1.5px"></span><span class="col" style="gap:5px;background:none"><span style="height:6px"></span><span style="height:6px;width:70%"></span><span style="height:6px"></span></span><span style="grid-column:span 2;height:12px;width:40%"></span></div>`],
["Mockup","Hi-fi Design","A detailed, static design that looks like the finished product but doesn’t work yet.",`<div class="frame col" style="align-items:center;justify-content:center;gap:5px;background:var(--paper)"><span class="row" style="gap:4px">${SP}<b class="fr" style="font-size:18px">Paladin</b>${SP}</span><span class="mono xs">lv. 4 (7421 exp)</span><span class="pbar thin" style="width:120px"><i style="width:45%"></i></span><span class="btn xs fill">Increase level</span></div>`],
["Prototype","Clickable Prototype","An interactive simulation of the product that people can click through and test.",`<div style="position:relative;width:176px;height:96px"><span style="position:absolute;left:0;top:6px">${MINI(`${L(26)}${L(20,'m t')}<span class="btn xs fill" style="margin-top:auto;font-size:6px;height:14px">Go</span>`,52,84)}</span>${SV(80,40,'<path d="M4 30C26 0 50 0 72 22M64 22h9v-9"/>').replace('<svg','<svg style="position:absolute;left:44px;top:12px"')}<span style="position:absolute;right:0;top:6px">${MINI(`<span style="display:grid;place-items:center;height:30px">${SP}</span>${L(26,'t')}${L(20,'m t')}`,52,84)}</span>${CUR(36,62)}</div>`],
["Lo-fi vs Hi-fi","Fidelity","Low fidelity is rough and fast for exploring; high fidelity is polished and close to final.",`<span class="row" style="gap:8px"><span class="col" style="align-items:center;gap:4px"><span class="frame wire" style="width:74px;height:66px;padding:6px;display:flex;flex-direction:column;gap:5px"><span style="height:20px"></span><span style="height:6px"></span><span style="height:6px;width:60%"></span></span><span class="mono xs">lo-fi</span></span><span class="col" style="align-items:center;gap:4px"><span class="frame" style="width:74px;height:66px;padding:6px;display:flex;flex-direction:column;gap:5px"><span style="height:20px;background:var(--ink);border-radius:5px;display:grid;place-items:center;color:var(--paper)">${SP}</span>${L(50)}<span class="btn xs fill" style="height:13px;font-size:6px">Play</span></span><span class="mono xs">hi-fi</span></span></span>`],
["Mood Board","Inspiration Board","A collage of images, colors, type and textures that sets the visual direction.",`<div style="display:grid;grid-template-columns:repeat(3,48px);grid-auto-rows:30px;gap:5px"><span style="grid-row:span 2;border-radius:8px;background:var(--ink);display:grid;place-items:center;color:var(--paper)">${SP}</span><span style="border-radius:8px;border:var(--bw,2px) solid var(--ink);background:repeating-linear-gradient(45deg,var(--ink) 0 2px,transparent 2px 6px)"></span><span style="border-radius:8px;background:#f2c14e"></span><span class="fr" style="border-radius:8px;border:var(--bw,2px) solid var(--ink);display:grid;place-items:center;font-size:18px">Aa</span><span style="border-radius:8px;border:var(--bw,2px) solid var(--ink);background:radial-gradient(var(--ink) 1.5px,transparent 2px) 0 0/8px 8px"></span></div>`],
["Style Guide","Brand Guidelines","Rules for using colors, fonts, logos and tone consistently.",`<div class="box col" style="padding:10px;gap:6px;width:150px"><span class="row sb"><span class="fr" style="font-size:24px">Aa</span><span class="row" style="gap:3px"><i class="sw" style="background:var(--ink);width:16px;height:16px"></i><i class="sw" style="background:var(--soft);width:16px;height:16px"></i><i class="sw" style="background:#c8372d;width:16px;height:16px"></i></span></span>${B('Button','fill xs')}<span class="mono xs">Rule: one primary per view</span></div>`],
["Design System","Component Library","A full kit of reusable components, tokens and guidelines shared by a whole team, such as Material Design or Apple’s Human Interface Guidelines.",`<div style="display:grid;grid-template-columns:repeat(2,auto);gap:8px;align-items:center;justify-items:center">${B('Button','fill sm')}<span class="tg on"></span><span class="chip">Chip</span><span class="chk on">${I('check')}</span><span class="inp sm2" style="width:80px"></span><span class="av sm">AR</span></div>`],
["Design Tokens","Tokens, Variables","Named values for colors, spacing, type and radius, shared between design files and code.",`<pre class="code" style="font-size:10px">--color-ink:   #000;
--space-md:    16px;
--radius-pill: 999px;
--font-display: Fraunces;</pre>`],
["Component, Variant, Instance","Figma Components","A component is the reusable master; variants are its versions (primary, secondary); an instance is a copy placed in a design.",`<div class="col" style="gap:6px"><span class="row b xs" style="gap:8px">${SV(16,16,'<path d="M8 1l3 3-3 3-3-3zM4 5l3 3-3 3-3-3zM12 5l3 3-3 3-3-3zM8 9l3 3-3 3-3-3z" fill="currentColor" stroke="none"/>')}Component</span><span class="row" style="gap:5px">${B('Primary','fill xs')}${B('Secondary','xs')}</span><span class="row b xs" style="gap:8px">${SV(16,16,'<path d="M8 2l6 6-6 6-6-6z" stroke-width="2"/>')}Instance</span></div>`],
["Auto Layout","Stack Layout","Figma’s feature that stacks items with set spacing and padding, resizing as content changes, much like CSS flexbox.",`<div class="box col" style="padding:10px;gap:0;width:130px;border-style:dashed"><span class="box" style="height:18px;background:var(--soft)"></span><span class="mono xs" style="text-align:center;line-height:12px;color:var(--danger)">↕ 8</span><span class="box" style="height:18px;background:var(--soft)"></span><span class="mono xs" style="text-align:center;line-height:12px;color:var(--danger)">↕ 8</span><span class="box" style="height:18px;background:var(--soft)"></span></div>`],
["Frame","Artboard","The canvas that represents one screen or page in a design file.",`<div class="col" style="gap:3px"><span class="mono xs ph">Desktop — 1440</span><span class="frame" style="width:160px;height:84px;border-radius:2px;border-width:1.5px"></span></div>`],
["Atomic Design","Atoms to Pages","Building interfaces from small to large: atoms, molecules, organisms, templates, then pages.",`<span class="row" style="gap:5px;align-items:center"><span class="col" style="align-items:center;gap:3px"><span class="logo-dot" style="border-radius:50%"></span><span class="mono xs">atom</span></span>›<span class="col" style="align-items:center;gap:3px"><span class="row" style="gap:2px"><span class="inp sm2" style="width:22px"></span><span class="logo-dot"></span></span><span class="mono xs">molecule</span></span>›<span class="col" style="align-items:center;gap:3px"><span class="box col" style="padding:3px;gap:2px;width:32px">${L(20,'t')}${L(14,'m t')}</span><span class="mono xs">organism</span></span>›<span class="col" style="align-items:center;gap:3px"><span class="box" style="width:28px;height:30px;border-style:dashed"></span><span class="mono xs">page</span></span></span>`],
["Usability Testing","User Testing","Watching real people try to complete tasks with your design to see where they struggle.",`<span class="row" style="gap:10px">${CB('eye')}<div class="col">${['Find the shop','Add to cart','Check out'].map((t,i)=>`<span class="row b xs" style="gap:5px">${i<2?`<span class="chk on" style="width:14px;height:14px;border-radius:4px">${I('check')}</span>`:`<span class="chk" style="width:14px;height:14px;border-radius:4px"></span>`}${t}</span>`).join('')}</div></span>`],
["A/B Testing","Split Testing","Showing two versions to different users and measuring which performs better.",`<span class="row" style="gap:8px">${[['A','4.1%',''],['B','6.3%','win']].map(([t,p,w])=>`<span class="box col" style="width:70px;padding:8px;align-items:center;gap:4px;${w?'background:var(--ink);color:var(--paper)':''}"><b class="fr" style="font-size:22px">${t}</b><span class="mono xs">${p}</span>${w?SP:''}</span>`).join('')}</span>`],
["Heuristic Evaluation","Expert Review","Reviewing a design against usability rules of thumb, such as Nielsen’s 10 heuristics.",`<div class="col" style="gap:5px">${[['Shows system status',1],['Speaks the user’s language',1],['Easy to undo',0]].map(([t,ok])=>`<span class="row b xs" style="gap:6px"><span style="color:${ok?'var(--ok)':'var(--danger)'}">${I(ok?'check':'x','s')}</span>${t}</span>`).join('')}</div>`],
["Iteration","Design Loop","Repeating cycles of design, test and refine until the design works.",SV(110,96,'<path d="M55 14a34 34 0 1 1-30 18"/><path d="M18 22l7 10 10-7"/><text x="40" y="44" font-size="9" font-family="Archivo,sans-serif" font-weight="800" fill="currentColor" stroke="none">design</text><text x="44" y="56" font-size="9" font-family="Archivo,sans-serif" font-weight="800" fill="currentColor" stroke="none">test</text><text x="40" y="68" font-size="9" font-family="Archivo,sans-serif" font-weight="800" fill="currentColor" stroke="none">refine</text>')],
["Design Thinking","Human-centered Design","A five-stage approach: empathize, define, ideate, prototype, test.",`<div class="col" style="gap:4px;align-items:flex-start">${['Empathize','Define','Ideate','Prototype','Test'].map((t,i)=>`<span class="chip sm ${i===2?'on':''}" style="margin-left:${i*12}px">${i+1}. ${t}</span>`).join('')}</div>`],
["Double Diamond","Diverge–Converge","A process of opening up then narrowing down, twice: discover, define, develop, deliver.",SV(180,86,'<path d="M4 40L44 10 84 40 44 70z" fill="var(--paper)"/><path d="M94 40L134 10l40 30-40 30z" fill="currentColor"/><path d="M84 40h10"/><text x="10" y="84" font-size="7.5" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">discover</text><text x="52" y="84" font-size="7.5" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">define</text><text x="96" y="84" font-size="7.5" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">develop</text><text x="140" y="84" font-size="7.5" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">deliver</text>')],
["Handoff","Dev Handoff","Delivering final designs, specs and assets to developers so they can build it.",`<span class="row" style="gap:10px"><span class="frame" style="width:62px;height:62px;display:grid;place-items:center">${SP}</span>${SV(36,16,'<path d="M2 8h30M26 3l6 5-6 5"/>')}<span class="cb fill" style="width:52px;height:52px">${I('code')}</span></span>`],
["Redlines","Specs, Annotations","Measurements and notes laid over a design so developers know exact sizes and spacing.",`<div style="position:relative;padding:16px 26px 6px 6px"><span class="btn fill">Increase level</span><span style="position:absolute;left:6px;right:26px;top:6px;border-top:1.5px solid var(--danger)"></span><span class="mono xs" style="position:absolute;left:50%;top:-6px;color:var(--danger);background:var(--bg);padding:0 3px">148</span><span style="position:absolute;right:16px;top:16px;bottom:6px;border-left:1.5px solid var(--danger)"></span><span class="mono xs" style="position:absolute;right:0;top:20px;color:var(--danger)">32</span></div>`],
["MVP","Minimum Viable Product","The simplest version that still delivers real value, shipped first to learn from real users.",`<span class="row" style="gap:6px;align-items:flex-end">${[[30,'v1',1],[44,'v2',0],[60,'v3',0]].map(([s,t,on])=>`<span class="col" style="align-items:center;gap:4px"><span class="box" style="width:${s}px;height:${s}px;${on?'background:var(--ink)':'border-style:dashed'}"></span><span class="mono xs">${t}${on?' ships':''}</span></span>`).join('')}</span>`]
]);

S('principles','UX Principles & Accessibility','access','Why designs work, and how to make them work for everyone.',[
["Affordance","Perceived Affordance","A quality that suggests how something is used; a raised button looks pressable.",`<span class="row" style="gap:16px"><span class="btn fill pr0">Press</span><span class="b sm ph">Press</span></span>`],
["Signifier","Cue","A visible hint that shows where or how to act, like grip dots on a draggable handle.",`<div class="box row" style="width:168px;padding:8px;gap:8px">${SV(10,18,'<circle cx="2" cy="3" r="1.5" fill="currentColor" stroke="none"/><circle cx="8" cy="3" r="1.5" fill="currentColor" stroke="none"/><circle cx="2" cy="9" r="1.5" fill="currentColor" stroke="none"/><circle cx="8" cy="9" r="1.5" fill="currentColor" stroke="none"/><circle cx="2" cy="15" r="1.5" fill="currentColor" stroke="none"/><circle cx="8" cy="15" r="1.5" fill="currentColor" stroke="none"/>')}<span class="col" style="flex:1;gap:3px">${L(60,'t')}${L(40,'m t')}</span><span class="mono xs">drag</span></div>`],
["Feedback","System Response","The interface reacting to every action so people know it worked.",`<span class="row" style="gap:8px">${B('Save','fill sm')}${SV(24,12,'<path d="M2 6h18M15 2l5 4-5 4"/>')}<span class="toast" style="position:static;transform:none">${I('check','xs')} Saved</span></span>`],
["Consistency","Standards","Similar things look and behave the same everywhere, so people learn once.",`<div class="col" style="gap:6px">${['Settings','Profile','Checkout'].map(t=>`<span class="row sb box" style="padding:5px 8px;width:160px"><span class="b xs">${t}</span>${B('Save','fill xs')}</span>`).join('')}</div>`],
["Mental Model","User Expectation","What people believe about how something works, based on past experience.",`<div class="col" style="gap:8px"><span class="row b sm">${CB('trash','sm')} means delete</span><span class="row b sm">${CB('cart','sm')} means buy</span><span class="row b sm">${CB('heart','sm')} means like</span></div>`],
["Cognitive Load","Mental Effort","How much thinking an interface demands. Fewer choices and clear grouping lower it.",`<span class="row" style="gap:12px"><span style="display:grid;grid-template-columns:repeat(4,12px);gap:3px">${'<span style="height:12px;border:1.5px solid var(--ink);border-radius:3px"></span>'.repeat(16)}</span><span class="col" style="gap:4px"><span class="box" style="width:60px;height:14px"></span><span class="box" style="width:60px;height:14px"></span><span class="box" style="width:60px;height:14px;background:var(--ink)"></span></span></span>`],
["Fitts’s Law","Target Acquisition","Bigger and closer targets are faster to hit, so make key buttons large and near.",SV(176,96,'<path d="M20 70L130 40" stroke-dasharray="3 4" stroke-width="1.5"/><path d="M20 70L150 14" stroke-dasharray="3 4" stroke-width="1.5" opacity=".4"/><rect x="112" y="30" width="56" height="22" rx="11" fill="currentColor"/><rect x="148" y="8" width="10" height="10" rx="3" fill="var(--paper)"/><path d="M14 62v18l5-5 3 7 4-2-3-7h7z" fill="var(--paper)" stroke-width="1.8"/><text x="112" y="70" font-size="8" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">big + near = fast</text>')],
["Hick’s Law","Choice Overload","The more choices people have, the longer they take to decide.",`<span class="row" style="gap:14px;align-items:flex-end"><span class="col" style="align-items:center;gap:4px"><span class="row" style="gap:3px"><span class="box" style="width:22px;height:22px"></span><span class="box" style="width:22px;height:22px"></span></span><span class="mono xs">fast</span></span><span class="col" style="align-items:center;gap:4px"><span style="display:grid;grid-template-columns:repeat(4,16px);gap:3px">${'<span class="box" style="height:16px;border-radius:4px"></span>'.repeat(8)}</span><span class="mono xs">slow</span></span></span>`],
["Jakob’s Law","Familiar Patterns","People spend most of their time on other sites, so they expect yours to work the same way.",`<div class="frame"><div class="hf row sb" style="background:var(--paper)"><span class="logo-dot"></span><span class="inp sm2" style="width:70px;height:16px"></span>${I('cart','s')}</div><div class="col" style="padding:8px;gap:5px">${L(90,'m t')}${L(110,'m t')}</div><span class="mono xs" style="position:absolute;left:8px;bottom:6px">logo left, cart right</span></div>`],
["Gestalt Principles","Proximity, Similarity, Closure, Continuity, Figure–Ground","How people group what they see: close items belong together, similar items look related, and the mind completes incomplete shapes.",SV(180,90,'<g fill="currentColor" stroke="none"><circle cx="12" cy="20" r="5"/><circle cx="26" cy="20" r="5"/><circle cx="12" cy="34" r="5"/><circle cx="26" cy="34" r="5"/><circle cx="54" cy="20" r="5"/><circle cx="68" cy="20" r="5"/><circle cx="54" cy="34" r="5"/><circle cx="68" cy="34" r="5"/></g><g><circle cx="100" cy="20" r="5" fill="currentColor"/><circle cx="114" cy="20" r="5" fill="var(--paper)"/><circle cx="100" cy="34" r="5" fill="currentColor"/><circle cx="114" cy="34" r="5" fill="var(--paper)"/></g><path d="M146 12l20 0M174 20l0 18M166 46l-20 0M138 38l0-18" stroke-width="3"/><text x="4" y="70" font-size="8" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">proximity</text><text x="92" y="70" font-size="8" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">similarity</text><text x="138" y="70" font-size="8" fill="currentColor" stroke="none" font-family="Courier Prime,monospace">closure</text>')],
["Touch Target Size","Hit Area","The tappable area of a control. Aim for about 44×44 pt on iOS and 48×48 dp on Android, even if the icon is smaller.",`<span class="bigtgt">${I('x','s')}</span>`],
["Accessibility","a11y","Designing so people with disabilities can use the product: vision, hearing, motor and cognitive needs. a11y is short for the 11 letters between a and y.",`<span class="row" style="gap:10px"><span class="cb fill" style="width:52px;height:52px">${I('access','lg')}</span><b class="fr" style="font-size:28px">a11y</b></span>`],
["WCAG","Web Content Accessibility Guidelines","The standard for web accessibility, now at version 2.2, with three conformance levels: A, AA (the usual target) and AAA.",`<div class="col" style="align-items:center;gap:7px"><b class="fr" style="font-size:24px">WCAG 2.2</b><span class="row" style="gap:5px"><span class="chip">A</span><span class="chip on">AA</span><span class="chip">AAA</span></span></div>`],
["Alt Text","Alternative Text","A text description of an image that screen readers read aloud and that shows if the image fails to load.",`<div class="col" style="gap:5px;align-items:center"><span class="box" style="width:90px;height:44px;display:grid;place-items:center;background:var(--soft)">${I('img')}</span><span class="mono xs">alt="Knight holding a shield"</span></div>`],
["Screen Reader","Assistive Technology","Software that reads the interface aloud, used by blind and low-vision people.",`<span class="row" style="gap:8px">${CB('vol','fill')}<span class="pop" style="padding:6px 9px"><span class="mono xs">“Button, Increase level”</span></span></span>`],
["ARIA Labels","ARIA Attributes","Code attributes that describe elements to assistive technology when the visible UI doesn’t, such as icon-only buttons.",`<pre class="code" style="font-size:10px">&lt;button aria-label="Close"&gt;
  ×
&lt;/button&gt;</pre>`],
["Keyboard Navigation","Tab Order","Using the whole interface with only a keyboard, moving through elements in a logical order with Tab.",`<span class="row" style="gap:14px"><span class="kbd">Tab</span><span class="fnum">${B('Name','sm')}<b>1</b></span><span class="fnum">${B('Save','fill sm')}<b>2</b></span></span>`],
["Dark Patterns","Deceptive Design","Designs that trick people into things they didn’t mean to do. Learn them to avoid them; this one is confirmshaming.",`<div class="box col" style="width:176px;padding:10px;gap:6px;align-items:center"><b class="b sm">Get 10% off?</b>${B('Yes, please','fill sm')}<span class="mono xs ph" style="text-decoration:underline">No thanks, I hate saving money</span></div>`]
]);

/* ---------- 16 more components ---------- */
S('more','More Components','plus','Extra building blocks that show up in real products.',[
["Toolbar","Action Bar","A strip of icon buttons for the most-used actions in a view, like an editor’s formatting bar.",`<div class="box row" style="padding:6px 8px;gap:4px">${['undo','redo','pen','img','link','trash'].map((n,i)=>`<span class="cb sm" style="${i===2?'background:var(--ink);color:var(--paper);':''}${i===1?'margin-right:8px':''}">${I(n)}</span>`).join('')}</div>`],
["Status Bar","System Bar","The phone’s top strip with time, signal, Wi-Fi and battery. Apps draw around it, never over it.",`<div class="phone wide" style="height:64px"><div class="row sb" style="padding:6px 10px;font:800 10px Archivo,sans-serif"><span>9:41</span><span class="row" style="gap:4px">${SV(16,10,'<path d="M1 9h2M5 9V6M9 9V4M13 9V1" stroke-width="2"/>')}${I('wifi','xs')}<span style="width:20px;height:10px;border:1.5px solid var(--ink);border-radius:3px;padding:1px;display:inline-flex"><i style="flex:.7;background:var(--ink);border-radius:1px"></i></span></span></div><div style="padding:6px 10px">${L(90,'m t')}</div></div>`],
["Menu Bar","Application Menu","The row of menus across the top of desktop apps: File, Edit, View, Help.",`<div class="col" style="gap:0;align-items:flex-start"><div class="box row" style="padding:4px 8px;gap:12px;font:700 10.5px Archivo,sans-serif;border-radius:8px"><span>File</span><span style="background:var(--ink);color:var(--paper);padding:1px 5px;border-radius:4px">Edit</span><span>View</span><span>Help</span></div><div class="lbx" style="margin-left:30px;margin-top:3px;font-size:11px"><span>Undo <span class="ph">⌘Z</span></span><span class="on">Copy</span><span>Paste</span></div></div>`],
["Title Bar","Window Chrome","The top of a desktop window with its title and the close, minimize and maximize controls.",`<div class="frame" style="height:88px"><div class="row hf" style="gap:5px"><i class="sd" style="background:#ff5f57;border-color:#c33"></i><i class="sd" style="background:#febc2e;border-color:#c90"></i><i class="sd" style="background:#28c840;border-color:#1a8"></i><b class="b xs" style="margin:0 auto">notes.txt</b></div>${FL}</div>`],
["Ribbon","Ribbon Toolbar","A tabbed toolbar with big grouped buttons, used in Microsoft Office.",`<div class="box" style="width:184px;overflow:hidden"><div class="row b xs" style="gap:10px;padding:4px 8px;border-bottom:2px solid"><b style="border-bottom:3px solid">Home</b><span>Insert</span><span>Layout</span></div><div class="row" style="padding:7px;gap:6px;align-items:stretch">${['copy','pen','img'].map(n=>`<span class="col" style="align-items:center;gap:2px;padding:3px 5px;border-radius:6px;${n==='pen'?'background:var(--soft)':''}">${I(n)}${LB(n)}</span>`).join('')}<span style="width:2px;background:var(--soft)"></span><span class="col" style="gap:4px;justify-content:center">${L(30,'m t')}${L(26,'m t')}${L(32,'m t')}</span></div></div>`],
["Dial","Knob, Rotary Control","A round control you turn to set a value, common in audio and video apps. Drag the slider to turn it.",`<div class="col" style="align-items:center;gap:12px"><span class="knob" style="--a:-45deg"><i></i></span><input class="knobr" type="range" min="-135" max="135" value="-45" aria-label="Turn the dial" style="width:120px;accent-color:var(--ink)"></div>`],
["Spacer","Gap Element","Empty space added on purpose between elements, usually a size from the spacing scale.",`<div class="col" style="gap:0;width:150px"><div class="box" style="height:24px"></div><div style="height:30px;border:1.5px dashed var(--danger);border-width:0 1.5px;margin:0 40%;display:grid;place-items:center"><span class="mono xs" style="color:var(--danger)">24</span></div><div class="box" style="height:24px"></div></div>`],
["Chat Bubble","Message Bubble","A rounded box holding one chat message; yours and theirs sit on opposite sides.",`<div class="col" style="width:178px;gap:6px"><span class="b xs" style="align-self:flex-start;background:var(--soft);padding:7px 10px;border-radius:14px 14px 14px 4px">Raid tonight?</span><span class="b xs" style="align-self:flex-end;background:var(--ink);color:var(--paper);padding:7px 10px;border-radius:14px 14px 4px 14px">Yes, 9pm ✦</span><span class="mono xs ph" style="align-self:flex-end">Seen</span></div>`],
["Message Composer","Chat Input","The bar where you type a message, with buttons to attach files and send.",`<span class="inp pill" style="min-width:184px;padding-right:4px">${I('clip2','s')}<span class="it ph">Message…</span><span class="cb fill sm">${I('send')}</span></span>`],
["Comment Thread","Replies","A comment followed by indented replies, used in docs, posts and code reviews.",`<div class="col" style="width:178px;gap:7px">${[0,1,1].map((d,i)=>`<span class="row" style="align-items:flex-start;margin-left:${d*22}px;gap:6px"><span class="av sm">${['AR','JM','KC'][i]}</span><span class="col" style="gap:3px">${L(70-i*8,'t')}${L(100-d*20,'m t')}</span></span>`).join('')}</div>`],
["Reaction Picker","Emoji Reactions","A small bar of emoji people tap to react without typing. Tap one.",`<span class="row box" style="border-radius:99px;padding:5px 8px;gap:2px">${['👍','❤️','😂','😮','😢'].map(e=>`<button type="button" data-tg class="rx">${e}</button>`).join('')}</span>`],
["Emoji Picker","Emoji Keyboard","A searchable grid of emoji grouped by category.",`<div class="box col" style="width:166px;padding:7px;gap:6px"><span class="inp pill sm2" style="height:24px">${I('search','xs')}<span class="ph mono xs">Search</span></span><span style="display:grid;grid-template-columns:repeat(6,1fr);font-size:17px;text-align:center;gap:2px">${'😀😎🥳🤖👾🔥⚔️🛡️🗝️🧪✨💎'.match(/\p{Extended_Pictographic}\uFE0F?/gu).map(e=>`<span>${e}</span>`).join('')}</span></div>`],
["Share Sheet","Share Menu","A panel listing apps and people you can send something to, plus Copy link.",`<div class="phone" style="width:124px"><div style="padding:8px">${L(60,'m t')}</div><span class="scrim"></span><div class="sheet" style="height:66px;gap:6px"><i class="handlebar"></i><span class="row" style="gap:6px;justify-content:center">${[0,1,2,3].map(i=>`<span class="av sm" style="${i===3?'background:var(--soft);color:var(--ink)':''}">${i===3?'…':''}</span>`).join('')}</span><span class="row b xs" style="gap:4px;justify-content:center">${I('link','xs')} Copy link</span></div></div>`],
["QR Code","Quick Response Code","A square barcode a phone camera reads to open a link, pay, or join Wi-Fi.",QR()],
["CAPTCHA","Bot Check","A challenge that checks a visitor is human, such as a checkbox or picking images. Keep it as light as possible.",`<div class="box row" style="padding:10px 12px;gap:10px"><button type="button" class="chk" data-tg aria-label="I’m not a robot">${I('check')}</button><b class="b sm">I’m not a robot</b>${I('shield')}</div>`],
["Countdown Timer","Timer","Shows time left until something starts or ends, like a sale or an exam.",`<span class="row mono" style="gap:4px;font-weight:700">${[['02','hrs'],['14','min'],['09','sec']].map(([v,l],i)=>`${i?'<b style="font-size:20px">:</b>':''}<span class="col" style="align-items:center;gap:2px"><span class="tbox" style="font-size:22px">${v}</span>${LB(l)}</span>`).join('')}</span>`],
["Order Tracker","Status Tracker","Shows the stages of a delivery or request and which one it’s at now.",`<div class="col" style="gap:6px"><span class="row wz" style="gap:0"><span class="done">${I('check','xs')}</span><i style="width:22px"></i><span class="done">${I('check','xs')}</span><i style="width:22px"></i><span class="on">${I('cart','xs')}</span><i class="m" style="width:22px"></i><span>4</span></span><span class="row sb mono xs"><span>Placed</span><span>Packed</span><span>Shipped</span><span>Here</span></span></div>`],
["Notification Center","Inbox Panel","A panel that collects all notifications in one list, often with tabs for unread and all.",`<div class="box" style="width:184px;overflow:hidden"><div class="row sb" style="padding:6px 8px;border-bottom:2px solid"><b class="b xs">Notifications</b><span class="chip sm on">3 new</span></div>${[1,1,0].map(u=>`<div class="row" style="padding:6px 8px;gap:6px;${u?'':'opacity:.45'}"><span class="sd" style="${u?'background:var(--ink)':''}"></span>${L(120,'m t')}</div>`).join('')}</div>`],
["Scrollbar","Scroll Indicator","The track and draggable thumb showing where you are in scrollable content and how much there is.",`<span class="row" style="gap:6px;align-items:stretch"><span class="box col" style="width:120px;height:92px;padding:8px;gap:8px;overflow:hidden">${L(90,'m t')}${L(70,'m t')}${L(96,'m t')}${L(80,'m t')}${L(60,'m t')}${L(90,'m t')}</span><span style="width:12px;border:2px solid var(--ink);border-radius:99px;position:relative;background:var(--paper)"><i style="position:absolute;left:1px;right:1px;top:22px;height:30px;border-radius:99px;background:var(--ink)"></i></span></span>`],
["Resize Handle","Grip","A corner or edge grip you drag to make a panel, window or text area bigger. Drag the corner.",`<div class="box" style="width:130px;height:80px;position:relative;resize:both;overflow:hidden;min-width:80px;min-height:50px;max-width:200px;max-height:130px"><div style="padding:8px">${L(80,'m t')}</div><span style="position:absolute;right:4px;bottom:4px;width:12px;height:12px;background:linear-gradient(135deg,transparent 45%,var(--ink) 45% 58%,transparent 58% 70%,var(--ink) 70% 83%,transparent 83%);pointer-events:none"></span></div>`],
["Disclosure Widget","Details, Expandable Text","A triangle that reveals more content when clicked, built into HTML as details and summary. Click it.",`<details class="disc"><summary>What drops from bosses?</summary><span class="mono xs">Keys, potions and rare swords.</span></details>`],
["Image Cropper","Crop Tool","A frame with handles you drag over an image to keep only part of it.",`<div style="position:relative;width:170px;height:96px;border-radius:8px;overflow:hidden;background:var(--soft)">${SV(170,96,'<path d="M0 80L50 40l30 24 40-36 50 40v28H0z" fill="currentColor" opacity=".5" stroke="none"/><circle cx="130" cy="22" r="10" fill="currentColor" stroke="none" opacity=".5"/>')}<span style="position:absolute;left:30px;top:16px;width:100px;height:64px;border:2px solid #fff;box-shadow:0 0 0 999px rgba(0,0,0,.45)"></span>${[[30,16],[130,16],[30,80],[130,80]].map(([x,y])=>`<i style="position:absolute;left:${x-5}px;top:${y-5}px;width:10px;height:10px;background:#fff;border:2px solid #000;border-radius:2px"></i>`).join('')}</div>`],
["Inline Edit","Click to Edit","Text that turns into an editable field when you click it. Click the name and type.",`<span class="row" style="gap:8px"><span class="ie" contenteditable="true" spellcheck="false">Paladin</span>${I('pen','s')}</span>`],
["Search Suggestions","Recent Searches","The list under a search field showing recent searches and popular matches before you finish typing.",`<div class="col" style="gap:0;width:176px"><span class="inp" style="border-radius:16px 16px 0 0">${I('search','s')}<span class="it">sw</span></span><div class="lbx" style="border-top-width:0;border-radius:0 0 12px 12px">${[['clock','sword build'],['clock','swamp map'],['search','swords']].map(([i,t],k)=>`<span class="row" style="gap:6px${k===0?';background:var(--soft)':''}">${I(i,'xs')}${t}</span>`).join('')}</div></div>`],
["Floating Toolbar","Bubble Menu","A small toolbar that pops up next to selected text with formatting options.",`<div class="col" style="align-items:center;gap:6px"><span class="row" style="background:var(--ink);color:var(--paper);border-radius:10px;padding:5px 10px;gap:11px;font:15px Fraunces,serif"><b>B</b><i>I</i><u>U</u>${I('link','s')}</span><span class="b sm">Make it <mark style="background:var(--soft);color:var(--ink);padding:1px 2px">really bold</mark> now</span></div>`],
["File Attachment","Attachment Chip, Upload Progress","Shows an attached file’s name, type and size, with progress while it uploads.",`<div class="col" style="gap:6px;width:184px">${[['quest-map.pdf','2.4 MB',100],['intro.mp4','48 MB',62]].map(([n,s,p])=>`<div class="box row" style="padding:6px 8px;gap:8px"><span class="cb sm fill">${I(p<100?'upload':'check')}</span><span class="col" style="gap:4px;flex:1"><span class="row sb"><b class="b xs">${n}</b><span class="mono xs ph">${s}</span></span>${p<100?`<span class="pbar thin" style="height:8px"><i style="width:${p}%"></i></span>`:''}</span></div>`).join('')}</div>`],
["Segmented Progress","Stories Bar","Progress split into segments, like the bars across the top of stories.",`<div class="phone" style="width:86px;background:#141312"><span class="row" style="gap:3px;padding:6px">${[1,1,.4,0].map(f=>`<i style="flex:1;height:3px;border-radius:2px;background:rgba(255,255,255,.3);position:relative;overflow:hidden;display:block"><b style="position:absolute;top:0;bottom:0;left:0;width:${f*100}%;background:#fff"></b></i>`).join('')}</span><span style="display:grid;place-items:center;height:70px;color:#fff">${SP}</span></div>`]
]);

/* ---------- 17 common screens ---------- */
S('screens','Common Screens','phone','Whole screens you’ll design again and again, and what each one needs.',[
["Login Screen","Sign-in Page","Where returning users enter their account details, with links for a forgotten password and for signing up.",SCR(`<b class="fr" style="font-size:15px;text-align:center">Welcome back</b><span class="inp sm2"></span><span class="inp sm2"></span><span class="btn xs fill">Log in</span><span class="mono xs" style="text-align:center;text-decoration:underline">Forgot password?</span>`)],
["Sign-up Screen","Registration","Where new users create an account. Ask for as little as possible up front.",SCR(`<b class="fr" style="font-size:15px;text-align:center">Create account</b><span class="inp sm2"></span><span class="inp sm2"></span><span class="row b xs" style="gap:5px"><span class="chk2 on">${I('check','xs')}</span>I agree to the terms</span><span class="btn xs fill">Sign up</span>`)],
["Forgot Password","Password Reset","Helps people get back into their account, usually by emailing a reset link.",SCR(`<span style="display:grid;place-items:center">${I('lock')}</span><b class="b sm" style="text-align:center">Reset your password</b><span class="inp sm2"></span><span class="btn xs fill">Send reset link</span><span class="mono xs" style="text-align:center;text-decoration:underline">Back to log in</span>`)],
["Dashboard","Overview Screen","Key numbers, charts and recent activity in one view.",SCR(`<span class="row" style="gap:4px">${[0,1,2].map(i=>`<span class="box col" style="flex:1;padding:4px;gap:3px;${i===0?'background:var(--ink)':''}">${L(16,(i===0?'inv ':'')+'t')}${L(28,i===0?'inv':'')}</span>`).join('')}</span>${SV(156,40,'<path d="M2 34L30 22 58 28 86 10 114 16 152 4"/>')}${L(120,'m t')}${L(100,'m t')}`)],
["Settings Screen","Preferences","Grouped options and toggles that control how the app behaves.",SCR(`<b class="b sm">Settings</b>${['Notifications','Dark mode','Language'].map((t,i)=>`<span class="row sb b xs" style="border-bottom:1.5px solid var(--soft);padding:3px 0">${t}${i<2?`<span class="tg ${i===0?'on':''}" style="transform:scale(.7);transform-origin:right"></span>`:I('chr','xs')}</span>`).join('')}`)],
["Profile Page","Account Page","A person’s photo, name, stats and content, with an Edit button for their own profile.",SCR(`<span style="display:grid;place-items:center"><span class="av">AR</span></span><b class="b sm" style="text-align:center">Alex R.</b><span class="row sb mono xs" style="padding:0 10px"><span>12 posts</span><span>340 fans</span></span><span class="btn xs">Edit profile</span>`)],
["Product Detail Page","PDP","Everything about one product: photos, price, options, reviews and Add to cart.",SCR(`<span class="row" style="gap:6px;align-items:stretch;flex:1"><span class="box" style="width:62px;display:grid;place-items:center;background:var(--soft)">${I('img')}</span><span class="col" style="gap:4px;flex:1">${L(60)}<b class="fr" style="font-size:15px">₱1,250</b><span class="row" style="gap:3px"><span class="chip sm">S</span><span class="chip sm on">M</span><span class="chip sm">L</span></span><span class="row" style="gap:1px">${'★★★★☆'}</span></span></span><span class="btn xs fill">Add to cart</span>`)],
["Shopping Cart","Basket, Bag","Lists chosen items with quantities and a subtotal before checkout.",SCR(`${[0,1].map(()=>`<span class="row" style="gap:6px"><span class="box" style="width:24px;height:24px;background:var(--soft)"></span><span class="col" style="gap:3px;flex:1">${L(60,'t')}${L(30,'m t')}</span><span class="mono xs">− 1 +</span></span>`).join('')}<span class="row sb b xs" style="border-top:1.5px solid;padding-top:4px"><span>Subtotal</span><span>₱2,480</span></span><span class="btn xs fill">Checkout</span>`)],
["Checkout","Payment Flow","Where people enter shipping and payment and place the order. Every extra step loses buyers.",SCR(`<span class="pbar thin"><i style="width:66%"></i></span><span class="lab" style="font-size:9px">Payment</span><span class="inp sm2"></span><span class="row" style="gap:4px"><span class="inp sm2"></span><span class="inp sm2"></span></span><span class="row sb b xs"><span>Total</span><span>₱2,580</span></span><span class="btn xs fill">Pay now</span>`)],
["Confirmation Page","Thank-you Page, Receipt","Confirms an order or form went through and says what happens next.",SCR(`<span style="display:grid;place-items:center;margin-top:4px"><span class="cb fill">${I('check')}</span></span><b class="b sm" style="text-align:center">Order placed</b><span class="mono xs" style="text-align:center">#A2091, arrives Friday</span><span class="btn xs fill">Track order</span>`)],
["Search Results","Results Page","Matches for a search, with filters, sorting and a result count.",SCR(`<span class="inp pill sm2" style="height:20px">${I('search','xs')}<span class="mono xs">swords</span></span><span class="row" style="gap:3px"><span class="chip sm on">All</span><span class="chip sm">lv. 4+</span><span class="mono xs ph" style="margin-left:auto">24 results</span></span>${[0,1,2].map(()=>`<span class="row" style="gap:5px"><span class="box" style="width:18px;height:18px;background:var(--soft)"></span>${L(100,'m t')}</span>`).join('')}`)],
["Landing Page","Marketing Page","A page built to convince visitors to take one action, like signing up.",SCR(`<span class="row sb"><span class="logo-dot"></span><span class="btn xs">Log in</span></span><span class="ln" style="width:120px;height:9px;margin:4px auto 0"></span><span style="align-self:center">${L(90,'m t')}</span><span class="btn xs fill" style="align-self:center">Get started</span><span class="row" style="gap:4px;margin-top:auto">${'<span class="box" style="flex:1;height:22px"></span>'.repeat(3)}</span>`)],
["Pricing Table","Plans Page","Plans side by side with prices and features, with one recommended plan highlighted.",`<span class="row" style="gap:4px;align-items:stretch">${[['Free','₱0',0],['Pro','₱199',1],['Team','₱499',0]].map(([n,p,on])=>`<span class="box col" style="width:56px;padding:6px 5px;gap:4px;align-items:center;${on?'background:var(--ink);color:var(--paper);transform:translateY(-6px)':''}"><b class="b xs">${n}</b><b class="fr" style="font-size:14px">${p}</b>${L(36,(on?'inv ':'m ')+'t')}${L(30,(on?'inv ':'m ')+'t')}<span class="btn xs ${on?'':'fill'}" style="${on?'background:var(--paper);color:var(--ink)':''}">Pick</span></span>`).join('')}</span>`],
["Error Page","404 Page, 500 Page","Shown when a page doesn’t exist (404) or the server failed (500). Always offer a way back.",SCR(`<b class="fr" style="font-size:38px;text-align:center;line-height:1;margin-top:4px">404</b><span class="b xs" style="text-align:center">This page wandered off.</span><span class="btn xs fill" style="align-self:center">Go home</span>`)],
["Splash Screen","Launch Screen","The brief screen shown while an app starts, usually just the logo.",`<div class="phone" style="background:var(--ink);color:var(--paper);display:grid;place-items:center"><span class="col" style="align-items:center;gap:6px">${SP.replace('class="sp"','class="sp" style="width:26px;height:26px"')}<span class="mono xs">fieldguide</span></span></div>`],
["Permission Request","Permission Prompt","Asks to use the camera, location or notifications. Explain why before the system pop-up appears.",`<div class="phone" style="width:132px;height:130px"><span class="scrim"></span><div class="dlg col" style="width:104px;align-items:center;text-align:center;gap:4px">${I('pin')}<b class="b xs">Find guilds near you?</b><span class="mono xs" style="font-size:8px">Used only while the app is open.</span><span class="btn xs fill">Allow</span><span class="mono xs">Not now</span></div></div>`],
["Paywall","Upgrade Screen","Shown when a feature needs a paid plan, listing what you get and the price.",SCR(`<span class="row" style="justify-content:center;gap:4px">${SP}<b class="fr" style="font-size:16px">Go Pro</b>${SP}</span>${['Unlimited quests','No ads','Custom themes'].map(t=>`<span class="row b xs" style="gap:5px">${I('check','xs')}${t}</span>`).join('')}<span class="btn xs fill">Start 7-day trial</span><span class="mono xs" style="text-align:center">then ₱199/month</span>`)],
["Inbox","Messages List","A list of conversations or emails with unread markers, previews and timestamps.",SCR(`${[1,1,0,0].map((u,i)=>`<span class="row" style="gap:6px"><span class="av sm">${['JM','KC','AL','RB'][i]}</span><span class="col" style="gap:3px;flex:1">${L(50,u?'t':'m t')}${L(80,'m t')}</span><span class="col" style="align-items:flex-end;gap:2px"><span class="mono xs" style="font-size:8px">${['2m','1h','Tue','Mon'][i]}</span>${u?'<i class="sd" style="width:8px;height:8px;background:var(--ink)"></i>':''}</span></span>`).join('')}`)],
["Help Center","FAQ, Support Page","Answers to common questions, a search box, and a way to contact support.",SCR(`<b class="b sm" style="text-align:center">How can we help?</b><span class="inp pill sm2" style="height:20px">${I('search','xs')}</span>${['Reset password','Refunds'].map(t=>`<span class="row sb b xs" style="border-bottom:1.5px solid var(--soft);padding:2px 0">${t}${I('chd','xs')}</span>`).join('')}<span class="mono xs" style="text-align:center;text-decoration:underline">Contact support</span>`)],
["Leaderboard","Rankings","Ranks people by score and highlights where you stand.",`<div class="col" style="width:176px;gap:4px">${[['1','KC','9,820'],['2','JM','8,410'],['3','AL','7,990'],['12','You','7,421']].map(([r,n,s],i)=>`<span class="row box" style="padding:4px 8px;gap:8px;${i===3?'background:var(--ink);color:var(--paper)':''}"><b class="mono sm" style="width:16px">${r}</b><span class="b xs" style="flex:1">${n}</span><span class="mono xs">${s}</span></span>`).join('')}</div>`],
["Comparison Table","Feature Matrix","A grid comparing options feature by feature with checks and crosses.",`<table class="tbl"><tr><th></th><th>Free</th><th>Pro</th></tr>${[['Quests',1,1],['Themes',0,1],['Export',0,1]].map(([f,a,b])=>`<tr><td>${f}</td><td>${a?'✓':'—'}</td><td>${b?'✓':'—'}</td></tr>`).join('')}</table>`]
]);

/* ---------- 18 layout & css ---------- */
S('css','Layout & CSS','code','The web concepts behind every layout you design. The demos with buttons change live.',[
["Box Model","CSS Box Model","Every element is a box: content, then padding, then border, then margin on the outside.",`<div class="bm m">margin<div class="bm b">border<div class="bm p">padding<div class="bm c">content</div></div></div></div>`],
["Margin","Outer Spacing","Space outside an element’s border that pushes other elements away.",`<div class="col" style="gap:0;width:140px"><div class="box" style="height:26px"></div><div style="height:22px;background:color-mix(in srgb,#f2b33d 30%,transparent);display:grid;place-items:center"><span class="mono xs">margin 16</span></div><div class="box" style="height:26px"></div></div>`],
["Display","Block, Inline, None","How an element flows: block takes a whole row, inline sits inside text, and none hides it completely.",`<div class="col" style="width:180px;gap:5px"><span class="box b xs" style="padding:3px 6px">block</span><span class="b xs">text <span style="border:1.5px solid var(--ink);border-radius:4px;padding:0 3px">inline</span> text <span style="border:1.5px solid var(--ink);border-radius:4px;padding:0 3px">inline</span></span><span class="box b xs dis" style="padding:3px 6px;border-style:dashed">none (hidden)</span></div>`],
["Flexbox","Flex Layout","A layout that lines items up in a row or column and shares out the space. Tap the options.",FXD('justify-content',[['start','flex-start'],['center','center'],['between','space-between']],'justify-content:flex-start;align-items:flex-start')],
["Flex Direction","Row, Column","Sets whether flex items run across in a row or down in a column. Tap to switch.",FXD('flex-direction',[['row','row'],['column','column']],'flex-direction:row;align-items:flex-start')],
["Align Items","Cross-axis Alignment","Lines flex items up along the other direction: top, center, bottom or stretched. Try it.",FXD('align-items',[['start','flex-start'],['center','center'],['end','flex-end']],'align-items:flex-start;height:56px')],
["Flex Wrap","Wrapping","Lets flex items move onto a new line when they run out of room. Tap to compare.",FXD('flex-wrap',[['nowrap','nowrap'],['wrap','wrap']],'flex-wrap:nowrap;overflow:hidden',8)],
["CSS Grid","Grid Layout","A two-dimensional layout of rows and columns you place items into. Tap to change the columns.",`<div class="col" data-demo style="gap:8px;align-items:center"><div class="fx" data-tgt style="display:grid;grid-template-columns:repeat(3,1fr);width:170px">${'<i style="width:auto;height:22px"></i>'.repeat(6)}</div><span class="seg sm" data-group>${[2,3,4].map(n=>`<button type="button" data-rg data-css="grid-template-columns:repeat(${n},1fr)" class="${n===3?'on':''}">${n} cols</button>`).join('')}</span></div>`],
["Grid Areas","Named Areas","Naming parts of a grid, like header, sidebar and main, then placing content by name.",`<div style="display:grid;grid-template-areas:'h h' 's m' 'f f';grid-template-columns:54px 110px;grid-template-rows:22px 50px 20px;gap:4px">${[['h','header'],['s','sidebar'],['m','main'],['f','footer']].map(([a,t])=>`<span class="box mono xs" style="grid-area:${a};display:grid;place-items:center;${a==='m'?'background:var(--soft)':''}">${t}</span>`).join('')}</div>`],
["Gap","Gutter","Space between rows and columns in flex or grid, without adding margins to each item.",`<div style="display:grid;grid-template-columns:repeat(2,56px);gap:14px;position:relative;padding:4px;background:repeating-linear-gradient(45deg,color-mix(in srgb,var(--danger) 25%,transparent) 0 3px,transparent 3px 7px);border-radius:8px">${'<span class="box" style="height:34px;background:var(--paper)"></span>'.repeat(4)}</div>`],
["Position: Relative","Relative Positioning","Nudges an element from where it would normally sit, and makes it the anchor for absolutely positioned children.",`<div style="position:relative;width:150px;height:80px"><span class="box" style="position:absolute;left:20px;top:20px;width:80px;height:40px;border-style:dashed;opacity:.5"></span><span class="box" style="position:absolute;left:44px;top:34px;width:80px;height:40px;background:var(--ink)"></span><span class="mono xs" style="position:absolute;left:0;top:0">top:14 left:24</span></div>`],
["Position: Absolute","Absolute Positioning","Takes an element out of the flow and places it at exact offsets inside its positioned parent, like a badge on an icon.",`<div class="frame" style="width:150px;height:84px">${FL}<span class="chip sm on" style="position:absolute;right:8px;top:8px">NEW</span><span style="position:absolute;right:30px;top:0;height:8px;border-left:1.5px dashed var(--danger)"></span><span style="position:absolute;right:0;top:16px;width:8px;border-top:1.5px dashed var(--danger)"></span></div>`],
["Position: Fixed","Fixed Positioning","Pins an element to the screen itself so it stays put while the page scrolls, like a chat button.",`<div class="phone" style="width:90px"><div class="col" style="padding:8px;gap:7px;opacity:.5">${L(60)}${L(70,'m t')}${L(50,'m t')}${L(66,'m t')}${L(40,'m t')}</div><span class="fab" style="width:30px;height:30px;right:6px;bottom:6px">${I('chat','s')}</span><span class="mono xs" style="position:absolute;left:6px;bottom:10px">fixed</span></div>`],
["Position: Sticky","Sticky Positioning","Acts normal until you scroll past it, then sticks to an edge, like a table header.",`<div class="frame" style="width:150px;height:96px"><div class="hf row sb" style="background:var(--ink);border-color:var(--ink)"><span class="b xs" style="color:var(--paper)">Name</span><span class="b xs" style="color:var(--paper)">Exp</span></div>${['Paladin','Mage','Rogue','Bard'].map(n=>`<div class="row sb mono xs" style="padding:3px 8px;border-bottom:1px solid var(--soft)"><span>${n}</span><span>${Math.round(RND(1,n.length)[0]*9000)}</span></div>`).join('')}</div>`],
["Overflow","Visible, Hidden, Scroll","What happens when content is bigger than its box: it spills out, gets clipped, or scrolls.",`<span class="row" style="gap:8px;align-items:flex-start">${[['visible','visible'],['hidden','hidden'],['scroll','auto']].map(([l,v])=>`<span class="col" style="align-items:center;gap:4px"><span class="box mono xs" style="width:50px;height:40px;padding:4px;overflow:${v};line-height:1.2;font-size:9px">Lots of text that keeps going on</span><span class="mono xs" style="margin-top:${v==='visible'?16:0}px">${l}</span></span>`).join('')}</span>`],
["Text Truncation","Ellipsis","Cutting off text that doesn’t fit and ending it with an ellipsis (…).",`<span class="box b xs" style="display:block;width:140px;padding:7px 9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">The legendary sword of the broken kingdom</span>`],
["Line Clamp","Multi-line Truncation","Limiting text to a set number of lines, with an ellipsis after the last one.",`<div class="col" style="gap:4px;align-items:flex-start"><span class="box" style="display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;width:160px;padding:7px 9px;font:12px/1.4 Archivo,sans-serif">A paladin who swore to protect the guild and every traveler on the long road north.</span>${LB('clamped to 2 lines')}</div>`],
["Aspect Ratio","Ratio Box","Keeps a box’s width-to-height proportion at any size, such as 16:9 for video.",`<span class="row" style="gap:8px;align-items:flex-end">${[['16:9','16/9',72],['1:1','1/1',44],['9:16','9/16',36]].map(([l,r,w])=>`<span class="col" style="align-items:center;gap:4px"><span class="box" style="width:${w}px;aspect-ratio:${r};background:var(--soft)"></span>${LB(l)}</span>`).join('')}</span>`],
["Object Fit","Cover, Contain","How an image fills its box: cover crops it to fill, contain shows all of it with empty space around.",`<span class="row" style="gap:10px">${[['cover','160%'],['contain','100%']].map(([l,s])=>`<span class="col" style="align-items:center;gap:4px"><span class="box" style="width:70px;height:56px;overflow:hidden;display:grid;place-items:center;background:var(--soft)"><span style="width:${s};aspect-ratio:${l==='cover'?'1/1':'4/3'};max-width:${l==='cover'?'none':'100%'};background:var(--ink);display:grid;place-items:center;color:var(--paper);flex:none">${SP}</span></span>${LB(l)}</span>`).join('')}</span>`],
["Viewport","Visible Area","The part of the page visible in the browser window or on the phone screen right now.",`<div style="position:relative;width:100px;height:110px;border:2px dashed var(--mute);border-radius:8px;padding:6px" class="col">${L(70)}${L(80,'m t')}${L(60,'m t')}${L(80,'m t')}${L(70,'m t')}${L(60,'m t')}${L(76,'m t')}<span style="position:absolute;left:-6px;right:-6px;top:26px;height:50px;border:var(--bw,2px) solid var(--ink);border-radius:8px;background:color-mix(in srgb,var(--ink) 8%,transparent)"></span><span class="mono xs" style="position:absolute;right:-56px;top:44px">viewport</span></div>`],
["Media Query","Breakpoint Rule","CSS that only applies when the screen matches a condition, like a minimum width.",CODE(`@media (min-width: 768px) {
  .cards {
    grid-template-columns: 1fr 1fr;
  }
}`)],
["Container Query","Component-level Responsiveness","CSS that adapts a component to the width of its own container instead of the whole screen.",`<span class="row" style="gap:8px;align-items:flex-start"><span class="box col" style="width:50px;padding:5px;gap:4px"><span style="height:24px;background:var(--soft);border-radius:4px"></span>${L(36,'t')}${L(30,'m t')}</span><span class="box row" style="width:110px;padding:5px;gap:5px"><span style="width:36px;height:36px;background:var(--soft);border-radius:4px"></span><span class="col" style="gap:4px">${L(50,'t')}${L(40,'m t')}</span></span></span>`],
["Mobile-first","Mobile-first Design","Designing the small-screen version first, then adding layout as screens get bigger.",`<span class="row" style="gap:6px;align-items:flex-end">${MINI(L(20,'t'),30,52)}${SV(16,10,'<path d="M2 5h10M9 2l3 3-3 3"/>')}<span class="frame" style="width:48px;height:62px"></span>${SV(16,10,'<path d="M2 5h10M9 2l3 3-3 3"/>')}<span class="frame" style="width:84px;height:58px"></span></span>`],
["Fluid Typography","clamp()","Text that grows smoothly with the screen between a minimum and a maximum size.",`<div class="col" style="gap:6px;align-items:center"><span class="row" style="gap:10px;align-items:baseline"><span class="fr" style="font-size:16px">Aa</span><span class="fr" style="font-size:24px">Aa</span><span class="fr" style="font-size:34px">Aa</span></span>${CODE('font-size: clamp(16px, 4vw, 34px);')}</div>`],
["Min & Max Width","Size Limits","Rules that stop an element getting too narrow or too wide, like a max-width that keeps text lines readable.",SV(180,60,`<path d="M10 30h160" stroke-width="2"/><path d="M40 20v20M150 20v20" stroke="#c8372d"/>${TX(40,14,'min 240',8,'middle')}${TX(150,14,'max 720',8,'middle')}<rect x="60" y="24" width="70" height="12" rx="6" fill="currentColor" stroke="none"/>`)],
["Centering","Center Alignment","Placing an element in the middle of its container, usually with flexbox or grid (place-items: center).",`<div class="frame" style="display:grid;place-items:center"><span style="position:absolute;left:50%;top:0;bottom:0;border-left:1.5px dashed var(--danger)"></span><span style="position:absolute;top:50%;left:0;right:0;border-top:1.5px dashed var(--danger)"></span><span class="box" style="width:60px;height:36px;background:var(--ink);position:relative"></span></div>`]
]);

/* ---------- 19 units ---------- */
S('units','Units, Screens & Assets','ruler','How sizes and images work across different screens.',[
["Pixel (px)","CSS Pixel","The basic unit of size on the web. On sharp screens one CSS pixel is drawn with several physical pixels.",`<span style="display:grid;grid-template-columns:repeat(8,12px);gap:1px;background:var(--soft);padding:1px;border-radius:4px">${Array.from({length:32},(_,i)=>`<i style="height:12px;background:${[10,11,12,13,18,21,26,27,28,29].includes(i)?'var(--ink)':'var(--paper)'}"></i>`).join('')}</span>`],
["Point (pt)","iOS Point","Apple’s size unit for iOS. 1pt is 1px at @1x, 2px at @2x and 3px at @3x.",`<span class="row" style="gap:10px;align-items:flex-end">${[1,2,3].map(n=>`<span class="col" style="align-items:center;gap:4px"><span style="display:grid;grid-template-columns:repeat(${n},${12/n*1.6}px);gap:1px;background:var(--soft);padding:1px">${'<i style="aspect-ratio:1;background:var(--ink)"></i>'.repeat(n*n)}</span>${LB('@'+n+'x')}</span>`).join('')}</span>`],
["Density-independent Pixel (dp)","dp, sp","Android’s size unit that looks the same physical size on any screen. Text uses sp, which also follows the user’s font size setting.",`<span class="row" style="gap:12px">${BIG('48dp',24)}<span class="col" style="gap:3px"><span class="mono sm">16sp text</span><span class="mono" style="font-size:15px">16sp large</span></span></span>`],
["rem & em","Relative Units","rem is relative to the root font size (usually 16px); em is relative to the parent’s font size. Both scale with the user’s text settings.",`<div class="col" style="gap:4px">${[[1,16],[1.5,24],[2,32]].map(([r,p])=>`<span class="row mono xs" style="gap:6px"><span style="width:40px">${r}rem</span><i style="display:block;height:8px;width:${p*2.6}px;background:var(--ink);border-radius:2px"></i><span>${p}px</span></span>`).join('')}</div>`],
["Percent, vw & vh","Viewport Units","Percent is relative to the parent; vw and vh are 1% of the viewport’s width and height.",`<div class="frame col" style="padding:8px;gap:8px"><span class="row mono xs" style="gap:4px"><i style="display:block;width:50%;height:10px;background:var(--ink);border-radius:3px"></i>50%</span><span class="row mono xs sb" style="border-top:1.5px dashed;padding-top:3px"><span>←</span><span>100vw</span><span>→</span></span></div>`],
["Pixel Density","@1x, @2x, @3x, Retina","How many physical pixels fit in the same space. Sharp screens need bigger image files to look crisp.",`<span class="row" style="gap:12px;align-items:flex-end">${[6,12,24].map((n,k)=>`<span class="col" style="align-items:center;gap:4px"><span style="display:grid;grid-template-columns:repeat(${n},1fr);width:42px;height:42px">${Array.from({length:n*n},(_,q)=>{const x=(q%n+.5)/n-.5,y=(Math.floor(q/n)+.5)/n-.5;return `<i style="background:${x*x+y*y<.2?'var(--ink)':'transparent'}"></i>`;}).join('')}</span>${LB('@'+(k+1)+'x')}</span>`).join('')}</span>`],
["PPI & DPI","Pixels / Dots per Inch","PPI measures how dense a screen’s pixels are; DPI is the print version, counting ink dots.",SV(170,70,`<path d="M10 50h150" stroke-width="2"/>${Array.from({length:11},(_,i)=>`<path d="M${10+i*15} 50v${i%5?-6:-12}" stroke-width="1.5"/>`).join('')}${Array.from({length:24},(_,i)=>`<circle cx="${12+i*6.2}" cy="62" r="2" fill="currentColor" stroke="none"/>`).join('')}${TX(85,22,'1 inch = 326 pixels (iPhone)',8,'middle')}`)],
["Resolution","Screen Size","The number of pixels across and down a screen or image, such as 1920 × 1080.",`<div class="frame" style="display:grid;place-items:center"><b class="mono" style="font-size:16px">1920 × 1080</b><span class="mono xs" style="position:absolute;bottom:4px">Full HD</span></div>`],
["Vector Graphics","Vector","Images made from math-defined shapes, so they stay sharp at any size. Icons and logos should be vectors.",`<span class="row" style="gap:6px;align-items:flex-end">${[16,32,64].map(s=>SV(s,s,'<path d="M12 2l2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1-4.4-4.3 6.1-.9z" fill="currentColor"/>','0 0 24 24')).join('')}</span>`],
["Raster Graphics","Bitmap","Images made of a fixed grid of pixels, like photos. They blur or turn blocky when enlarged.",`<span style="display:grid;grid-template-columns:repeat(8,9px);gap:0;border:2px solid var(--ink);border-radius:4px;overflow:hidden">${Array.from({length:64},(_,i)=>{const x=i%8-3.5,y=Math.floor(i/8)-3.5;return `<i style="height:9px;background:${x*x+y*y<11?'var(--ink)':'var(--paper)'}"></i>`;}).join('')}</span>`],
["SVG","Scalable Vector Graphics","The web’s vector image format. It can be styled with CSS and animated.",`<div class="col" style="gap:6px;align-items:center">${SV(40,40,'<circle cx="20" cy="20" r="14" fill="currentColor"/>')}${CODE('&lt;svg viewBox="0 0 40 40"&gt;\n  &lt;circle r="14"/&gt;\n&lt;/svg&gt;')}</div>`],
["Image Formats","PNG, JPG, WebP, AVIF","PNG keeps sharp edges and transparency, JPG is small for photos, and WebP and AVIF are newer formats that are smaller still.",`<div class="col" style="gap:4px">${[['PNG','sharp, transparent'],['JPG','photos, small'],['WebP','smaller, modern'],['AVIF','smallest, newest']].map(([f,d])=>`<span class="row" style="gap:6px"><span class="chip sm on" style="width:44px;justify-content:center">${f}</span>${LB(d)}</span>`).join('')}</div>`],
["Nine-slice Scaling","9-slice","Splitting an image into a 3×3 grid so the corners stay fixed while the edges and center stretch. Used for buttons and panels.",`<div style="position:relative;width:150px;height:70px;border:3px solid var(--ink);border-radius:18px;background:var(--soft)"><span style="position:absolute;left:18px;top:0;bottom:0;border-left:1.5px dashed var(--danger)"></span><span style="position:absolute;right:18px;top:0;bottom:0;border-left:1.5px dashed var(--danger)"></span><span style="position:absolute;top:18px;left:0;right:0;border-top:1.5px dashed var(--danger)"></span><span style="position:absolute;bottom:18px;left:0;right:0;border-top:1.5px dashed var(--danger)"></span><span class="mono xs" style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%)">stretches</span></div>`],
["Orientation","Portrait, Landscape","Whether a screen is taller than it is wide (portrait) or wider than it is tall (landscape).",`<span class="row" style="gap:14px;align-items:flex-end"><span class="col" style="align-items:center;gap:4px"><span class="phone" style="width:44px;height:76px"></span>${LB('portrait')}</span><span class="col" style="align-items:center;gap:4px"><span class="phone" style="width:76px;height:44px"></span>${LB('landscape')}</span></span>`],
["Aspect Ratios","16:9, 4:3, 1:1, 9:16","Standard width-to-height shapes. 16:9 is widescreen video and 9:16 is vertical video for Shorts and Reels.",`<span class="row" style="gap:6px;align-items:flex-end">${[['16:9',64,36],['4:3',48,36],['1:1',36,36],['9:16',30,54]].map(([l,w,h])=>`<span class="col" style="align-items:center;gap:4px"><span class="box" style="width:${w}px;height:${h}px;background:var(--soft)"></span>${LB(l)}</span>`).join('')}</span>`],
["Favicon","Site Icon","The tiny icon shown in a browser tab and in bookmarks.",`<span class="row" style="gap:6px;padding:6px 12px;border:2px solid var(--ink);border-bottom:0;border-radius:10px 10px 0 0;background:var(--paper)">${SP}<b class="b xs">UI Field Guide</b>${I('x','xs')}</span>`],
["App Icon","Launcher Icon","The icon on a phone’s home screen. Each platform has its own size and corner-shape rules.",`<span class="col" style="align-items:center;gap:6px"><span style="width:64px;height:64px;border-radius:16px;background:var(--ink);color:var(--paper);display:grid;place-items:center">${SP.replace('class="sp"','class="sp" style="width:30px;height:30px"')}</span>${LB('Field Guide')}</span>`],
["Sprite Sheet","Sprites","Many small images packed into one file and shown one piece at a time, used in games and animations.",`<span class="row box" style="gap:0;overflow:hidden">${[0,10,20,10].map((y,i)=>`<span style="width:36px;height:50px;border-left:${i?'1.5px dashed var(--mute)':'0'};position:relative"><i style="position:absolute;left:10px;bottom:${6+y}px;width:16px;height:16px;border-radius:50%;background:var(--ink)"></i></span>`).join('')}</span>`]
]);

/* ---------- 20 typography deep dive ---------- */
S('type','Typography Deep Dive','type','The parts of letters and the rules of setting text.',[
["Serif","Serif Typeface","Letters with small strokes, called serifs, at the ends. Often feels classic or editorial.",`<span style="font:400 46px Georgia,'Times New Roman',serif">Rg</span>`],
["Sans-serif","Sans Typeface","Letters without serifs. Clean and the most common choice for interfaces.",`<span style="font:800 46px Archivo,sans-serif">Rg</span>`],
["Monospace","Fixed-width Font","Every character takes the same width. Used for code and numbers that must line up.",`<div class="col mono" style="font-size:22px;line-height:1.2"><span>iiiii</span><span>WWWWW</span></div>`],
["Display Typeface","Headline Font","A font designed for big sizes, with more personality than body fonts. Like the one in this guide’s titles.",BIG('Paladin',40)],
["Script & Handwritten","Script Font","Fonts that imitate handwriting or calligraphy. Use them sparingly; long passages get hard to read.",`<span style="font:italic 38px 'Brush Script MT','Segoe Script',cursive">Hello there</span>`],
["Font Weight","Thin to Black","How thick the strokes are, from 100 (thin) to 900 (black).",`<span class="row" style="gap:10px;align-items:flex-end">${[400,600,800,900].map(w=>`<span class="col" style="align-items:center;gap:2px"><span style="font:${w} 28px Archivo,sans-serif">Aa</span>${LB(w)}</span>`).join('')}</span>`],
["Italic & Oblique","Slanted Type","Italic is a separately drawn slanted style; oblique is simply the upright letters tilted.",`<span class="row" style="gap:14px"><span class="col" style="align-items:center;gap:3px"><span style="font:italic 30px Georgia,serif">afe</span>${LB('italic')}</span><span class="col" style="align-items:center;gap:3px"><span style="font:oblique 30px Georgia,serif;font-synthesis:style;display:inline-block;transform:skewX(-12deg)">afe</span>${LB('oblique')}</span></span>`],
["Baseline","Text Baseline","The invisible line letters sit on. Descenders like g and y dip below it.",TYPO('baseline')],
["x-height","Lowercase Height","The height of lowercase letters such as x. A larger x-height reads better at small sizes.",TYPO('x-height')],
["Cap Height","Capital Height","The height of capital letters, measured from the baseline.",TYPO('cap height')],
["Ascender & Descender","Extenders","Parts of letters that rise above the x-height (b, d, h) or drop below the baseline (g, p, y).",TYPO('descender')],
["Leading","Line Height","The space from one line of text to the next. Around 1.4–1.6 × the font size suits body text.",`<span class="row" style="gap:12px;align-items:flex-start">${[[1,'1.0'],[1.6,'1.6']].map(([lh,l])=>`<span class="col" style="gap:4px;align-items:center"><span style="font:12px/${lh} Archivo,sans-serif;width:62px">Lines of text set close or apart.</span>${LB(l)}</span>`).join('')}</span>`],
["Tracking","Letter Spacing","Even spacing added or removed across a whole word or line.",`<div class="col" style="gap:6px;align-items:center"><span style="font:900 18px Archivo,sans-serif;letter-spacing:-.06em">TRACKING</span><span style="font:900 18px Archivo,sans-serif;letter-spacing:.3em">TRACKING</span></div>`],
["Kerning","Pair Spacing","Adjusting the space between two specific letters, like A and V, so the gaps look even.",`<span class="row" style="gap:16px"><span class="col" style="align-items:center;gap:3px"><span style="font:800 36px Georgia,serif;letter-spacing:.12em;font-kerning:none">AVA</span>${LB('off')}</span><span class="col" style="align-items:center;gap:3px"><span style="font:800 36px Georgia,serif;letter-spacing:-.08em">AVA</span>${LB('kerned')}</span></span>`],
["Measure","Line Length","How many characters fit on one line. About 45–75 characters is comfortable for reading.",`<div class="col" style="gap:5px;align-items:flex-start">${L(170,'m t')}${L(170,'m t')}<span class="row mono xs" style="gap:4px;width:170px;color:var(--danger)"><i style="flex:1;border-top:1.5px solid"></i>~65 characters<i style="flex:1;border-top:1.5px solid"></i></span></div>`],
["Text Alignment","Left, Center, Right, Justified","Where lines line up. Left-aligned text is easiest to read in left-to-right languages.",`<span class="row" style="gap:8px">${['flex-start','center','flex-end','stretch'].map((a,i)=>`<span class="col" style="align-items:${a};gap:3px;width:34px">${[30,22,27,18].map(w=>`<i class="ln t" style="width:${a==='stretch'?34:w}px;align-self:${a==='stretch'?'stretch':'auto'}"></i>`).join('')}${LB(['left','center','right','justify'][i]).replace('class="mono xs"','class="mono xs" style="align-self:center;font-size:8px"')}</span>`).join('')}</span>`],
["Rag","Ragged Edge","The uneven right edge of left-aligned text. A good rag has no deep, awkward gaps.",`<div class="col" style="gap:5px;position:relative">${[150,120,148,96,140].map(w=>L(w,'m t')).join('')}<span style="position:absolute;right:-6px;top:-4px;bottom:-4px;width:46px;border:1.5px dashed var(--danger);border-radius:6px"></span></div>`],
["Widows & Orphans","Stray Lines","A widow is a lone word or line stranded at the end of a paragraph or top of a column; an orphan is a lone line left at the bottom of a page.",`<div class="col" style="gap:5px">${L(150,'m t')}${L(150,'m t')}${L(146,'m t')}<span class="b xs" style="border:1.5px dashed var(--danger);border-radius:4px;padding:0 4px;align-self:flex-start">word.</span></div>`],
["Hyphenation","Word Breaks","Splitting long words across lines with a hyphen, which helps narrow or justified text avoid big gaps.",`<span style="display:block;width:90px;font:13px/1.4 Archivo,sans-serif;text-align:justify">The final adven-<br>ture begins at dawn in the north.</span>`],
["Ligature","Joined Letters","Two or more letters drawn as one shape, like fi or fl, so they don’t collide.",`<span class="row" style="gap:16px"><span class="col" style="align-items:center;gap:3px"><span style="font:36px Georgia,serif;font-variant-ligatures:none">fi fl</span>${LB('off')}</span><span class="col" style="align-items:center;gap:3px"><span style="font:36px Georgia,serif;font-variant-ligatures:common-ligatures">fi fl</span>${LB('on')}</span></span>`],
["Small Caps","Small Capitals","Capital letters drawn about as tall as lowercase, used for acronyms and labels.",`<span style="font:24px Georgia,serif;font-variant:small-caps">Level Up, NASA</span>`],
["Tabular Numbers","Tabular Figures","Numbers that all share one width so columns of figures line up.",`<span class="row" style="gap:18px">${[['proportional-nums','proportional'],['tabular-nums','tabular']].map(([v,l])=>`<span class="col" style="align-items:flex-end;gap:2px;font:15px Archivo,sans-serif;font-variant-numeric:${v}"><span>1,111</span><span>8,888</span><span>4,071</span>${LB(l)}</span>`).join('')}</span>`],
["Variable Fonts","Variable Typeface","One font file holding a whole range of weights or widths you can set to any value. Drag the slider.",`<div class="col" data-demo style="align-items:center;gap:8px"><span data-tgt style="font-family:Fraunces,serif;font-size:48px;line-height:1;--w:400;font-variation-settings:'wght' var(--w),'SOFT' 100">Aa</span><input type="range" min="100" max="900" value="400" data-var="--w" aria-label="Font weight" style="width:140px;accent-color:var(--ink)"></div>`],
["Font Stack","Fallback Fonts","The list of fonts to try in order, ending with a generic family, in case the first one doesn’t load.",CODE(`font-family:
  "Archivo",
  system-ui,
  sans-serif;`)],
["Font Pairing","Type Pairing","Choosing fonts that work together, often a characterful display font for headings and a quiet one for body text.",`<div class="col" style="gap:4px;width:170px">${BIG('Paladin',24)}<span style="font:12px/1.45 Archivo,sans-serif">A sturdy sans for reading, a soft serif for the big moments.</span></div>`],
["Modular Scale","Type Scale Ratio","Font sizes picked by multiplying by one ratio, such as 1.25, so every size feels related.",`<span class="row" style="gap:6px;align-items:baseline">${[16,20,25,31,39].map(s=>`<span class="col" style="align-items:center;gap:2px"><span class="fr" style="font-size:${s}px;line-height:1">A</span>${LB(s)}</span>`).join('')}</span>`],
["Drop Cap","Initial Letter","An enlarged first letter that drops into the opening lines of a paragraph.",`<span style="display:block;width:150px;font:12px/1.4 Archivo,sans-serif"><b class="fr" style="float:left;font-size:44px;line-height:.85;margin:2px 6px 0 0">O</b>nce upon a time, a paladin set out to find the broken swords of the old guild.</span>`],
["All Caps","Uppercase","Text set fully in capitals. Add a little letter spacing and keep it short; it’s slower to read.",`<span style="font:900 14px Archivo,sans-serif;letter-spacing:.08em">INCREASE LEVEL</span>`],
["Font Loading","FOUT, FOIT","How web fonts appear while downloading: FOUT shows a fallback font first, FOIT shows invisible text first.",`<div class="col" style="gap:8px">${[['FOUT','font:16px system-ui','Hello'],['FOIT','color:transparent;border:1.5px dashed var(--mute);border-radius:4px','Hello']].map(([l,s,t])=>`<span class="row" style="gap:8px"><span class="chip sm" style="width:40px;justify-content:center">${l}</span><span style="${s}">${t}</span>${SV(16,10,'<path d="M2 5h10M9 2l3 3-3 3"/>')}<span class="fr" style="font-size:16px">Hello</span></span>`).join('')}</div>`],
["Legibility & Readability","Readable Text","Legibility is how easily single characters are told apart; readability is how comfortable whole passages are to read.",`<div class="col" style="gap:6px;align-items:center"><span class="row" style="gap:14px"><span style="font:20px Archivo,sans-serif">Il1 O0</span><span class="mono" style="font-size:20px">Il1 O0</span></span>${LB('which is easier to tell apart?')}</div>`]
]);

/* ---------- 21 color theory ---------- */
S('color','Color Theory','drop','How color works and how to choose it.',[
["Hue","Color Family","The pure color itself, like red, yellow or blue, measured as an angle around the color wheel.",`<div class="col" style="gap:5px;width:170px"><span class="hue" style="height:18px"></span><span class="row sb mono xs"><span>0°</span><span>120°</span><span>240°</span><span>360°</span></span></div>`],
["Saturation","Chroma, Intensity","How vivid a color is, from grey to full strength.",`<div class="col" style="gap:5px;width:170px"><span style="display:block;height:22px;border-radius:99px;border:2px solid var(--ink);background:linear-gradient(90deg,#7f7f80,#1e63d6)"></span><span class="row sb mono xs"><span>0%</span><span>100%</span></span></div>`],
["Lightness","Brightness, Value","How light or dark a color is, from black to white.",`<div class="col" style="gap:5px;width:170px"><span style="display:block;height:22px;border-radius:99px;border:2px solid var(--ink);background:linear-gradient(90deg,#000,#1e63d6,#fff)"></span><span class="row sb mono xs"><span>0%</span><span>50%</span><span>100%</span></span></div>`],
["Tints, Shades & Tones","Color Variations","A tint adds white, a shade adds black, and a tone adds grey.",`<div class="col" style="gap:4px">${[['tint','#1e63d6','#fff'],['shade','#1e63d6','#000'],['tone','#1e63d6','#888']].map(([l,a,b])=>`<span class="row" style="gap:4px">${[0,25,50,75].map(p=>SW(`color-mix(in srgb,${a},${b} ${p}%)`,20)).join('')}${LB(l)}</span>`).join('')}</div>`],
["Color Wheel","Hue Circle","All hues arranged in a circle, used to find colors that work together.",PIE('red,yellow,lime,cyan,blue,magenta,red',true)],
["Primary, Secondary & Tertiary","Color Mixing","Primaries mix into secondaries, and mixing neighbors makes tertiaries. Screens use red, green and blue light as primaries.",`<span style="position:relative;width:96px;height:90px;background:#000;border-radius:12px;display:block;overflow:hidden">${[['#f00',26,20],['#0f0',46,20],['#00f',36,38]].map(([c,x,y])=>`<i style="position:absolute;left:${x}px;top:${y}px;width:34px;height:34px;border-radius:50%;background:${c};mix-blend-mode:screen"></i>`).join('')}</span>`],
["Complementary","Opposite Colors","Colors directly across the wheel from each other. High contrast and energetic.",`<span class="row" style="gap:12px">${PIE('red,yellow,lime,cyan,blue,magenta,red',true)}${SWS(['#e8742c','#2c8ae8'],30)}</span>`],
["Analogous","Neighbor Colors","Colors next to each other on the wheel. Calm and harmonious.",SWS(['#e8b92c','#e8742c','#e8432c'],34)],
["Triadic","Three-way Scheme","Three colors evenly spaced around the wheel. Bold but balanced.",SWS(['#e8432c','#2ce874','#2c5be8'],34)],
["Split-complementary","Split Scheme","One color plus the two neighbors of its opposite. Softer than a straight complementary pair.",SWS(['#e8742c','#2cb7e8','#5b2ce8'],34)],
["Monochromatic","Single-hue Scheme","Different lightness and saturation of just one hue.",SWS(['#0d2b66','#1e63d6','#6f9cf0','#c7d8fa'],30)],
["Warm & Cool Colors","Color Temperature","Reds, oranges and yellows feel warm; blues, greens and purples feel cool.",`<span class="row" style="gap:12px"><span class="col" style="align-items:center;gap:4px">${SWS(['#e8432c','#e8742c','#f2c14e'],22)}${LB('warm')}</span><span class="col" style="align-items:center;gap:4px">${SWS(['#2c5be8','#2cb7a0','#7a4bb3'],22)}${LB('cool')}</span></span>`],
["60-30-10 Rule","Color Proportion","A balance guide: about 60% main color, 30% secondary color and 10% accent.",`<div class="col" style="gap:5px;width:176px"><span class="row" style="gap:0;height:30px;border:2px solid var(--ink);border-radius:8px;overflow:hidden"><i style="flex:6;height:100%;background:var(--paper)"></i><i style="flex:3;height:100%;background:var(--ink)"></i><i style="flex:1;height:100%;background:#c8372d"></i></span><span class="row mono xs" style="gap:0"><span style="flex:6">60%</span><span style="flex:3">30%</span><span style="flex:1">10</span></span></div>`],
["RGB","Red Green Blue","How screens make color by mixing light, each channel from 0 to 255.",`<div class="col" style="gap:4px;width:170px">${[['R',47,'#e33'],['G',95,'#2a2'],['B',208,'#36f']].map(([l,v,c])=>`<span class="row mono xs" style="gap:6px"><b style="width:10px">${l}</b><i style="display:block;height:8px;width:${v/2}px;background:${c};border-radius:2px"></i>${v}</span>`).join('')}<span class="row" style="gap:6px">${SW('rgb(47,95,208)',24)}<span class="mono xs">rgb(47, 95, 208)</span></span></div>`],
["HEX","Hex Code","RGB written as six hexadecimal digits in pairs for red, green and blue, like #2F5FD0.",`<div class="col" style="gap:4px;align-items:center"><span class="mono" style="font-size:24px;font-weight:700">#<span style="color:#d33">2F</span><span style="color:#2a2">5F</span><span style="color:#36f">D0</span></span><span class="row mono xs" style="gap:22px;margin-left:16px"><span>R</span><span>G</span><span>B</span></span></div>`],
["HSL","Hue, Saturation, Lightness","Color written as hue (0–360°), saturation and lightness, which makes variations easy. Drag the hue.",`<div class="col" data-demo style="gap:8px;align-items:center"><span data-tgt style="--h:220;display:block;width:60px;height:60px;border-radius:14px;border:2px solid var(--ink);background:hsl(var(--h) 65% 50%)"></span><input type="range" min="0" max="360" value="220" data-var="--h" aria-label="Hue" style="width:140px;accent-color:var(--ink)"></div>`],
["CMYK","Cyan, Magenta, Yellow, Key","The ink colors used for printing. Bright screen colors may look duller when printed.",SWS(['#00b7eb','#e5007e','#ffe600','#111'],30)],
["Alpha","Opacity Channel","A fourth value that sets transparency, like rgba(0, 0, 0, 0.5).",`<span style="display:flex;gap:6px;padding:8px;border-radius:10px;background:repeating-conic-gradient(#ccc 0 25%,#fff 0 50%) 0 0/12px 12px">${[1,.6,.3].map(a=>`<i style="width:38px;height:38px;border-radius:8px;background:rgba(30,99,214,${a})"></i>`).join('')}</span>`],
["Color Gamut","sRGB, Display P3","The range of colors a screen can show. Display P3 shows more vivid colors than sRGB.",SV(130,96,`<path d="M30 86L64 8 116 76z" fill="currentColor" opacity=".12"/><path d="M38 80L64 22 104 72z"/>${TX(64,50,'sRGB',8,'middle')}${TX(118,90,'P3',8,'middle')}`)],
["Color Ramp","Color Scale, 50–900","Steps of one color from light to dark, numbered 50, 100 … 900, used in design systems.",`<span class="row" style="gap:2px">${[50,100,200,300,400,500,600,700,800,900].map((n,i)=>`<span class="col" style="align-items:center;gap:2px"><i style="display:block;width:15px;height:30px;border-radius:4px;background:color-mix(in srgb,#1e63d6,${i<5?'#fff':'#000'} ${i<5?(90-i*20):((i-5)*18)}%)"></i><span class="mono" style="font-size:7px">${n}</span></span>`).join('')}</span>`],
["Semantic Colors","Status Colors","Colors with fixed meanings: green for success, red for errors, amber for warnings and blue for info. Always pair them with text or icons.",`<div class="col" style="gap:4px">${[['#2e9d5b','check','Success'],['#c8372d','x','Error'],['#c98a00','warn','Warning'],['#2f5fd0','info','Info']].map(([c,i,t])=>`<span class="row b xs" style="gap:6px;color:${c}">${I(i,'s')}<span>${t}</span></span>`).join('')}</div>`],
["Brand Colors","Brand Palette","The specific colors that identify a brand, used the same way everywhere.",`<span class="row" style="gap:10px"><span class="logo">${SP}</span>${SWS(['var(--ink)','var(--paper)','var(--soft)'],26)}</span>`],
["Gradient Types","Linear, Radial, Conic","Linear blends along a line, radial spreads out from a point, and conic sweeps around a center.",`<span class="row" style="gap:8px">${[['linear','linear-gradient(135deg,var(--ink),var(--paper))'],['radial','radial-gradient(circle,var(--paper),var(--ink))'],['conic','conic-gradient(var(--ink),var(--paper),var(--ink))']].map(([l,g])=>`<span class="col" style="align-items:center;gap:3px"><i style="display:block;width:46px;height:46px;border-radius:12px;border:2px solid var(--ink);background:${g}"></i>${LB(l)}</span>`).join('')}</span>`],
["Duotone","Two-tone Image","An image recolored using only two colors.",`<span style="display:block;border-radius:10px;overflow:hidden;line-height:0">${SV(150,86,'<rect width="150" height="86" fill="#f2c14e" stroke="none"/><path d="M0 70L40 30l30 26 34-36 46 46v20H0z" fill="#3a1f6b" stroke="none"/><circle cx="118" cy="22" r="10" fill="#3a1f6b" stroke="none"/>')}</span>`],
["Color Blindness","Color Vision Deficiency","Roughly 1 in 12 men and 1 in 200 women see some colors differently, most often red and green. Never rely on color alone.",`<span class="row" style="gap:12px"><span class="col" style="align-items:center;gap:4px">${SWS(['#c8372d','#2e9d5b'],28)}${LB('typical')}</span><span class="col" style="align-items:center;gap:4px">${SWS(['#9a8a3a','#a39446'],28)}${LB('red-green CVD')}</span></span>`]
]);

/* ---------- 22 motion ---------- */
S('motion','Motion & Animation','bolt','How things move, and the words animators use. These demos animate on their own.',[
["Easing","Timing Function","How speed changes during an animation. Real objects speed up and slow down instead of moving at one speed.",`<div class="col" style="gap:4px">${MV('e-lin')}${MV('e-io')}<span class="row sb mono xs"><span>top: linear</span><span>bottom: eased</span></span></div>`],
["Linear","Constant Speed","Moves at the same speed from start to end. Feels mechanical, so keep it for spinners and progress.",MV('e-lin')],
["Ease-in","Accelerate","Starts slow and speeds up. Use it for things leaving the screen.",MV('e-in')],
["Ease-out","Decelerate","Starts fast and slows down. Use it for things entering the screen; it feels responsive.",MV('e-out')],
["Ease-in-out","Accelerate, then Decelerate","Slow at both ends and fast in the middle. Good for moving between two points on screen.",MV('e-io')],
["Cubic Bézier","Custom Easing Curve","A custom easing curve set by four numbers, like cubic-bezier(0.7, 0, 0.2, 1).",`<div class="col" style="gap:6px;align-items:center">${SV(90,50,'<path d="M4 46h82M4 46V4" stroke-width="1.5" opacity=".4"/><path d="M4 46C60 46 20 4 86 4"/><circle cx="60" cy="46" r="3" fill="#c8372d" stroke="none"/><circle cx="20" cy="4" r="3" fill="#c8372d" stroke="none"/>')}${MV('e-bz')}</div>`],
["Spring Animation","Physics-based Motion","Motion driven by stiffness and damping, so it can overshoot and settle like a real spring.",MV('e-spr')],
["Duration","Animation Length","How long an animation takes. Most interface motion lives between 150 and 400 milliseconds.",`<div class="col" style="gap:4px">${[['.3s','150ms'],['.6s','300ms'],['1.4s','700ms']].map(([d,l])=>`<span class="row" style="gap:6px"><span style="width:110px">${MV('e-io','animation-duration:'+d).replace('width:170px','')}</span>${LB(l)}</span>`).join('').replace(/class="trk"/g,'class="trk" style="width:110px"')}</div>`],
["Delay","Animation Delay","Waiting a moment before an animation starts.",`<div class="col" style="gap:4px">${MV('e-io')}${MV('e-io','animation-delay:.6s')}<span class="mono xs">bottom: 0.6s delay</span></div>`],
["Keyframes","Keyframe","Points in time where you set a value; the software fills in every frame between them.",SV(176,70,`<path d="M6 40h164" stroke-width="2"/>${[20,80,150].map((x,i)=>`<path d="M${x} 32l8 8-8 8-8-8z" fill="${i===1?'currentColor':'var(--paper)'}"/>${TX(x,22,['0%','50%','100%'][i],8,'middle')}`).join('')}${TX(20,64,'x: 0',8,'middle')}${TX(80,64,'x: 80',8,'middle')}${TX(150,64,'x: 160',8,'middle')}`)],
["Tweening","Interpolation, In-betweening","Automatically generating the frames between two keyframes.",`<span class="row" style="gap:6px">${[1,.2,.3,.45,.6,1].map((o,i)=>`<i style="display:block;width:22px;height:22px;border-radius:6px;background:var(--ink);opacity:${o};${i===0||i===5?'outline:2px solid var(--ink);outline-offset:2px':''}"></i>`).join('')}</span>`],
["Stagger","Cascade","Starting the same animation on several items one after another, for a flowing effect.",`<span class="row a-dots" style="gap:8px">${[0,1,2,3,4].map(i=>`<i style="display:block;width:16px;height:16px;border-radius:50%;background:var(--ink);animation-delay:${i*.1}s"></i>`).join('')}</span>`],
["Fade","Opacity Transition","Changing opacity to make something appear or disappear.",`<span class="ab a-fade"></span>`],
["Slide","Translate","Moving something in from, or out to, an edge.",`<div class="box" style="width:90px;height:70px;overflow:hidden;display:grid;place-items:center"><span class="ab a-slide" style="width:50px;height:30px"></span></div>`],
["Scale","Zoom Transition","Growing or shrinking an element, often from the point that was tapped.",`<span class="ab a-scale"></span>`],
["Rotate","Spin","Turning an element around a point, like a refresh icon spinning.",`<span class="cb" style="width:52px;height:52px"><span class="a-rot" style="display:grid">${I('refresh')}</span></span>`],
["Morph","Shape Morphing","One shape smoothly turning into another, like a square becoming a circle.",`<span class="ab a-morph"></span>`],
["Shared Element Transition","Hero Transition, Magic Move","One element travels from one screen to the next, like a thumbnail growing into the full photo.",`<span class="row" style="gap:10px;position:relative">${MINI('',46,76)}${MINI('',46,76)}<i class="a-shared" style="position:absolute;left:10px;top:40px;width:22px;height:18px;border-radius:4px;background:var(--ink)"></i></span>`],
["Page Transition","Screen Transition","The animation used when moving between screens, such as push, fade or slide-over.",`<span style="position:relative;width:120px;height:90px;display:block"><span class="phone" style="position:absolute;left:0;top:6px;width:56px;height:84px;opacity:.5"></span><span class="phone" style="position:absolute;left:36px;top:0;width:60px;height:90px;box-shadow:-6px 0 0 var(--soft)"></span><span style="position:absolute;right:0;top:36px">${SV(20,12,'<path d="M18 6H2M6 2L2 6l4 4"/>')}</span></span>`],
["Motion Path","Path Animation","Making an element follow a drawn curve instead of a straight line.",`<span style="position:relative;display:block;width:160px;height:70px">${SV(160,70,'<path d="M8 50 C40 -10 100 100 152 20" stroke-dasharray="3 5" stroke-width="1.5"/>')}<i class="a-path"></i></span>`],
["Loop","Infinite Animation","An animation that repeats forever. Keep loops subtle so they don’t distract.",`<span class="row" style="gap:12px"><span class="ab a-bob" style="width:30px;height:30px;border-radius:50%"></span>${BIG('∞',30)}</span>`],
["Squash & Stretch","Animation Principle","Squishing on impact and stretching when fast, to give objects weight. One of the 12 principles of animation.",`<span style="display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:90px;width:90px;border-bottom:2px solid var(--ink)"><i class="a-sq" style="display:block;width:30px;height:30px;border-radius:50%;background:var(--ink)"></i></span>`],
["Anticipation","Wind-up","A small move in the opposite direction before the main action, like crouching before a jump.",MV('a-anti')],
["Follow-through","Overlapping Action","Parts keep moving after the main motion stops, then settle, which makes motion feel natural.",`<div class="trk" style="height:44px"><span class="mv e-io" style="top:10px"></span><span class="mv a-follow" style="top:10px;width:12px;height:12px;border-radius:50%;margin-left:7px;margin-top:-10px"></span></div>`],
["12 Principles of Animation","Disney’s Principles","Classic animator rules: squash and stretch, anticipation, staging, straight ahead and pose to pose, follow-through, slow in and out, arcs, secondary action, timing, exaggeration, solid drawing and appeal.",`<div class="col" style="align-items:center;gap:4px">${BIG('12',40)}<span class="mono xs">principles of animation</span></div>`],
["Frame Rate","FPS","How many frames show each second: 24 fps for film, 30 for most video, 60 or more feels smooth in interfaces.",`<span class="row" style="gap:10px">${[24,30,60].map(f=>`<span class="col" style="align-items:center;gap:3px"><span class="row" style="gap:${f===60?1:4}px">${'<i style="display:block;width:5px;height:20px;background:var(--ink);border-radius:1px"></i>'.repeat(f===24?3:f===30?4:7)}</span>${LB(f+' fps')}</span>`).join('')}</span>`],
["Motion Blur","Blur Trail","Blurring a fast-moving object along its path so the motion reads as smooth.",`<span class="row" style="gap:0">${[.12,.22,.4,1].map((o,i)=>`<i style="display:block;width:${i===3?34:16}px;height:34px;border-radius:${i===3?9:4}px;background:var(--ink);opacity:${o};filter:blur(${i===3?0:3-i}px)"></i>`).join('')}</span>`],
["Lottie","Lottie Animation","A lightweight animation file exported from After Effects (via the Bodymovin plugin) that plays in apps and websites.",`<span class="row" style="gap:10px"><span class="ab a-scale" style="width:34px;height:34px;border-radius:50%;display:grid;place-items:center;color:var(--paper)">${SP}</span><span class="box row" style="padding:6px 8px;gap:6px">${I('copy','s')}<span class="mono xs">loader.json</span></span></span>`],
["Reduced Motion","prefers-reduced-motion","A system setting for people who get dizzy from motion. Respect it by toning down or removing animation.",CODE(`@media (prefers-reduced-motion:
       reduce) {
  * { animation: none; }
}`)]
]);

/* ---------- 23 laws ---------- */
S('laws','UX Laws & Psychology','bulb','Rules of thumb from psychology that explain how people use interfaces.',[
["Miller’s Law","7 ± 2","People can hold only a few items in working memory, so break information into chunks, like a phone number in groups.",GB('09171234567','0917 123 4567')],
["Tesler’s Law","Conservation of Complexity","Every system has some complexity that can’t be removed, only moved. Let the system carry it instead of the user.",`<span class="row" style="gap:10px"><span class="col" style="align-items:center;gap:3px"><span class="box" style="width:46px;height:20px"></span>${LB('user')}</span><span class="col" style="align-items:center;gap:3px"><span class="box" style="width:46px;height:52px;background:var(--ink)"></span>${LB('system')}</span></span>`],
["Postel’s Law","Robustness Principle","Be liberal in what you accept and strict in what you output: accept many input formats, display one clean one.",`<span class="row" style="gap:6px"><span class="col mono xs" style="gap:3px"><span>09171234567</span><span>+63 917…</span><span>917-123-4567</span></span>${SV(20,12,'<path d="M2 6h14M12 2l4 4-4 4"/>')}<span class="chip sm on">+63 917 123 4567</span></span>`],
["Doherty Threshold","400 ms Rule","People stay engaged when the system responds within about 400 milliseconds. Show progress if it takes longer.",`<div class="col" style="gap:4px;width:176px"><span class="row" style="height:14px;border:2px solid var(--ink);border-radius:99px;overflow:hidden"><i style="width:40%;height:100%;background:#2e9d5b"></i><i style="flex:1;height:100%;background:var(--soft)"></i></span><span class="row sb mono xs"><span>0</span><span style="margin-left:-60px">400ms</span><span>1s</span></span></div>`],
["Von Restorff Effect","Isolation Effect","The item that looks different from the rest is the one people remember.",`<span class="row" style="gap:8px">${[0,0,1,0,0].map(o=>`<i style="display:block;width:24px;height:24px;border-radius:50%;border:2px solid var(--ink);background:${o?'var(--ink)':'var(--paper)'}"></i>`).join('')}</span>`],
["Serial Position Effect","Primacy & Recency","People remember the first and last items in a list best, so put key items at the ends.",`<span class="row" style="gap:6px">${[1,.3,.25,.3,1].map(o=>`<span class="box" style="width:26px;height:26px;opacity:${o};background:${o===1?'var(--ink)':'var(--paper)'}"></span>`).join('')}</span>`],
["Peak-End Rule","Memory of Experience","People judge an experience mostly by its most intense moment and its end, so design both carefully.",LINE([20,30,62,24,30,50],false)],
["Zeigarnik Effect","Unfinished Tasks","People remember unfinished tasks, which is why checklists and progress bars pull them back.",`<div class="col" style="gap:4px">${['Add photo','Write bio','Verify email','Pick theme'].map((t,i)=>`<span class="row b xs" style="gap:6px"><span class="chk2 ${i<2?'on':''}">${i<2?I('check','xs'):''}</span>${t}</span>`).join('')}<span class="mono xs">2 of 4 done</span></div>`],
["Goal-Gradient Effect","Finish Line Effect","People speed up as they near a goal, like a loyalty card that’s almost full.",`<span style="display:grid;grid-template-columns:repeat(5,22px);gap:5px">${Array.from({length:10},(_,i)=>`<i style="display:grid;place-items:center;height:22px;border-radius:50%;border:2px solid var(--ink);background:${i<8?'var(--ink)':'var(--paper)'};color:var(--paper)">${i<8?SP.replace('class="sp"','class="sp" style="width:10px;height:10px"'):''}</i>`).join('')}</span>`],
["Aesthetic-Usability Effect","Pretty Feels Easier","People see good-looking designs as easier to use and forgive small problems in them.",`<span class="row" style="gap:12px"><span style="font:13px Times,serif;border:1px solid #888;padding:2px 6px;background:#eee;color:#000">Submit</span><span class="btn fill">${SP} Level up</span></span>`],
["Law of Prägnanz","Law of Simplicity","People read complex shapes in the simplest way possible, like seeing overlapping circles instead of odd shapes.",SV(140,70,'<circle cx="40" cy="35" r="24"/><circle cx="70" cy="35" r="24"/><circle cx="100" cy="35" r="24"/>')],
["Law of Common Region","Grouping by Container","Items inside a shared border or background are seen as one group.",`<span class="row" style="gap:10px">${[0,1].map(()=>`<span class="box row" style="padding:8px;gap:6px;background:var(--soft)">${'<i style="display:block;width:14px;height:14px;border-radius:50%;background:var(--ink)"></i>'.repeat(3)}</span>`).join('')}</span>`],
["Law of Uniform Connectedness","Grouping by Connection","Items connected by lines or shared color are seen as related.",SV(160,40,`<path d="M20 20H60" stroke-width="3"/>${[20,60,100,140].map(x=>`<circle cx="${x}" cy="20" r="8" fill="currentColor" stroke="none"/>`).join('')}`)],
["Recognition over Recall","Recognize, Don’t Remember","Showing options people can recognize beats making them remember things, like a list of recent files.",`<div class="col" style="gap:0;width:166px"><span class="lab" style="margin-bottom:4px">Recent</span><div class="lbx">${['quest-map.pdf','paladin.png','notes.txt'].map((t,i)=>`<span class="${i?'':'on'}">${t}</span>`).join('')}</div></div>`],
["Occam’s Razor","Simplest Solution","Among options that work equally well, pick the one with the fewest parts.",`<span class="row" style="gap:14px"><span class="col" style="gap:3px">${'<span class="box" style="width:50px;height:10px"></span>'.repeat(5)}</span>${SV(20,12,'<path d="M2 6h14M12 2l4 4-4 4"/>')}<span class="box" style="width:50px;height:34px;background:var(--ink)"></span></span>`],
["Pareto Principle","80/20 Rule","About 80% of effects come from 20% of causes, so focus on the features people use most.",`<div class="col" style="gap:5px;width:170px"><span class="row" style="height:24px;border:2px solid var(--ink);border-radius:8px;overflow:hidden"><i style="width:20%;height:100%;background:var(--ink)"></i><i style="flex:1;height:100%;background:var(--soft)"></i></span><span class="mono xs">20% of features, 80% of use</span></div>`],
["Parkinson’s Law","Work Expands","A task expands to fill the time it’s given. Autofill and smart defaults help people finish faster.",`<span class="row" style="gap:10px">${I('clock','lg')}<span class="col" style="gap:4px"><span class="row b xs" style="gap:4px">${I('wand','xs')}Autofill address</span>${L(90,'m t')}</span></span>`],
["Default Effect","Smart Defaults","Most people keep whatever is preselected, so choose defaults that are best for them.",`<div class="col" style="gap:5px">${['Standard (recommended)','Express','Pickup'].map((t,i)=>`<span class="row b xs" style="gap:6px"><span class="rad ${i?'':'on'}" style="width:16px;height:16px"></span>${t}</span>`).join('')}</div>`],
["Social Proof","Herd Behavior","People follow what others do, so honest ratings, reviews and user counts build trust.",`<div class="col" style="align-items:center;gap:5px"><span style="font-size:18px;letter-spacing:2px">★★★★★</span><span class="mono xs">4.8 from 2,431 reviews</span><span class="avg">${['AR','JM','KC'].map(t=>`<span class="av sm">${t}</span>`).join('')}</span></div>`],
["Anchoring","Anchoring Bias","The first number people see shapes how they judge the next one, like a crossed-out original price.",`<span class="row" style="gap:10px;align-items:baseline"><s class="mono ph" style="font-size:15px">₱2,000</s>${BIG('₱1,200',28)}</span>`],
["Scarcity","Scarcity Effect","Things feel more valuable when they’re limited. Faking scarcity is a dark pattern.",`<span class="row" style="gap:8px"><span class="chip on">Only 3 left</span><span class="mono xs">(only if true)</span></span>`],
["Loss Aversion","Fear of Loss","Losing something feels worse than gaining the same thing feels good, which is why streaks are powerful.",`<span class="box row" style="padding:8px 10px;gap:8px">${SP}<span class="col" style="gap:2px"><b class="b xs">7-day streak</b><span class="mono xs">Play today to keep it</span></span></span>`],
["Mapping","Natural Mapping","Controls laid out to match what they control, like stove knobs arranged like the burners.",`<span class="row" style="gap:14px"><span style="display:grid;grid-template-columns:repeat(2,28px);gap:6px">${[0,1,2,3].map(i=>`<i style="display:block;height:28px;border-radius:50%;border:2px solid var(--ink);${i===1?'background:var(--ink)':''}"></i>`).join('')}</span><span style="display:grid;grid-template-columns:repeat(2,14px);gap:5px">${[0,1,2,3].map(i=>`<i style="display:block;height:14px;border-radius:50%;border:2px solid var(--ink);${i===1?'background:var(--ink)':''}"></i>`).join('')}</span></span>`],
["Constraints","Design Constraints","Limits that prevent wrong actions, like greying out dates that can’t be booked.",CAL(d=>d<6?'dis':d===8?'on':'').replace(/class="dis"/g,'class="dis" style="text-decoration:line-through"')],
["Conceptual Model","Mental Map of the System","The simple explanation people form of how something works, like folders holding files.",`<span class="row" style="gap:8px">${I('folder','lg')}${SV(20,12,'<path d="M2 6h14M12 2l4 4-4 4"/>')}<span class="col" style="gap:3px">${['a.png','b.txt','c.pdf'].map(f=>`<span class="row mono xs" style="gap:4px">${I('img','xs')}${f}</span>`).join('')}</span></span>`],
["Discoverability","Findability","How easily people can figure out what actions exist and where they are.",GB('Actions hidden behind a long-press','Visible button with a label')],
["Gulfs of Execution & Evaluation","Norman’s Gulfs","The gap between what people want and how to do it (execution), and between what happened and understanding it (evaluation).",SV(180,80,`<path d="M4 70h50M126 70h50" stroke-width="3"/><path d="M54 70q36 20 72 0" stroke-dasharray="3 4"/><path d="M40 40h96M128 34l8 6-8 6" />${TX(88,34,'execution',8,'middle')}<path d="M136 56H44M52 50l-8 6 8 6"/>${TX(88,52,'evaluation',8,'middle')}${TX(28,82,'person',8,'middle')}${TX(152,82,'system',8,'middle')}`)]
]);

/* ---------- 24 nielsen ---------- */
S('heuristics','Usability Heuristics','flag','Jakob Nielsen’s 10 usability heuristics, in his order, plus Ben Shneiderman’s 8 golden rules.',[
["1. Visibility of System Status","Keep Users Informed","Always tell people what’s happening through timely feedback, like progress while uploading.",`<div class="box col" style="padding:8px 10px;gap:5px;width:170px"><span class="row sb b xs"><span>Uploading video</span><span class="mono">62%</span></span><span class="pbar thin"><i style="width:62%"></i></span></div>`],
["2. Match with the Real World","Speak the User’s Language","Use words, icons and order people already know, not internal jargon.",GB('Error 0x80070057','Your file name can’t include /')],
["3. User Control and Freedom","Emergency Exits","Give a clear way out of mistakes, with Undo, Cancel and Back.",`<span class="snack" style="position:static;width:170px">Quest deleted <b>UNDO</b></span>`],
["4. Consistency and Standards","Follow Conventions","Follow platform conventions so people never wonder if different words mean the same thing.",GB('Save, Store, Keep on three screens','Save on every screen')],
["5. Error Prevention","Prevent Problems","Better than a good error message is stopping the error, like disabling Send until the form is valid.",`<div class="col" style="gap:5px;align-items:flex-start">${IN('alex@')}<span class="btn fill sm dis">Send</span><span class="mono xs">Enter a full email to continue</span></div>`],
["6. Recognition Rather Than Recall","Show, Don’t Make Them Remember","Keep options visible so people don’t have to remember information from one screen to the next.",`<div class="col" style="gap:0;width:150px">${IN('pal|')}<div class="lbx" style="border-top-width:0;border-radius:0 0 10px 10px"><span class="on">Paladin</span><span>Palette</span></div></div>`],
["7. Flexibility and Efficiency","Shortcuts for Experts","Offer accelerators like keyboard shortcuts that experts love and beginners can ignore.",`<span class="row" style="gap:8px"><span class="lbx" style="min-width:90px"><span class="row sb">Save <span class="ph">⌘S</span></span><span class="row sb">Find <span class="ph">⌘F</span></span></span><span class="kbd">⌘</span><span class="kbd">S</span></span>`],
["8. Aesthetic and Minimalist Design","Remove the Noise","Every extra element competes with the important ones, so cut what doesn’t help.",`<div class="box col" style="padding:12px;gap:8px;align-items:center;width:130px">${BIG('Paladin',20)}<span class="btn fill sm">Play</span></div>`],
["9. Help Users Recover from Errors","Useful Error Messages","Say what went wrong in plain language and suggest a fix.",`<div class="callout col" style="gap:5px;border-left-color:var(--danger)"><b class="b xs">Card declined</b><span class="mono xs">Your bank said no. Try another card or call them.</span><span class="btn xs">Use another card</span></div>`],
["10. Help and Documentation","Findable Help","It’s best when no help is needed, but help should be easy to search and focused on tasks.",`<span class="row" style="gap:8px">${CB('question')}<span class="inp pill" style="min-width:120px">${I('search','xs')}<span class="it ph mono xs">How do I…</span></span></span>`],
["Shneiderman’s 8 Golden Rules","Golden Rules of Interface Design","Strive for consistency, design for everyone, give informative feedback, make dialogs end clearly, prevent errors, allow easy undo, keep users in control, and reduce memory load.",`<div class="col" style="align-items:center;gap:6px">${BIG('8',38)}${CH(['consistency','feedback','closure','undo'])}</div>`]
]);

/* ---------- 25 methods ---------- */
S('methods','Research & Product Methods','clip','How teams learn what to build and decide what comes first.',[
["Stakeholder Interview","Kickoff Interview","Talking with the people who own or fund a project to learn goals, limits and how success is measured.",`<span class="row" style="gap:6px"><span class="av">PM</span><span class="pop" style="padding:6px 8px"><span class="mono xs">What does success look like?</span></span></span>`],
["User Interview","One-on-one Interview","A conversation with a real user about their needs and frustrations. Ask about past behavior, not predictions.",`<span class="row" style="gap:8px">${CB('mic','fill')}<span class="col" style="gap:4px"><span class="mono xs">“Tell me about the last time you…”</span>${L(100,'m t')}</span></span>`],
["Survey","Questionnaire","A set of questions sent to many people to measure attitudes at scale.",`<div class="col" style="gap:5px;align-items:center"><b class="b xs">How easy was checkout?</b><span class="row" style="gap:5px" data-group>${[1,2,3,4,5].map(n=>`<button type="button" data-rg class="otp ${n===4?'on':''}" style="width:24px;height:24px;font-size:11px;${''}">${n}</button>`).join('')}</span></div>`],
["Contextual Inquiry","Field Study","Watching and interviewing people where they really do the task, like at their desk or in a shop.",`<span class="row" style="gap:10px">${CB('eye')}<span class="frame" style="width:110px;height:64px;display:grid;place-items:end center;padding:6px">${SV(90,40,'<path d="M5 38h80M20 38V20h50v18M38 20v-8h14v8"/>')}</span></span>`],
["Diary Study","Longitudinal Study","Participants log their experiences over days or weeks, capturing behavior a single session misses.",`<span class="row" style="gap:3px">${['M','T','W','T','F'].map((d,i)=>`<span class="col box" style="width:30px;padding:3px;gap:3px;align-items:center"><span class="mono xs">${d}</span>${i%2?L(18,'m t'):`<span class="sticky-n" style="width:22px;height:18px;padding:0"></span>`}</span>`).join('')}</span>`],
["Competitive Analysis","Competitor Audit","Reviewing similar products to learn what they do well, what they miss, and where you can stand out.",`<table class="tbl"><tr><th></th><th>A</th><th>B</th><th>You</th></tr>${[['Search',1,1,1],['Dark mode',0,1,1],['Offline',0,0,1]].map(r=>`<tr><td>${r[0]}</td>${r.slice(1).map(v=>`<td>${v?'✓':'—'}</td>`).join('')}</tr>`).join('')}</table>`],
["Affinity Mapping","Affinity Diagram","Grouping research notes on sticky notes into themes to see patterns.",`<span class="row" style="gap:12px;align-items:flex-start">${[3,2].map((n,g)=>`<span class="col" style="gap:3px;align-items:center"><b class="b xs">${['Pricing','Speed'][g]}</b>${'<span class="sticky-n" style="height:18px"></span>'.repeat(n)}</span>`).join('')}</span>`],
["Empathy Map","Says, Thinks, Does, Feels","A four-part board capturing what a user says, thinks, does and feels.",`<span style="display:grid;grid-template-columns:repeat(2,70px);grid-auto-rows:38px;border:2px solid var(--ink);border-radius:10px;overflow:hidden;background:var(--paper)">${['Says','Thinks','Does','Feels'].map((t,i)=>`<span class="b xs" style="padding:4px;border-right:${i%2?0:1.5}px solid var(--ink);border-bottom:${i<2?1.5:0}px solid var(--ink)">${t}</span>`).join('')}</span>`],
["Jobs to Be Done","JTBD","Framing needs as the job someone hires a product to do: When I…, I want to…, so I can…",`<div class="box" style="width:176px;padding:10px;font:italic 800 12px/1.35 Fraunces,serif">When I’m on the bus, I want to learn in short bursts, so I can use dead time.</div>`],
["How Might We","HMW Question","Turning a problem into an open question that invites ideas.",`<div class="box" style="width:170px;padding:10px;font:italic 800 13px/1.35 Fraunces,serif;background:#f7d774;color:#222">How might we make saving money feel like leveling up?</div>`],
["Problem Statement","Point of View","A short, specific description of the user’s problem that the team agrees to solve.",`<div class="callout col" style="gap:4px"><b class="b xs">Problem</b><span class="mono xs">Students drop off at checkout because shipping costs appear too late.</span></div>`],
["Tree Testing","Reverse Card Sort","Testing whether people can find items in your menu structure, with no visual design involved.",`<div class="col mono xs tree" style="gap:3px"><span>▾ Home</span><span style="padding-left:12px">▸ Shop</span><span style="padding-left:12px;font-weight:700">▾ Account</span><span style="padding-left:24px;background:var(--ink);color:var(--paper);border-radius:4px;padding-right:6px">Order history ✓</span><span style="padding-left:12px">▸ Help</span></div>`],
["First-click Testing","First Click Test","Checking where people click first for a task. A correct first click strongly predicts success.",`<div class="frame">${FL}<span style="position:absolute;right:20px;top:26px;width:28px;height:28px;border-radius:50%;background:radial-gradient(circle,rgba(200,55,45,.8),transparent 70%)"></span><span style="position:absolute;left:30px;top:60px;width:18px;height:18px;border-radius:50%;background:radial-gradient(circle,rgba(200,55,45,.5),transparent 70%)"></span></div>`],
["Five-second Test","First Impression Test","Showing a design for five seconds, then asking what people remember about it.",`<span class="row" style="gap:10px"><span class="cb fill" style="width:50px;height:50px;font:900 20px Fraunces,serif">5s</span><span class="frame" style="width:96px;height:64px">${FL}</span></span>`],
["Guerrilla Testing","Hallway Testing","Quick, informal tests with whoever is nearby, like classmates or people in a café.",`<span class="row" style="gap:8px"><span class="av">?</span><span class="phone" style="width:40px;height:66px"></span><span class="mono xs">“Can you find<br>the settings?”</span></span>`],
["Heatmap","Click Map, Scroll Map","A map colored by where people click, move or scroll the most.",`<div class="frame">${FL}<span style="position:absolute;inset:0;background:radial-gradient(circle at 30% 25%,rgba(255,60,0,.55),transparent 25%),radial-gradient(circle at 75% 70%,rgba(255,200,0,.5),transparent 22%),radial-gradient(circle at 60% 30%,rgba(255,140,0,.35),transparent 18%)"></span></div>`],
["Eye Tracking","Gaze Tracking","Measuring where people look on a screen and in what order.",`<div class="frame">${FL}${SV(176,104,`<path d="M20 20L120 18 40 50 90 60 150 80" stroke-width="1.5" stroke="#c8372d"/>${[[20,20],[120,18],[40,50],[90,60],[150,80]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="7" fill="#c8372d" stroke="none" opacity=".85"/><text x="${x}" y="${y+3}" font-size="8" fill="#fff" stroke="none" text-anchor="middle" font-family="Archivo">${i+1}</text>`).join('')}`).replace('<svg','<svg style="position:absolute;inset:0"')}</div>`],
["Session Recording","Session Replay","Recordings of real users’ clicks and scrolls, used to spot where they get stuck.",`<div class="frame">${FL}${CUR(110,40)}<span style="position:absolute;left:0;right:0;bottom:0;padding:5px 8px;background:var(--ink);display:flex;gap:6px;align-items:center;color:var(--paper)">${I('play','xs')}<span class="scr" style="background:rgba(255,255,255,.3)"><i style="width:40%"></i></span><span class="mono xs">0:42</span></span></div>`],
["Analytics","Product Analytics","Measuring what people do in the product, such as visits, clicks and conversions.",LINE([18,26,22,40,36,52,60],true)],
["Funnel Analysis","Conversion Funnel","Tracking how many people drop off at each step of a flow, like browse, cart, pay.",`<div class="col" style="gap:3px;align-items:center">${[['Visit','100%',170],['Cart','38%',110],['Pay','12%',56]].map(([l,p,w])=>`<span class="row b xs" style="gap:0;width:${w}px;height:22px;background:var(--ink);color:var(--paper);border-radius:5px;justify-content:space-between;padding:0 7px"><span>${l}</span><span class="mono">${p}</span></span>`).join('')}</div>`],
["Conversion Rate","CVR","The share of visitors who complete a goal, such as buying or signing up.",`<div class="col" style="align-items:center;gap:4px">${BIG('3.2%',36)}${LB('of visitors bought')}</div>`],
["Task Success Rate","Completion Rate","The percentage of test participants who complete a task.",`<div class="col" style="align-items:center;gap:6px"><span class="row" style="gap:4px">${Array.from({length:10},(_,i)=>`<i style="display:block;width:13px;height:13px;border-radius:50%;border:2px solid var(--ink);background:${i<8?'var(--ink)':'var(--paper)'}"></i>`).join('')}</span><span class="mono xs">8 of 10 succeeded</span></div>`],
["Time on Task","Task Time","How long a task takes. Faster usually means easier.",`<span class="row" style="gap:10px">${I('clock','lg')}${BIG('1:42',30)}</span>`],
["SUS","System Usability Scale","A standard 10-question survey that scores usability from 0 to 100. About 68 is average.",SV(130,76,`<path d="M15 66a50 50 0 0 1 100 0" stroke="var(--soft)" stroke-width="10"/><path d="M15 66a50 50 0 0 1 81-39" stroke-width="10"/><path d="M65 66L88 34" stroke-width="3"/>${TX(65,60,'68',14,'middle')}`)],
["NPS","Net Promoter Score","Asks how likely people are to recommend you from 0 to 10, then subtracts detractors (0–6) from promoters (9–10).",`<span class="row" style="gap:2px">${Array.from({length:11},(_,i)=>`<span style="width:15px;height:24px;border-radius:4px;display:grid;place-items:center;font:700 8px Archivo,sans-serif;color:#fff;background:${i<7?'#c8372d':i<9?'#c98a00':'#2e9d5b'}">${i}</span>`).join('')}</span>`],
["CSAT","Customer Satisfaction Score","A quick rating of one interaction, often 1 to 5 stars or faces.",`<span class="row" style="gap:6px;font-size:22px">${['😞','🙁','😐','🙂','😄'].map((e,i)=>`<span style="${i===4?'outline:2px solid var(--ink);border-radius:50%':'opacity:.5'}">${e}</span>`).join('')}</span>`],
["Service Blueprint","Service Map","A diagram of a service showing what the customer does, what staff do on and off stage, and the systems behind them.",`<div class="col" style="gap:0;width:180px">${['Customer','Front stage','Back stage'].map((r,i)=>`<span class="row" style="gap:4px;padding:4px 0;border-top:${i===2?'1.5px dashed var(--danger)':i?'1.5px solid var(--soft)':'0'}"><span class="mono xs" style="width:52px">${r}</span>${'<span class="box" style="width:30px;height:14px;border-radius:4px"></span>'.repeat(3)}</span>`).join('')}</div>`],
["Design Sprint","Five-day Sprint","A five-day process from problem to tested prototype: map, sketch, decide, prototype, test.",`<span class="row" style="gap:3px">${['Map','Sketch','Decide','Proto','Test'].map((t,i)=>`<span class="col" style="align-items:center;gap:2px"><span class="chip sm ${i===4?'on':''}" style="width:34px;justify-content:center;padding:0">${['M','T','W','T','F'][i]}</span><span class="mono" style="font-size:7px">${t}</span></span>`).join('')}</span>`],
["Lean UX","Build, Measure, Learn","Shipping small experiments quickly and learning from real data instead of writing big documents first.",SV(150,90,`<path d="M75 14a32 32 0 1 1-28 16"/><path d="M40 22l7 9 9-7"/>${TX(75,12,'build',8,'middle')}${TX(118,70,'measure',8,'middle')}${TX(30,74,'learn',8,'middle')}`)],
["Agile & Scrum","Sprints","Building in short cycles (often two weeks) with planning, daily stand-ups and reviews.",`<span class="row" style="gap:8px">${SV(60,60,'<path d="M30 8a22 22 0 1 1-20 13"/><path d="M5 16l5 6 7-4"/>')}<span class="col" style="gap:3px">${CH(['plan','build','review'])}</span></span>`],
["Design Critique","Crit","A structured session where designers get feedback on work against its goals, not personal taste.",`<span class="row" style="gap:8px"><span class="frame" style="width:70px;height:60px">${FL}</span><span class="col" style="gap:4px">${['Is the CTA clear?','Try more contrast'].map(t=>`<span class="pop" style="padding:3px 6px"><span class="mono xs">${t}</span></span>`).join('')}</span></span>`],
["MoSCoW","Must, Should, Could, Won’t","A way to sort features into four priority buckets.",`<div style="display:grid;grid-template-columns:repeat(2,78px);gap:4px">${[['Must',1],['Should',0],['Could',0],['Won’t',0]].map(([t,o])=>`<span class="chip ${o?'on':''}" style="justify-content:center">${t}</span>`).join('')}</div>`],
["RICE Scoring","Reach × Impact × Confidence ÷ Effort","A formula for ranking ideas by value against effort.",CODE(`score = (reach × impact
        × confidence)
        ÷ effort`)],
["North Star Metric","NSM","The one number that best captures the value a product gives users, like weekly active learners.",`<div class="col" style="align-items:center;gap:4px">${SP.replace('class="sp"','class="sp" style="width:26px;height:26px"')}${BIG('12,480',26)}${LB('weekly active learners')}</div>`],
["KPI & OKR","Key Results","KPIs are ongoing health numbers; OKRs pair an ambitious objective with measurable key results.",`<div class="box col" style="padding:8px;gap:5px;width:170px"><b class="b xs">O: Make onboarding effortless</b>${[80,45,20].map((p,i)=>`<span class="row mono xs" style="gap:6px"><span>KR${i+1}</span><span class="pbar thin" style="flex:1;height:8px"><i style="width:${p}%"></i></span></span>`).join('')}</div>`],
["Design Brief","Project Brief","A short document setting a project’s goal, audience, scope and deadline before design starts.",`<div class="box col" style="padding:9px;gap:5px;width:140px"><b class="b xs">Brief</b>${['Goal','Audience','Scope','Due'].map(t=>`<span class="row mono xs" style="gap:6px"><b style="width:46px">${t}</b>${L(50,'m t')}</span>`).join('')}</div>`],
["Design Debt","UX Debt","Inconsistencies and shortcuts that pile up over time and make a product harder to use and change.",`<div class="col" style="gap:5px;align-items:center"><span class="row" style="gap:5px"><span class="btn sm fill">Save</span><span class="btn sm" style="border-radius:4px">SAVE</span><span style="font:12px Times,serif;border:1px solid;padding:2px 5px">save</span></span>${LB('three “Save” buttons, three styles')}</div>`]
]);

/* ---------- 26 a11y deep ---------- */
S('a11y','Accessibility Deep Dive','eye','The details that make interfaces work for everyone.',[
["POUR","Perceivable, Operable, Understandable, Robust","WCAG’s four principles: people must be able to perceive content, operate the controls, understand them, and use them with assistive technology.",`<span class="row" style="gap:5px">${['P','O','U','R'].map(l=>`<span class="cb fill" style="width:38px;height:38px;font:900 18px Fraunces,serif">${l}</span>`).join('')}</span>`],
["Semantic HTML","Meaningful Markup","Using the right element for the job, like button for actions and nav for navigation, so assistive tech understands the page.",GB('&lt;div onclick="save()"&gt;','&lt;button&gt;Save&lt;/button&gt;')],
["Landmarks","Page Regions","Labeled regions like header, nav, main and footer that screen reader users can jump between.",`<div class="frame col" style="gap:3px;padding:4px">${['header','nav','main','footer'].map(t=>`<span class="mono xs" style="border:1.5px dashed var(--ink);border-radius:4px;padding:${t==='main'?'12px':'2px'} 6px">${t}</span>`).join('')}</div>`],
["Heading Structure","Heading Levels","Using h1 to h6 in order so people can skim and jump through a page by its headings.",`<div class="col mono xs" style="gap:3px">${[['h1','Field Guide',0],['h2','Inputs',12],['h3','Slider',24],['h3','Stepper',24],['h2','Navigation',12]].map(([h,t,p])=>`<span style="padding-left:${p}px"><b>${h}</b> ${t}</span>`).join('')}</div>`],
["Accessible Name","Label","The text assistive technology announces for an element, taken from its label, its content or aria-label.",`<span class="row" style="gap:8px">${CB('trash')}<span class="pop" style="padding:5px 8px"><span class="mono xs">name: “Delete quest”</span></span></span>`],
["Focus Trap","Modal Focus","Keeping keyboard focus inside an open dialog until it closes, then returning focus where it was.",`<div class="frame"><span class="scrim"></span><div class="dlg col"><span class="btn xs" style="outline:2px solid var(--ink);outline-offset:2px">Cancel</span><span class="btn xs fill">Delete</span>${SV(30,24,'<path d="M24 4a10 10 0 1 1-18 6M2 6l4 4 4-4"/>').replace('<svg','<svg style="position:absolute;right:-10px;top:10px;color:var(--paper)"')}</div></div>`],
["Focus Management","Moving Focus","Sending focus to the right place after a change, like the first field of a new step or an error summary.",`<span class="row" style="gap:8px"><span class="btn sm fill">Next</span>${SV(20,12,'<path d="M2 6h14M12 2l4 4-4 4"/>')}${IN('|','foc').replace('class="inp foc"','class="inp" style="outline:3px solid var(--ink);outline-offset:3px;min-width:90px"')}</span>`],
["Live Region","aria-live","An area whose updates are read out automatically, like a Saved message or a cart count.",`<div class="col" style="gap:6px;align-items:center"><span class="toast" style="position:static;transform:none">${I('check','xs')} Saved</span>${CODE('aria-live="polite"')}</div>`],
["Captions","Subtitles","Text of speech and important sounds shown on video, for deaf viewers and anyone watching muted.",`<div class="vp"><span class="cb sm">${I('play','xs')}</span><span style="background:rgba(0,0,0,.75);color:#fff;font:600 10px Archivo,sans-serif;padding:3px 6px;margin:0 auto 8px;border-radius:4px">[sword clangs] On your left!</span></div>`],
["Transcript","Text Alternative","A full text version of audio or video content that people can read or search.",`<div class="box col" style="padding:8px;gap:5px;width:170px"><span class="row b xs" style="gap:5px">${I('play','xs')}Episode 4</span>${['0:00 Welcome back…','0:14 Today we level…','0:31 First, open…'].map(t=>`<span class="mono xs">${t}</span>`).join('')}</div>`],
["Audio Description","Described Video","Narration that describes important visual details in a video for blind and low-vision viewers.",`<span class="row" style="gap:8px">${CB('vol','fill')}<span class="pop" style="padding:5px 8px"><span class="mono xs">“The knight raises his shield.”</span></span></span>`],
["Text Resize","Zoom to 200%","Text must stay readable and the layout must keep working when zoomed to 200%.",`<span class="row" style="gap:10px;align-items:baseline"><span style="font:14px Archivo,sans-serif">Aa</span>${SV(20,12,'<path d="M2 6h14M12 2l4 4-4 4"/>')}<span style="font:800 32px Archivo,sans-serif">Aa</span><span class="mono xs">200%</span></span>`],
["Reflow","No Sideways Scrolling","Content should fit a 320px-wide screen without horizontal scrolling.",`<span class="row" style="gap:10px"><span class="phone" style="width:52px;padding:6px;display:flex;flex-direction:column;gap:4px">${L(36,'t')}${L(30,'m t')}${L(36,'m t')}${L(26,'m t')}</span><span class="mono xs">320px wide,<br>no scroll ↔</span></span>`],
["Forced Colors","High Contrast Mode","A system setting that swaps your colors for the user’s chosen high-contrast palette. Don’t hide meaning in background colors.",`<span class="box col" style="padding:10px;gap:6px;background:#000;color:#ff0;border-color:#fff;width:150px"><b class="b sm" style="color:#fff">Settings</b><span style="border:2px solid #0ff;color:#0ff;border-radius:6px;padding:3px 8px;font:700 10px Archivo,sans-serif;align-self:flex-start">Save</span><u class="b xs">Link text</u></span>`],
["Use of Color","Don’t Rely on Color Alone","Information shown with color must also be shown another way, like an icon, a pattern or text.",`<div class="col" style="gap:6px">${IN('alex@','err')}<span class="errt">${I('warn','xs')} Missing the domain</span></div>`],
["Non-text Contrast","3:1 Contrast","Icons, input borders and focus rings need at least 3:1 contrast against what’s around them.",`<span class="row" style="gap:10px"><span class="col" style="align-items:center;gap:3px"><span style="width:70px;height:26px;border:2px solid #e2ded5;border-radius:8px;display:block"></span>${LB('1.2:1 ✕')}</span><span class="col" style="align-items:center;gap:3px"><span style="width:70px;height:26px;border:2px solid var(--ink);border-radius:8px;display:block"></span>${LB('15:1 ✓')}</span></span>`],
["Screen Magnifier","Zoom Software","Software that enlarges part of the screen for low-vision users.",`<span style="position:relative;display:block;width:170px;height:80px"><span class="col" style="gap:6px;padding:8px">${L(140,'m t')}${L(120,'m t')}${L(150,'m t')}</span><span style="position:absolute;left:60px;top:6px;width:66px;height:66px;border-radius:50%;border:3px solid var(--ink);background:var(--paper);display:grid;place-items:center;font:800 22px Archivo,sans-serif;box-shadow:4px 4px 0 var(--mute)">Lv.4</span></span>`],
["Voice Control","Voice Access","Controlling a device by speaking, like “Click Submit”. Visible labels must match the accessible names.",`<span class="row" style="gap:8px">${CB('mic','fill')}<span class="pop" style="padding:5px 8px"><span class="mono xs">“Click Submit”</span></span><span class="btn sm fill" style="outline:2px dashed var(--ink);outline-offset:3px">Submit</span></span>`],
["Switch Access","Switch Control","Using one button or switch to move through items one at a time, for people with limited movement.",`<span class="row" style="gap:12px"><span class="col" style="gap:4px">${[0,1,2].map(i=>`<span class="box" style="width:60px;height:16px;${i===1?'outline:3px solid #c8372d;outline-offset:2px':''}"></span>`).join('')}</span><span class="cb fill a-pulse" style="width:46px;height:46px"></span></span>`],
["Plain Language","Cognitive Accessibility","Short sentences, common words and clear steps help everyone, especially people with cognitive or learning disabilities.",GB('Authentication credentials invalid','Wrong password. Try again.')],
["Accessible Forms","Form Accessibility","Every input has a visible label, errors are described in text and tied to their field, and required fields are marked.",`<div class="col" style="gap:4px"><span class="lab">Email <b style="color:var(--danger)">*</b></span>${IN('alex@','err')}<span class="errt">${I('warn','xs')} Add the part after @</span></div>`],
["Accessibility Audit","A11y Audit","A systematic check against WCAG using automated tools, keyboard testing and screen readers.",`<div class="col" style="gap:4px">${[['Contrast',1],['Keyboard',1],['Alt text',0],['Labels',1]].map(([t,ok])=>`<span class="row b xs" style="gap:6px"><span style="color:${ok?'var(--ok)':'var(--danger)'}">${I(ok?'check':'x','s')}</span>${t}</span>`).join('')}</div>`],
["Inclusive Design","Universal Design","Designing for the full range of people from the start. Fixes for one group often help everyone, like captions in a noisy room.",`<span class="avg">${['AR','JM','KC','AL','RB'].map(t=>`<span class="av">${t}</span>`).join('')}</span>`]
]);

/* ---------- 27 data viz ---------- */
S('dataviz','Data Visualization','chart','Chart types and the parts that make them readable.',[
["Bar Chart","Column Chart","Rectangles whose lengths compare values across categories. The safest chart for comparing amounts.",BAR([40,62,28,70,50])],
["Horizontal Bar Chart","Bar Chart (horizontal)","Bars running sideways, which leaves room for long category names.",`<div class="col" style="gap:5px">${[['Sword',90],['Bow',64],['Key',40],['Potion',24]].map(([t,v])=>`<span class="row" style="gap:6px"><span class="mono xs" style="width:38px">${t}</span><i style="display:block;height:12px;width:${v*1.3}px;background:var(--ink);border-radius:3px"></i></span>`).join('')}</div>`],
["Stacked Bar Chart","Stacked Column","Bars split into segments to show parts of a whole across categories.",SV(170,88,AX+[[30,20,14],[40,14,20],[22,28,10],[34,22,18]].map((s,i)=>{let y=80;return s.map((h,j)=>{y-=h;return `<rect x="${22+i*36}" y="${y}" width="24" height="${h}" fill="${['currentColor','var(--mute)','var(--soft)'][j]}" stroke="none"/>`;}).join('');}).join(''))],
["Line Chart","Trend Line","Points joined by a line to show change over time.",LINE([20,34,28,50,44,62])],
["Area Chart","Filled Line Chart","A line chart with the space below filled in, emphasizing volume over time.",LINE([18,30,26,46,40,58,52],true)],
["Pie Chart","Pie","A circle split into slices that show parts of a whole. Hard to compare more than a few slices.",PIE('var(--ink) 0 45%,var(--mute) 0 72%,var(--soft) 0')],
["Donut Chart","Ring Chart","A pie chart with a hole in the middle, often holding a total.",`<span style="position:relative;display:inline-grid;place-items:center">${PIE('var(--ink) 0 62%,var(--soft) 0',true)}<b class="fr" style="position:absolute;font-size:16px">62%</b></span>`],
["Scatter Plot","XY Plot","Dots placed by two values to show whether they’re related.",SV(170,88,AX+RND(22,5).map((r,i)=>{const x=14+i*7;const y=74-i*2.6-r*16;return `<circle cx="${x}" cy="${y}" r="3" fill="currentColor" stroke="none"/>`;}).join(''))],
["Bubble Chart","Bubble Plot","A scatter plot where each dot’s size shows a third value.",SV(170,88,AX+[[40,50,8],[70,30,14],[110,52,10],[140,22,18],[90,66,6]].map(([x,y,r])=>`<circle cx="${x}" cy="${y}" r="${r}" fill="currentColor" stroke="none" opacity=".55"/>`).join(''))],
["Histogram","Frequency Chart","Touching bars that show how often values fall into ranges, revealing the shape of the data.",SV(170,88,AX+[10,22,38,56,64,48,30,16,8].map((h,i)=>`<rect x="${12+i*17}" y="${80-h}" width="17" height="${h}" fill="currentColor" stroke="var(--paper)" stroke-width="1"/>`).join(''))],
["Heatmap Chart","Matrix Heatmap","A grid of cells colored by value, showing patterns across two dimensions.",`<span style="display:grid;grid-template-columns:repeat(7,20px);gap:2px">${RND(28,11).map(v=>`<i style="display:block;height:20px;border-radius:3px;background:var(--ink);opacity:${.1+v*.9}"></i>`).join('')}</span>`],
["Calendar Heatmap","Contribution Graph","A calendar grid of small squares shaded by activity each day.",`<span style="display:grid;grid-template-rows:repeat(7,9px);grid-auto-flow:column;gap:2px">${RND(98,7).map(v=>`<i style="display:block;width:9px;height:9px;border-radius:2px;background:${v<.3?'var(--soft)':'#2e9d5b'};opacity:${v<.3?1:.3+v*.7}"></i>`).join('')}</span>`],
["Treemap","Nested Rectangles","Rectangles sized by value and nested by category, for showing parts of a whole with many items.",`<span style="display:grid;grid-template-columns:90px 50px 30px;grid-template-rows:40px 30px;gap:3px">${[['grid-row:span 2',1],['',.6],['',.3],['grid-column:span 2',.45]].map(([s,o])=>`<i style="display:block;${s};border-radius:4px;background:var(--ink);opacity:${o}"></i>`).join('')}</span>`],
["Funnel Chart","Funnel","Narrowing bars showing how many people pass through each step.",`<div class="col" style="gap:3px;align-items:center">${[170,130,90,50].map((w,i)=>`<i style="display:block;width:${w}px;height:16px;background:var(--ink);opacity:${1-i*.2};clip-path:polygon(0 0,100% 0,${100-6}% 100%,6% 100%)"></i>`).join('')}</div>`],
["Gauge","Dial Chart","A half circle with a needle showing one value against a range, like a speedometer.",SV(130,76,`<path d="M15 66a50 50 0 0 1 100 0" stroke="var(--soft)" stroke-width="10"/><path d="M15 66a50 50 0 0 1 50-50" stroke-width="10"/><path d="M65 66L50 30" stroke-width="3"/><circle cx="65" cy="66" r="4" fill="currentColor"/>`)],
["Radar Chart","Spider Chart","Values plotted on spokes from a center and joined into a shape, for comparing several attributes at once.",SV(120,100,`${[40,26,13].map(r=>`<polygon points="${[0,1,2,3,4,5].map(i=>{const a=Math.PI/3*i-Math.PI/2;return `${60+r*Math.cos(a)},${52+r*Math.sin(a)}`;}).join(' ')}" fill="none" stroke-width="1" opacity=".35"/>`).join('')}<polygon points="${[36,22,30,14,34,26].map((r,i)=>{const a=Math.PI/3*i-Math.PI/2;return `${60+r*Math.cos(a)},${52+r*Math.sin(a)}`;}).join(' ')}" fill="currentColor" fill-opacity=".3"/>`)],
["Sankey Diagram","Flow Diagram","Bands whose widths show how quantities flow from one stage to the next.",SV(176,90,'<path d="M20 20C90 20 90 18 156 18" stroke-width="16" opacity=".8"/><path d="M20 46C90 46 90 52 156 52" stroke-width="12" opacity=".5"/><path d="M20 70C90 70 90 30 156 30" stroke-width="6" opacity=".35"/><path d="M14 8v74M162 8v60" stroke-width="5"/>')],
["Gantt Chart","Project Timeline","Bars on a timeline showing when each task starts and ends, and how they overlap.",`<div class="col" style="gap:4px;width:176px">${[['Research',0,40],['Design',30,50],['Build',60,70],['Test',110,40]].map(([t,s,w])=>`<span class="row" style="gap:6px"><span class="mono xs" style="width:44px">${t}</span><span style="position:relative;flex:1;height:12px"><i style="position:absolute;left:${s*.85}px;width:${w*.85}px;height:12px;border-radius:4px;background:var(--ink)"></i></span></span>`).join('')}</div>`],
["Org Chart","Hierarchy Chart","Boxes and lines showing who reports to whom.",SV(170,80,'<rect x="65" y="4" width="40" height="18" rx="5" fill="currentColor"/><path d="M85 22v10M30 32h110M30 32v8M85 32v8M140 32v8"/><rect x="10" y="40" width="40" height="18" rx="5" fill="var(--paper)"/><rect x="65" y="40" width="40" height="18" rx="5" fill="var(--paper)"/><rect x="120" y="40" width="40" height="18" rx="5" fill="var(--paper)"/><path d="M85 58v8"/><rect x="70" y="66" width="30" height="12" rx="4" fill="var(--soft)"/>')],
["Pivot Table","Summary Table","A table that groups and totals data by categories, which you can rearrange to see different summaries.",`<table class="tbl"><tr><th>Class</th><th>Q1</th><th>Q2</th></tr><tr><td><b>Paladin</b></td><td>40</td><td>52</td></tr><tr><td><b>Mage</b></td><td>31</td><td>27</td></tr><tr><td style="background:var(--soft)"><b>Total</b></td><td style="background:var(--soft)"><b>71</b></td><td style="background:var(--soft)"><b>79</b></td></tr></table>`],
["Choropleth Map","Shaded Map","A map whose regions are shaded by a value, like population by province.",SV(170,92,'<path d="M10 20L50 10 70 30 40 50 14 44z" fill="currentColor" opacity=".85"/><path d="M70 30L110 16 130 40 96 56 40 50z" fill="currentColor" opacity=".45"/><path d="M14 44L40 50 96 56 80 84 20 80z" fill="currentColor" opacity=".25"/><path d="M96 56L130 40 160 60 140 86 80 84z" fill="currentColor" opacity=".65"/>')],
["Legend","Key","The guide that explains what each color, shape or line in a chart means.",`<div class="col" style="gap:6px;align-items:center">${BAR([40,62,28,70])}<span class="row mono xs" style="gap:12px"><span class="row" style="gap:4px">${SW('var(--ink)',10)}2025</span><span class="row" style="gap:4px">${SW('var(--mute)',10)}2026</span></span></div>`.replace('height="88"','height="60"')],
["Axis & Ticks","Chart Axis","The scale lines along a chart’s edges, with tick marks and labels for values.",SV(170,88,`${AX}${[0,1,2,3].map(i=>`<path d="M6 ${80-i*24}h4" stroke-width="1.5"/>${TX(4,83-i*24,i*25,7,'end')}`).join('').replace(/x="4"/g,'x="5"')}${['Q1','Q2','Q3','Q4'].map((q,i)=>`<path d="M${30+i*40} 80v4" stroke-width="1.5"/>${TX(30+i*40,88,q,7,'middle')}`).join('')}`).replace('viewBox="0 0 170 88"','viewBox="-12 0 182 92"')],
["Gridlines","Chart Grid","Light lines across a chart that help readers line values up with the axis. Keep them faint.",LINE([20,34,28,50,44,62],false,[20,40,60].map(y=>`<path d="M10 ${80-y}h156" stroke-width="1" opacity=".2"/>`).join(''))],
["Data Labels","Value Labels","Numbers printed right on bars or points so readers don’t have to estimate.",BAR([40,62,28,70,50],true)],
["Chart Tooltip","Data Tooltip","A small box that appears on hover or tap with the exact values for one point.",`<span style="position:relative;display:block">${LINE([20,34,28,50,44,62])}<span class="tip" style="position:absolute;left:84px;top:4px">Q4: 50</span></span>`],
["Annotation","Chart Callout","A note placed on a chart to explain a spike, dip or event.",`<span style="position:relative;display:block">${LINE([20,24,22,64,40,44])}<span class="pop" style="position:absolute;left:100px;top:2px;padding:3px 6px"><span class="mono xs">Launch day</span></span></span>`],
["Small Multiples","Trellis Chart","Many small charts with the same scale side by side, making comparisons easy.",`<span style="display:grid;grid-template-columns:repeat(2,80px);gap:5px">${[[2,8,5,12],[10,6,9,4],[3,5,9,14],[8,8,7,9]].map(v=>`<span class="box" style="padding:4px;line-height:0">${SV(70,30,`<path d="M2 ${28-v[0]*1.8}L24 ${28-v[1]*1.8}L46 ${28-v[2]*1.8}L68 ${28-v[3]*1.8}"/>`)}</span>`).join('')}</span>`]
]);

/* ---------- 28 platforms ---------- */
S('platforms','Platform Patterns','globe','Names that come from specific platforms and design systems.',[
["Material Design","Material 3, Material You","Google’s design system for Android and the web, built around layered surfaces, bold color and motion.",`<div class="phone" style="width:96px;background:#f3edf7;color:#1d1b20"><div style="padding:8px" class="col"><b style="font:800 11px Archivo,sans-serif">Inbox</b><span style="height:28px;border-radius:12px;background:#fff;display:block"></span><span style="height:28px;border-radius:12px;background:#fff;display:block"></span></div><span style="position:absolute;right:8px;bottom:8px;width:30px;height:30px;border-radius:10px;background:#eaddff;color:#21005d;display:grid;place-items:center">${I('pen','s')}</span></div>`],
["Apple HIG","Human Interface Guidelines","Apple’s design guidance for iPhone, iPad, Mac, Apple Watch, Apple TV and Vision Pro.",`<div class="phone" style="width:96px;background:#f2f2f7;color:#000"><div class="col" style="padding:8px;gap:5px"><b style="font:800 15px system-ui,sans-serif">Settings</b><span style="background:#fff;border-radius:10px;display:flex;flex-direction:column">${['Wi-Fi','Bluetooth'].map((t,i)=>`<span style="font:10px system-ui,sans-serif;padding:5px 7px;${i?'border-top:1px solid #ddd':''}">${t}</span>`).join('')}</span></div></div>`],
["Fluent Design","Microsoft Fluent","Microsoft’s design system for Windows and Office, known for light, depth and soft translucent materials.",`<div style="width:160px;height:96px;border-radius:8px;background:linear-gradient(135deg,#7aa7e8,#c7b7f0);padding:10px"><div style="height:100%;border-radius:6px;background:rgba(255,255,255,.55);backdrop-filter:blur(6px);border:1px solid rgba(255,255,255,.8);padding:8px;color:#111"><b style="font:700 10px 'Segoe UI',system-ui,sans-serif">Settings</b></div></div>`],
["Other Design Systems","Carbon, Ant, Polaris, Atlassian","Public design systems from IBM (Carbon), Ant Group (Ant Design), Shopify (Polaris) and Atlassian that teams study and borrow from.",CH(['Carbon','Ant Design','Polaris','Atlassian','Primer','Spectrum'])],
["Large Title","iOS Large Title","A big bold screen title on iOS that shrinks into the navigation bar as you scroll.",`<div class="phone" style="width:96px"><div class="col" style="padding:8px;gap:6px"><b style="font:900 18px system-ui,sans-serif">Quests</b>${L(70,'m t')}${L(60,'m t')}${L(70,'m t')}</div></div>`],
["Dynamic Island","iPhone Island","The pill at the top of newer iPhones that expands to show live activity like timers, calls and music.",`<div class="phone" style="width:110px;background:#f2f2f2"><span style="position:absolute;left:8px;right:8px;top:6px;height:28px;border-radius:16px;background:#000;color:#fff;display:flex;align-items:center;gap:6px;padding:0 8px;font:700 9px system-ui,sans-serif">${I('clock','xs')}<span style="flex:1">Timer</span><span>4:59</span></span></div>`],
["Live Activity","Live Activities","Real-time updates on the iPhone lock screen and Dynamic Island, like a delivery or a game score.",`<div style="width:170px;border-radius:16px;background:#1c1c1e;color:#fff;padding:10px;display:flex;flex-direction:column;gap:6px;font:700 10px system-ui,sans-serif"><span class="row sb"><span>Order arriving</span><span>8 min</span></span><span style="height:6px;border-radius:3px;background:#444;position:relative"><i style="position:absolute;left:0;top:0;bottom:0;width:70%;background:#fff;border-radius:3px"></i></span></div>`],
["Widgets","Home Screen Widget","Small glanceable panels of app info placed on the home screen.",`<div class="phone" style="width:100px;padding:8px;display:grid;grid-template-columns:repeat(4,1fr);gap:5px;align-content:start"><span style="grid-column:span 4;height:38px;border-radius:10px;background:var(--ink);color:var(--paper);padding:5px;font:800 9px Archivo,sans-serif">lv. 4<br>7,421 exp</span>${'<span style="aspect-ratio:1;border-radius:6px;background:var(--soft)"></span>'.repeat(8)}</div>`],
["Bottom App Bar","Material Bottom Bar","An Android bar at the bottom of the screen holding actions, sometimes with a docked FAB.",`<div class="phone wide"><div class="row" style="position:absolute;left:0;right:0;bottom:0;padding:8px 10px;gap:12px;background:var(--soft);border-top:2px solid var(--ink)">${I('menu','s')}${I('search','s')}${I('heart','s')}<span class="cb fill sm" style="margin-left:auto;border-radius:10px">${I('plus')}</span></div></div>`],
["Predictive Back","Back Gesture Preview","Android’s back swipe that previews the screen you’ll land on before you finish the gesture.",`<span style="position:relative;display:block;width:100px;height:110px"><span class="phone" style="position:absolute;inset:0;width:100px;height:110px;opacity:.5"></span><span class="phone" style="position:absolute;left:18px;top:10px;width:76px;height:90px;box-shadow:-4px 4px 0 var(--soft)"></span><span style="position:absolute;left:2px;top:46px">${I('chl','s')}</span></span>`],
["Notification Shade","Notification Drawer","The panel pulled down from the top of an Android phone, showing notifications and quick settings.",`<div class="phone" style="width:100px"><div style="background:var(--ink);color:var(--paper);padding:6px;display:flex;flex-direction:column;gap:5px;border-radius:0 0 12px 12px"><span class="row" style="gap:4px">${'<i style="display:block;width:16px;height:16px;border-radius:50%;background:var(--paper);opacity:.5"></i>'.repeat(4)}</span><span style="height:22px;border-radius:8px;background:var(--paper);opacity:.25;display:block"></span><span style="height:22px;border-radius:8px;background:var(--paper);opacity:.25;display:block"></span></div></div>`],
["Quick Settings","Control Center","Tiles for toggling Wi-Fi, Bluetooth, the flashlight and more. iPhone calls it Control Center.",`<span style="display:grid;grid-template-columns:repeat(3,40px);gap:5px">${['wifi','bolt','sun','lock','vol','phone'].map((n,i)=>`<span style="height:40px;border-radius:12px;display:grid;place-items:center;border:2px solid var(--ink);background:${i<3?'var(--ink)':'var(--paper)'};color:${i<3?'var(--paper)':'var(--ink)'}">${I(n,'s')}</span>`).join('')}</span>`],
["Dynamic Color","Material You Theming","Android themes the whole interface with colors pulled from the user’s wallpaper.",`<span class="row" style="gap:8px"><span style="width:50px;height:80px;border-radius:10px;border:2px solid var(--ink);background:linear-gradient(160deg,#f2a65a,#7a4bb3)"></span>${SV(20,12,'<path d="M2 6h14M12 2l4 4-4 4"/>')}${SWS(['#f2a65a','#c47ab0','#7a4bb3'],22)}</span>`],
["Dock & Taskbar","App Dock","The bar of pinned and open apps on macOS (the Dock) and Windows (the Taskbar).",`<span class="row box" style="padding:6px 8px;gap:6px;border-radius:14px">${['globe','chat','film','folder','term'].map((n,i)=>`<span class="col" style="align-items:center;gap:2px"><span class="cb sm" style="border-radius:8px">${I(n)}</span><i style="display:block;width:4px;height:4px;border-radius:50%;background:${i<2?'var(--ink)':'transparent'}"></i></span>`).join('')}</span>`],
["System Tray","Menu Bar Extras","The area near the clock with small status icons for background apps.",`<span class="row box" style="padding:5px 9px;gap:9px;border-radius:8px">${I('wifi','s')}${I('vol','s')}${I('bell','s')}<span class="mono xs">9:41</span></span>`],
["Progressive Web App","PWA","A website that can be installed to the home screen and work like an app, even offline.",`<span class="row" style="gap:8px"><span class="box row" style="padding:5px 8px;gap:6px">${I('globe','s')}<span class="mono xs">fieldguide.app</span><span class="cb sm fill">${I('download')}</span></span></span>`]
]);

/* ---------- 29 emerging ---------- */
S('emerging','AI, Voice & New Interfaces','wand','Interfaces beyond the classic screen and mouse.',[
["Conversational UI","Chat Interface","An interface you use by talking or typing back and forth, like a chatbot or assistant.",`<div class="col" style="width:176px;gap:6px"><span class="b xs" style="align-self:flex-end;background:var(--ink);color:var(--paper);padding:6px 9px;border-radius:12px 12px 3px 12px">Plan my study week</span><span class="row" style="gap:6px;align-items:flex-start"><span class="logo" style="width:22px;height:22px;border-radius:7px">${SP}</span><span class="col" style="gap:4px">${L(110,'m t')}${L(90,'m t')}</span></span></div>`],
["Prompt Box","AI Composer","The input where you type a request to an AI, often with buttons to attach files and send.",`<div class="box col" style="width:184px;padding:8px;gap:8px;border-radius:16px"><span class="mono xs ph">Ask anything…</span><span class="row sb">${I('plus','s')}<span class="cb fill sm">${I('send')}</span></span></div>`],
["Suggested Prompts","Starter Chips","Example requests shown as chips so people know what they can ask.",CH(['Summarize my notes','Quiz me','Explain like I’m 5'])],
["Streaming Response","Token Streaming","AI text that appears piece by piece as it’s generated, so people can start reading sooner.",`<span class="b sm a-type" style="max-width:180px">Here is your plan for Monday</span>`],
["Response Actions","Stop, Regenerate, Copy","Controls around an AI answer: stop it mid-way, try again, copy it, or rate it.",`<div class="col" style="gap:6px;align-items:flex-start">${L(150,'m t')}${L(120,'m t')}<span class="row" style="gap:4px">${['copy','refresh','heart','x'].map(n=>CB(n,'sm')).join('')}</span></div>`],
["Citations","Source Links","Numbered links showing where an AI answer’s facts came from, so people can check them.",`<span style="display:block;width:176px;font:12px/1.6 Archivo,sans-serif">Flood risk rises in July <span class="chip sm" style="height:16px">1</span> and peaks after typhoons <span class="chip sm" style="height:16px">2</span>.</span>`],
["AI Disclosure","AI Label","A clear label that content was created or changed by AI.",`<span class="row" style="gap:8px"><span class="chip on">${SP} AI-generated</span><span class="mono xs">image</span></span>`],
["Thinking Indicator","Reasoning Indicator","A status showing the AI is working, often naming the step it’s on.",`<span class="row b sm" style="gap:8px"><span class="row a-dots" style="gap:4px">${[0,1,2].map(i=>`<i style="display:block;width:8px;height:8px;border-radius:50%;background:var(--ink);animation-delay:${i*.15}s"></i>`).join('')}</span>Searching sources…</span>`],
["Generative UI","Dynamic UI","Interface parts generated on the fly to fit a request, like a chart or a form built inside the chat.",`<div class="box col" style="padding:8px;gap:6px;width:176px;border-radius:14px"><span class="mono xs">Here’s your progress:</span><span class="box" style="padding:4px;line-height:0">${SV(150,40,'<path d="M2 36L30 28 58 30 86 16 114 18 148 4"/>')}</span></div>`],
["Voice User Interface","VUI","Controlling software by speaking, like smart speakers and voice assistants.",`<span class="row" style="gap:10px">${CB('mic','fill')}<span class="wave">${[6,14,22,12,26,16,8,18,10].map(h=>`<i style="height:${h}px"></i>`).join('')}</span></span>`],
["Wake Word","Hotword","The phrase that starts a voice assistant listening.",`<span class="row" style="gap:8px"><span class="cb fill a-pulse" style="width:44px;height:44px">${I('mic')}</span><span class="pop" style="padding:5px 8px"><span class="mono xs">“Hey, Guide…”</span></span></span>`],
["Multimodal Input","Multimodal","Using several kinds of input together, such as voice, text, images and touch.",`<span class="row" style="gap:6px">${['type','mic','img','hand'].map(n=>CB(n)).join('')}</span>`],
["Augmented Reality","AR","Digital objects placed over a live camera view of the real world.",`<div class="phone" style="width:100px;background:linear-gradient(#cfd8dc,#90a4ae)"><span style="position:absolute;left:0;right:0;bottom:0;height:40px;background:#78909c"></span><span style="position:absolute;left:30px;top:36px;color:var(--ink)">${SV(40,40,'<path d="M20 4l16 9v14l-16 9-16-9V13zM20 22l16-9M20 22v14M20 22L4 13" fill="var(--paper)"/>')}</span></div>`],
["Virtual Reality","VR","A fully computer-made world seen through a headset.",SV(140,70,'<rect x="10" y="14" width="120" height="44" rx="16" fill="var(--paper)"/><circle cx="46" cy="36" r="13" fill="currentColor"/><circle cx="94" cy="36" r="13" fill="currentColor"/><path d="M62 52q8-8 16 0"/>')],
["Spatial UI","Spatial Computing","Interfaces floating in 3D space around you, controlled with eyes, hands and voice, like Apple Vision Pro.",`<span style="display:block;position:relative;width:170px;height:90px;perspective:300px">${[[-30,10,'rotateY(25deg)'],[50,0,'none'],[124,10,'rotateY(-25deg)']].map(([x,y,t])=>`<span style="position:absolute;left:${x+20}px;top:${y+10}px;width:${x===50?70:44}px;height:${x===50?60:48}px;border-radius:12px;background:color-mix(in srgb,var(--paper) 70%,transparent);border:2px solid var(--ink);transform:${t};backdrop-filter:blur(4px)"></span>`).join('')}</span>`],
["Wearable UI","Smartwatch UI","Tiny, glanceable screens on watches and bands, built for interactions that last seconds.",`<span class="row" style="gap:0;flex-direction:column;align-items:center"><span style="width:24px;height:16px;background:var(--soft);border-radius:4px 4px 0 0"></span><span style="width:70px;height:78px;border-radius:20px;border:3px solid var(--ink);background:#000;display:grid;place-items:center">${SV(52,52,'<circle cx="26" cy="26" r="20" stroke="#333" stroke-width="6"/><path d="M26 6a20 20 0 1 1-19 26" stroke="#ff375f" stroke-width="6"/>')}</span><span style="width:24px;height:16px;background:var(--soft);border-radius:0 0 4px 4px"></span></span>`],
["10-foot UI","TV Interface","TV interfaces seen from the couch and driven by a remote: big text, a clear focus highlight and simple grids.",`<div style="width:176px;height:100px;border-radius:8px;border:3px solid var(--ink);background:#151515;padding:10px;display:grid;grid-template-columns:repeat(3,1fr);gap:6px;align-content:center">${[0,1,2].map(i=>`<span style="height:46px;border-radius:6px;background:#444;${i===1?'outline:3px solid #fff;transform:scale(1.1)':''}"></span>`).join('')}</div>`],
["Automotive UI","In-car Interface","Car dashboard and infotainment screens designed for quick glances and minimal distraction.",`<div style="width:180px;height:84px;border-radius:12px;border:2px solid var(--ink);background:#101418;display:grid;grid-template-columns:1.4fr 1fr;gap:6px;padding:6px"><span style="border-radius:6px;background:#26323a;position:relative"><i style="position:absolute;left:20%;top:30%;right:20%;height:4px;background:#5ac8fa;border-radius:2px;transform:rotate(-20deg)"></i></span><span style="display:grid;gap:6px">${'<span style="border-radius:6px;background:#2b2f33"></span>'.repeat(2)}</span></div>`],
["Command-line Interface","CLI","Typing text commands into a terminal.",`<pre class="code" style="font-size:10px">$ npm run dev
<span class="cm">▲ ready on localhost:3000</span>
$ <span class="caret" style="background:var(--paper);height:11px"></span></pre>`],
["Text-based UI","TUI","Full interfaces drawn with characters inside a terminal, with menus and panels.",`<pre class="code" style="font-size:9.5px;line-height:1.25">┌─ Files ──┬─ Preview ─┐
│ ▸ src    │ hello.js  │
│   index  │ console…  │
└──────────┴───────────┘</pre>`],
["Zero UI","Ambient Interface","Interactions with no screen at all, through voice, gestures, sensors or automatic routines.",`<span style="position:relative;display:grid;place-items:center;width:90px;height:90px">${[80,58,36].map(s=>`<i style="position:absolute;width:${s}px;height:${s}px;border-radius:50%;border:2px solid var(--ink);opacity:${s/100}"></i>`).join('')}<i style="width:14px;height:14px;border-radius:50%;background:var(--ink)"></i></span>`],
["Gesture Control","Air Gestures","Controlling devices with hand movements in the air, tracked by cameras or sensors.",`<span class="row" style="gap:6px">${I('hand','lg')}${SV(40,30,'<path d="M4 20q16-16 32 0" stroke-dasharray="3 4"/><path d="M30 14l6 6-8 2"/>')}</span>`]
]);

/* ---------- 30 design tools ---------- */
S('tools','Design Tool Terms','crop','Words you’ll hear inside Figma and similar design tools.',[
["Layer","Layers Panel","Every object in a design file, listed in a panel where you can reorder, hide and lock them.",`<div class="lbx" style="min-width:150px">${[['Header','eye'],['Button','eye'],['Background','lock']].map(([t,i],k)=>`<span class="row sb ${k===1?'on':''}">${t}${I(i,'xs')}</span>`).join('')}</div>`],
["Group","Grouping","Bundling layers so they move together, without adding any layout rules.",`<span style="display:inline-flex;gap:6px;padding:8px;border:1.5px dashed var(--ink);border-radius:6px"><i style="display:block;width:26px;height:26px;border-radius:50%;background:var(--ink)"></i><i style="display:block;width:36px;height:26px;border-radius:6px;background:var(--mute)"></i></span>`],
["Constraints","Resizing Rules","Rules for how a layer moves or stretches when its frame resizes, such as pinned to the left and right.",`<div class="frame" style="width:150px;height:80px"><span class="box" style="position:absolute;left:24px;right:24px;top:28px;height:24px;background:var(--soft)"></span><span style="position:absolute;left:0;width:24px;top:40px;border-top:1.5px solid var(--danger)"></span><span style="position:absolute;right:0;width:24px;top:40px;border-top:1.5px solid var(--danger)"></span><span class="mono xs" style="position:absolute;left:50%;transform:translateX(-50%);bottom:4px">left + right</span></div>`],
["Mask","Clip Content","Using one shape to show only part of another, like a photo inside a circle.",`<span class="row" style="gap:8px"><span style="width:60px;height:60px;border-radius:50%;overflow:hidden;border:2px solid var(--ink);background:linear-gradient(160deg,#f2a65a,#7a4bb3)"></span><span class="mono xs">circle mask<br>over a photo</span></span>`],
["Boolean Operations","Union, Subtract, Intersect, Exclude","Combining two shapes into a new one by adding, cutting, overlapping or excluding.",`<span class="row" style="gap:8px">${['union','subtract','intersect','exclude'].map((op,i)=>`<span class="col" style="align-items:center;gap:3px">${SV(36,28,`<defs><clipPath id="cA${i}"><circle cx="13" cy="14" r="10"/></clipPath><clipPath id="cB${i}"><circle cx="23" cy="14" r="10"/></clipPath></defs>${i===0?'<circle cx="13" cy="14" r="10" fill="currentColor" stroke="none"/><circle cx="23" cy="14" r="10" fill="currentColor" stroke="none"/>':i===1?'<circle cx="13" cy="14" r="10" fill="currentColor" stroke="none"/><circle cx="23" cy="14" r="10" fill="var(--bg)" stroke="none"/>':i===2?`<circle cx="23" cy="14" r="10" fill="currentColor" stroke="none" clip-path="url(#cA${i})"/>`:`<circle cx="13" cy="14" r="10" fill="currentColor" stroke="none"/><circle cx="23" cy="14" r="10" fill="currentColor" stroke="none"/><circle cx="23" cy="14" r="10" fill="var(--bg)" stroke="none" clip-path="url(#cA${i})"/>`}`)}${LB(op)}</span>`).join('')}</span>`],
["Vector Path","Path","A shape made of points joined by straight or curved segments.",SV(150,70,'<path d="M10 56L40 14 90 50 140 16"/><g fill="var(--paper)" stroke-width="2"><rect x="6" y="52" width="8" height="8"/><rect x="36" y="10" width="8" height="8"/><rect x="86" y="46" width="8" height="8"/><rect x="136" y="12" width="8" height="8"/></g>')],
["Pen Tool","Bézier Tool","The tool for drawing paths point by point; click for corners, drag to make curves.",`<span class="row" style="gap:8px">${I('pen','lg')}${SV(110,60,'<path d="M6 50C30 0 70 0 104 40" stroke-dasharray="1 0"/><rect x="2" y="46" width="8" height="8" fill="var(--paper)" stroke-width="2"/>')}</span>`],
["Anchor Points & Handles","Bézier Handles","Anchor points are where a path bends; handles stick out from them and control the curve.",SV(170,80,'<path d="M10 70C40 10 130 10 160 70"/><path d="M10 70L40 10M160 70L130 10" stroke-width="1.5" opacity=".55"/><circle cx="40" cy="10" r="4" fill="var(--paper)" stroke-width="2"/><circle cx="130" cy="10" r="4" fill="var(--paper)" stroke-width="2"/><rect x="6" y="66" width="8" height="8" fill="currentColor"/><rect x="156" y="66" width="8" height="8" fill="currentColor"/>')],
["Snapping","Smart Guides","Objects jump into alignment with edges, centers and even spacing as you drag, with guide lines appearing.",`<span style="position:relative;display:block;width:160px;height:80px"><span class="box" style="position:absolute;left:10px;top:10px;width:50px;height:30px"></span><span class="box" style="position:absolute;left:90px;top:10px;width:50px;height:50px;background:var(--soft)"></span><span style="position:absolute;left:0;right:0;top:10px;border-top:1.5px solid #e03ea1"></span>${CUR(120,36)}</span>`],
["Guides & Rulers","Ruler Guides","Rulers along the canvas edges and guide lines you drag out of them to align things.",`<div class="frame" style="padding:0"><span style="position:absolute;left:0;right:0;top:0;height:12px;border-bottom:1.5px solid var(--ink);background:repeating-linear-gradient(90deg,var(--ink) 0 1px,transparent 1px 10px);opacity:.6"></span><span style="position:absolute;left:0;top:0;bottom:0;width:12px;border-right:1.5px solid var(--ink);background:repeating-linear-gradient(0deg,var(--ink) 0 1px,transparent 1px 10px);opacity:.6"></span><span style="position:absolute;left:70px;top:12px;bottom:0;border-left:1.5px solid #2f8fff"></span></div>`],
["Styles","Shared Styles","Saved colors, text, effects and grids reused across a file, so one change updates everywhere.",`<div class="lbx" style="min-width:150px">${[['var(--ink)','Ink / Primary'],['#c8372d','Danger'],['', 'Heading / H1']].map(([c,t])=>`<span class="row" style="gap:6px">${c?SW(c,12):'<b class="fr" style="font-size:11px">Ag</b>'}${t}</span>`).join('')}</div>`],
["Library","Team Library","Shared components and styles published once for a whole team to use.",`<div class="box col" style="padding:8px;gap:6px;width:160px"><span class="row sb"><b class="b xs">Field Guide UI</b><span class="chip sm on">Published</span></span><span class="row" style="gap:5px">${B('Btn','fill xs')}<span class="tg on" style="transform:scale(.7)"></span><span class="chk on">${I('check')}</span></span></div>`],
["Variables & Modes","Design Variables","Stored values like colors and numbers, with modes such as light and dark that swap them all at once.",`<table class="tbl"><tr><th>Name</th><th>Light</th><th>Dark</th></tr><tr><td>bg</td><td>${SW('#f4f1ea',12)}</td><td>${SW('#121110',12)}</td></tr><tr><td>ink</td><td>${SW('#000',12)}</td><td>${SW('#f4f0e6',12)}</td></tr></table>`],
["Interactive Components","Component Interactions","Components with prototype behavior built in, like a toggle that switches itself when clicked.",`<span class="row" style="gap:10px"><span class="tg"></span>${SV(30,20,'<path d="M4 6h20M20 2l4 4-4 4M26 14H6M10 10l-4 4 4 4"/>')}<span class="tg on"></span></span>`],
["Smart Animate","Auto-animate","Automatically animating layers with matching names between two frames in a prototype.",`<span class="row" style="gap:8px">${MINI('<i style="display:block;width:16px;height:16px;border-radius:4px;background:var(--ink)"></i>',46,70)}${SV(24,12,'<path d="M2 6h18M16 2l4 4-4 4"/>')}${MINI('<i style="display:block;width:34px;height:34px;border-radius:50%;background:var(--ink);margin:auto"></i>',46,70)}</span>`],
["Prototype Triggers","On Click, On Hover, After Delay","The event that starts a prototype interaction, like a click, a hover, a key press or a timer.",CH(['On click','On hover','While pressing','Key/Gamepad','After delay'],0)],
["Export Settings","Export, Slices","Choosing which layers to save as PNG, JPG, SVG or PDF, and at what scale.",`<div class="lbx" style="min-width:150px">${[['1x','PNG'],['2x','PNG'],['—','SVG']].map(([s,f])=>`<span class="row sb">${s}<b>${f}</b></span>`).join('')}<span class="on" style="text-align:center">Export icon</span></div>`],
["Plugins","Extensions","Add-on tools that extend a design app, like icon packs, contrast checkers or content generators.",`<span class="row" style="gap:8px">${CB('puzzle','fill')}${CH(['Icons','Contrast','Lorem'])}</span>`],
["Version History","Versions","Saved snapshots of a file that you can view or restore.",`<div class="tl">${['Today 3:14pm','Yesterday','Sep 30, v1.0'].map((t,i)=>`<span class="row"><i class="${i?'':'on'}"></i><span class="mono xs">${t}</span></span>`).join('')}</div>`],
["Dev Mode","Inspect Panel","A view where developers read sizes, spacing, styles and code snippets straight from a design.",CODE(`width: 148px;
height: 32px;
border-radius: 99px;
background: #000;`)],
["Blend Modes","Multiply, Screen, Overlay","Rules for how a layer’s colors mix with the layers underneath.",`<span style="position:relative;display:block;width:90px;height:60px"><i style="position:absolute;left:0;top:0;width:56px;height:56px;border-radius:50%;background:#f2c14e"></i><i style="position:absolute;left:32px;top:0;width:56px;height:56px;border-radius:50%;background:#2fb7e8;mix-blend-mode:multiply"></i></span>`],
["Effects","Shadow, Blur","Visual effects added to layers, such as drop shadows, inner shadows, layer blur and background blur.",`<span class="row" style="gap:14px"><span class="box" style="width:50px;height:40px;box-shadow:0 8px 16px rgba(0,0,0,.25)"></span><span class="box" style="width:50px;height:40px;background:var(--ink);filter:blur(3px)"></span></span>`],
["Pixel Grid","Pixel Snapping","The grid of single pixels visible at high zoom. Snapping to it keeps edges crisp.",`<span style="display:block;width:120px;height:80px;border-radius:6px;background:repeating-linear-gradient(90deg,color-mix(in srgb,var(--ink) 20%,transparent) 0 1px,transparent 1px 10px),repeating-linear-gradient(0deg,color-mix(in srgb,var(--ink) 20%,transparent) 0 1px,transparent 1px 10px),var(--paper);position:relative;border:2px solid var(--ink)"><i style="position:absolute;left:30px;top:20px;width:50px;height:30px;background:var(--ink)"></i></span>`],
["Multiplayer Editing","Live Collaboration","Several people editing the same file at once, each with a named cursor.",`<span style="position:relative;display:block;width:160px;height:80px">${[['JM','#2f5fd0',20,10],['KC','#c8372d',100,40]].map(([n,c,x,y])=>`<span style="position:absolute;left:${x}px;top:${y}px;display:flex;align-items:flex-start;gap:2px">${SV(14,14,`<path d="M2 2v10l3-3 2 4 2-1-2-4h4z" fill="${c}" stroke="${c}"/>`)}<span style="background:${c};color:#fff;font:700 9px Archivo,sans-serif;padding:1px 5px;border-radius:4px;margin-top:8px">${n}</span></span>`).join('')}</span>`]
]);

/* ---------- 31 motion graphics ---------- */
S('ae','Motion Graphics Tool Terms','film','After Effects and Alight Motion vocabulary for animating UI and video.',[
["Composition","Comp","A container with its own size, frame rate and length where you build an animation, like a scene.",`<div class="frame col" style="justify-content:center;align-items:center;gap:4px"><b class="b xs">Comp 1</b><span class="mono xs">1920×1080, 30fps, 0:10</span></div>`],
["Timeline","Layer Timeline","The panel where layers are stacked as bars across time.",`<div class="col" style="gap:4px;width:176px">${[['Title',10,80],['Button',40,110],['BG',0,170]].map(([t,s,w])=>`<span class="row" style="gap:6px"><span class="mono xs" style="width:34px">${t}</span><span style="position:relative;flex:1;height:12px;background:var(--soft);border-radius:3px"><i style="position:absolute;left:${s*.75}px;width:${w*.75}px;top:0;bottom:0;background:var(--mute);border-radius:3px"></i></span></span>`).join('')}</div>`],
["Playhead","Current Time Indicator","The vertical line marking the current frame on the timeline.",`<div style="position:relative;width:170px;height:60px;border-top:2px solid var(--ink)">${Array.from({length:9},(_,i)=>`<span class="mono" style="position:absolute;left:${i*20}px;top:2px;font-size:7px">${i}s</span>`).join('')}<span style="position:absolute;left:84px;top:-8px;bottom:0;width:2px;background:#2f8fff"></span><span style="position:absolute;left:78px;top:-10px;width:14px;height:10px;background:#2f8fff;clip-path:polygon(0 0,100% 0,50% 100%)"></span></div>`],
["Keyframe Interpolation","Linear, Bezier, Hold","How values change between keyframes: steadily (linear), smoothly (Bezier), or jumping at the next key (hold).",`<span class="row" style="gap:14px">${[['linear','<path d="M10 2l8 8-8 8-8-8z"/>'],['bezier','<path d="M10 2c4 5 8 8 0 16C2 10 6 7 10 2z"/>'],['hold','<path d="M3 3h14v14H3z"/>']].map(([l,p])=>`<span class="col" style="align-items:center;gap:4px">${SV(20,20,p.replace('/>',' fill="currentColor"/>'))}${LB(l)}</span>`).join('')}</span>`],
["Easy Ease","F9","After Effects’ one-click ease that slows motion into and out of keyframes.",`<span class="row" style="gap:10px"><span class="kbd">F9</span>${SV(80,50,'<path d="M4 46C40 46 40 4 76 4"/>')}</span>`],
["Graph Editor","Speed Graph, Value Graph","A view showing how speed or value changes over time, where you shape easing by dragging handles.",SV(176,90,'<path d="M8 84h164M8 84V4" stroke-width="1.5" opacity=".4"/><path d="M10 80C70 80 50 10 100 10S150 80 168 80"/><path d="M10 80h40M100 10h-24M100 10h24M168 80h-20" stroke-width="1.5" stroke="#2f8fff"/><circle cx="50" cy="80" r="3" fill="#2f8fff" stroke="none"/><circle cx="76" cy="10" r="3" fill="#2f8fff" stroke="none"/><circle cx="124" cy="10" r="3" fill="#2f8fff" stroke="none"/>')],
["Precompose","Precomp, Nesting","Moving several layers into their own composition so you can treat them as one layer.",`<span class="row" style="gap:8px"><span class="col" style="gap:3px">${'<span class="box" style="width:50px;height:12px;border-radius:3px"></span>'.repeat(3)}</span>${SV(20,12,'<path d="M2 6h14M12 2l4 4-4 4"/>')}<span class="box mono xs" style="width:60px;height:42px;display:grid;place-items:center;background:var(--soft)">Pre-comp</span></span>`],
["Null Object","Null","An invisible layer used as a controller that other layers follow.",SV(150,80,'<rect x="60" y="6" width="30" height="30" stroke-dasharray="4 3" stroke="#c8372d"/><path d="M75 36L30 62M75 36v26M75 36l45 26" stroke-width="1.5" opacity=".6"/><circle cx="30" cy="66" r="8" fill="currentColor"/><rect x="67" y="60" width="16" height="16" fill="currentColor"/><path d="M120 58l9 16h-18z" fill="currentColor"/>')],
["Parenting","Parent & Link","Linking a layer to another so it follows the parent’s position, scale and rotation.",`<span class="row" style="gap:8px"><span class="box mono xs" style="padding:6px 8px">Arm</span>${SV(40,16,'<path d="M2 8c8-8 16 8 24 0s8-4 12 0" stroke-width="1.8"/>')}<span class="box mono xs" style="padding:6px 8px;background:var(--ink);color:var(--paper)">Body</span></span>`],
["Track Matte","Alpha Matte, Luma Matte","Using one layer’s transparency or brightness to show or hide the layer below it.",`<span style="font:900 42px Archivo,sans-serif;background:linear-gradient(90deg,#f2a65a,#7a4bb3,#2f8fff);-webkit-background-clip:text;background-clip:text;color:transparent;line-height:1">MATTE</span>`],
["Shape Layer","Vector Layer","A layer of vector shapes you can animate with built-in properties like trim paths and repeater.",`<span class="row" style="gap:10px">${SV(40,40,'<path d="M20 4l16 32H4z" fill="currentColor"/>')}<div class="lbx" style="min-width:96px;font-size:10px"><span>▾ Shape 1</span><span style="padding-left:18px">Path</span><span style="padding-left:18px">Fill</span><span style="padding-left:18px" class="on">Trim Paths</span></div></span>`],
["Trim Paths","Stroke Reveal","Animating a stroke’s start and end so a line draws itself on.",SV(160,70,'<path class="a-trim" d="M10 50C40 0 70 70 100 30S150 10 150 50" stroke-width="4"/>')],
["Expressions","Code-driven Animation","Short JavaScript snippets on a property that create motion without keyframes, like wiggle(2, 30).",`<span class="row" style="gap:12px"><span class="ab a-wig" style="width:30px;height:30px;border-radius:8px"></span>${CODE('wiggle(2, 30)')}</span>`],
["Motion Tracking","Tracking","Following a moving point in footage so graphics can stick to it.",`<div class="frame" style="background:linear-gradient(#b0bec5,#78909c)">${SV(176,104,'<path d="M20 80C60 60 90 70 150 30" stroke="#fff" stroke-dasharray="3 4" stroke-width="1.5"/>').replace('<svg','<svg style="position:absolute;inset:0"')}<span style="position:absolute;left:138px;top:18px;width:24px;height:24px;border:2px solid #ffeb3b"></span><span style="position:absolute;left:146px;top:26px;width:8px;height:8px;border:1.5px solid #ffeb3b"></span></div>`],
["Render Queue","Export Queue","Where you choose output format and settings, then render the final video.",`<div class="col" style="gap:5px;width:176px">${[['intro.mp4',100],['outro.mp4',45]].map(([n,p])=>`<span class="box row" style="padding:5px 8px;gap:8px"><span class="mono xs" style="width:60px">${n}</span><span class="pbar thin" style="flex:1;height:8px"><i style="width:${p}%"></i></span></span>`).join('')}</div>`]
]);

/* ---------- 32 writing ---------- */
S('writing','UX Writing & Content','chat','Words are part of the design.',[
["Microcopy","Interface Copy","The small bits of text in an interface: button labels, hints, errors and confirmations.",`<div class="col" style="gap:5px;align-items:flex-start"><span class="mono xs ph">We’ll never post without asking.</span>${B('Connect account','fill sm')}</div>`],
["Voice & Tone","Brand Voice","Voice is a product’s steady personality; tone adapts it to the moment, calmer for errors and lighter for wins.",`<div class="col" style="gap:6px;width:176px"><span class="pop" style="padding:5px 8px"><span class="mono xs">Level up! You’re on fire ✦</span></span><span class="pop" style="padding:5px 8px"><span class="mono xs">Payment failed. Nothing was charged.</span></span></div>`],
["Button Labels","Action Labels","Start with a verb that says exactly what happens: Save changes, not Submit or OK.",GB('OK','Delete 3 files')],
["Error Messages","Error Copy","Say what went wrong and how to fix it, without blaming the user or using jargon.",GB('Invalid input!','Use 8 or more characters')],
["Empty State Copy","Zero State Copy","Tell people what will appear here and how to get started.",`<div class="col" style="align-items:center;gap:4px">${I('folder','lg')}<b class="b xs">Your saved quests show up here</b><span class="btn xs fill">Browse quests</span></div>`],
["Confirmation Copy","Success Message","Confirm what happened using the same word as the action: Publish becomes Published.",`<span class="row" style="gap:8px">${B('Publish','fill sm')}${SV(20,12,'<path d="M2 6h14M12 2l4 4-4 4"/>')}<span class="toast" style="position:static;transform:none">${I('check','xs')} Published</span></span>`],
["Sentence Case vs Title Case","Capitalization","Sentence case capitalizes only the first word and is easier to read. Title Case Capitalizes Every Word.",`<div class="col" style="gap:6px"><span class="row b sm" style="gap:6px">${LB('sentence')}Save your progress</span><span class="row b sm" style="gap:6px">${LB('title')}Save Your Progress</span></div>`],
["Scannability","Skimmable Text","Front-load key words and use short paragraphs, headings and lists so people can skim.",`<span class="row" style="gap:10px;align-items:flex-start"><span class="col" style="gap:3px">${'<i class="ln m t" style="width:66px"></i>'.repeat(7)}</span><span class="col" style="gap:4px">${L(50)}${L(60,'m t')}${L(40)}${L(56,'m t')}</span></span>`],
["Localization","l10n","Adapting a product for a language and region: translation, formats, currency and imagery.",`<div class="col" style="gap:4px">${[['EN','Save'],['ES','Guardar'],['TL','I-save'],['JA','保存']].map(([l,t])=>`<span class="row" style="gap:8px"><span class="chip sm" style="width:30px;justify-content:center">${l}</span>${B(t,'fill xs')}</span>`).join('')}</div>`],
["Internationalization","i18n","Building a product so it can be localized later without redesign, like leaving room for longer words.",`<div class="col" style="gap:5px;align-items:flex-start">${B('Settings','fill sm')}${B('Einstellungen','fill sm')}${LB('German is ~30% longer')}</div>`],
["Right-to-Left","RTL","Languages like Arabic and Hebrew read from right to left, so layouts mirror.",`<div class="frame col" dir="rtl" style="padding:9px;gap:6px"><span class="row" style="gap:6px">${I('chr','s')}<b style="font:700 13px system-ui,sans-serif">الإعدادات</b></span>${L(110,'m t')}${L(80,'m t')}</div>`],
["Pluralization","Plural Rules","Writing messages that handle counts correctly, such as 1 item and 2 items. Other languages have more plural forms.",GB('1 items left','1 item left')],
["Date, Time & Number Formats","Locale Formats","The same value is written differently by region, like 10/04/2026 versus 04/10/2026, and 1,000.50 versus 1.000,50.",`<table class="tbl"><tr><th></th><th>US</th><th>EU</th></tr><tr><td>Date</td><td>10/04/26</td><td>04/10/26</td></tr><tr><td>Number</td><td>1,000.50</td><td>1.000,50</td></tr><tr><td>Time</td><td>2:30 PM</td><td>14:30</td></tr></table>`],
["Placeholder Content","Lorem Ipsum","Dummy text used before real content exists. Real copy early reveals layout problems sooner.",`<span style="display:block;width:160px;font:12px/1.4 Georgia,serif;color:var(--mute)">Lorem ipsum dolor sit amet, consectetur adipiscing elit.</span>`]
]);

/* ---------- 33 dev ---------- */
S('dev','Code & Build Terms','term','Developer words you’ll hear during handoff.',[
["HTML","Markup","The language that gives a web page its structure and meaning: headings, buttons, lists and forms.",CODE(`&lt;h1&gt;Paladin&lt;/h1&gt;
&lt;button&gt;Level up&lt;/button&gt;`)],
["CSS","Stylesheet","The language that controls how HTML looks: color, type, spacing, layout and animation.",CODE(`.btn {
  border-radius: 99px;
  background: #000;
}`)],
["JavaScript","JS","The language that makes web pages interactive.",CODE(`button.onclick = () =&gt; {
  hero.level++;
};`)],
["DOM","Document Object Model","The live tree of elements the browser builds from HTML, which code reads and changes.",`<div class="col mono xs tree" style="gap:3px"><span>html</span><span style="padding-left:12px">└ body</span><span style="padding-left:24px">└ main</span><span style="padding-left:36px">├ h1</span><span style="padding-left:36px">└ button</span></div>`],
["Component (Code)","UI Component","A reusable piece of code for one part of the interface, matching a component in the design file.",CODE(`&lt;Button variant="primary"&gt;
  Increase level
&lt;/Button&gt;`)],
["Props","Properties","Settings passed into a component, like its label, size or variant. They match a design component’s properties.",`<div class="col" style="gap:6px;align-items:center">${CODE('size="sm"  variant="outline"')}${B('Save','sm')}</div>`],
["State","Component State","Data that changes while the app runs, like whether a toggle is on. Each visual state needs a design.",`<span class="row" style="gap:10px"><button type="button" class="tg on" data-tg aria-label="Toggle state"></button>${CODE('isOn: true')}</span>`],
["Event","Event Handler","Something that happens, like a click, a key press or a scroll, that code can respond to.",`<span class="row" style="gap:10px"><span style="position:relative">${B('Play','fill')}${CUR(40,14)}</span>${CODE('onClick')}</span>`],
["Framework","React, Vue, SwiftUI, Flutter","Toolkits for building interfaces from components. A good design system maps cleanly onto them.",CH(['React','Vue','Svelte','SwiftUI','Jetpack Compose','Flutter'])],
["Storybook","Component Workshop","A tool that shows every coded component and its states on its own, like a living design system.",`<div class="frame" style="display:flex"><div class="side col" style="width:64px;font:9px Courier Prime,monospace;gap:4px"><span>Button</span><b>Toggle</b><span>Card</span></div><div style="flex:1;display:grid;place-items:center"><span class="tg on"></span></div></div>`],
["Responsive Images","srcset","Serving different image sizes for different screens so phones don’t download huge files.",CODE(`&lt;img srcset="
  hero-480.jpg 480w,
  hero-1200.jpg 1200w"&gt;`)],
["Core Web Vitals","LCP, INP, CLS","Google’s page experience metrics: Largest Contentful Paint for loading, Interaction to Next Paint for responsiveness, and Cumulative Layout Shift for visual stability.",`<div class="col" style="gap:4px">${[['LCP','≤ 2.5 s'],['INP','≤ 200 ms'],['CLS','≤ 0.1']].map(([m,v])=>`<span class="row" style="gap:8px"><span class="chip sm on" style="width:38px;justify-content:center">${m}</span><span class="mono xs">good: ${v}</span></span>`).join('')}</div>`],
["Layout Shift","Content Jump","When content moves after loading, like a button jumping down as an image appears. Reserve space to prevent it.",`<span class="row" style="gap:8px">${SCR(`${L(60)}${B('Buy','fill xs')}`,70,80)}${SV(20,12,'<path d="M2 6h14M12 2l4 4-4 4"/>')}${SCR(`${L(60)}<span style="height:30px;background:var(--soft);border-radius:4px;display:block"></span>${B('Buy','fill xs')}`,70,80)}</span>`],
["Lighthouse","Page Audit","A free Google tool that scores a page’s performance, accessibility, best practices and SEO.",`<span class="row" style="gap:6px">${[98,100,92,100].map((s,i)=>`<span class="col" style="align-items:center;gap:3px"><span style="width:36px;height:36px;border-radius:50%;border:3px solid #2e9d5b;display:grid;place-items:center;font:700 11px Courier Prime,monospace;color:#2e9d5b">${s}</span><span class="mono" style="font-size:7px">${['Perf','A11y','Best','SEO'][i]}</span></span>`).join('')}</span>`],
["Version Control","Git","Tracking changes to code over time with commits and branches, so a team can work in parallel.",SV(160,70,'<path d="M10 50h140"/><path d="M50 50C60 20 80 20 90 20h20c10 0 20 0 30 30" stroke-dasharray="1 0"/><circle cx="20" cy="50" r="6" fill="currentColor"/><circle cx="50" cy="50" r="6" fill="currentColor"/><circle cx="90" cy="20" r="6" fill="var(--paper)"/><circle cx="120" cy="20" r="6" fill="var(--paper)"/><circle cx="140" cy="50" r="6" fill="currentColor"/>')]
]);
